INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f68d3c62-8832-4d5a-aa3c-ccd33f9e1d91', '閑居即事', '闲居即事', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["深嶂多幽景，閑居野興清。","滿庭秋雨過，連夜綠苔生。","石面橫琴坐，松陰採藥行。","超然塵事外，不似絆浮名。"]', '["深嶂多幽景，闲居野兴清。","满庭秋雨過，連夜綠苔生。","石面橫琴坐，松陰採藥行。","超然塵事外，不似絆浮名。"]', '诗', 'shi', '', NULL, '閑居即事 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f62de444-00b3-4afa-bbbf-896f148ce8cf', '廢宅花', '廢宅花', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["數樹荒庭上，芬芳映綠苔。","自緣逢暖發，不是爲人開。","色豔鶯猶在，香消蝶已回。","相從無勝事，誰向此傾桮。"]', '["數樹荒庭上，芬芳映綠苔。","自緣逢暖發，不是爲人开。","色豔鶯猶在，香消蝶已回。","相從無勝事，誰向此傾桮。"]', '诗', 'shi', '', NULL, '廢宅花 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3bd9077-ad1c-40e8-b223-60440ac5b5af', '寄友人', '寄友人', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["當代知音少，相思在此身。","一分南北路，長問往來人。","是處應爲客，何門許掃塵。","憑書正惆悵，蜀魄數聲新。"]', '["當代知音少，相思在此身。","一分南北路，长问往来人。","是处應爲客，何门許掃塵。","憑书正惆悵，蜀魄數声新。"]', '诗', 'shi', '', NULL, '寄友人 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93a7537a-e725-4b7b-8670-a6c82d898c6c', '塗中感懷', '塗中感懷', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["世上名利牽，塗中意慘然。","到家能幾日，爲客便經年。","跡似萍隨水，情同鶴在田。","何當功業遂，歸路下遙天。"]', '["世上名利牽，塗中意慘然。","到家能幾日，爲客便經年。","跡似萍隨水，情同鹤在田。","何當功業遂，归路下遙天。"]', '诗', 'shi', '', NULL, '塗中感懷 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81b32160-4eaa-4765-8824-ef33e4ae353e', '贈道者', '贈道者', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["獨住神仙境，門當瀑布開。","地多臨水石，行不惹塵埃。","風起松花散，琴鳴鶴翅回。","還歸九天上，時有故人來。"]', '["独住神仙境，门當瀑布开。","地多臨水石，行不惹塵埃。","风起松花散，琴鳴鹤翅回。","還归九天上，时有故人来。"]', '诗', 'shi', '', NULL, '贈道者 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f55a124-08bc-440e-aee3-a721e7a60b44', '長安春日野中', '长安春日野中', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["青春思楚地，閑步出秦城。","滿眼是岐路，何年見弟兄。","煙霞裝媚景，霄漢指前程。","盡日徘徊處，歸鴻過玉京。"]', '["青春思楚地，闲步出秦城。","满眼是岐路，何年见弟兄。","煙霞裝媚景，霄漢指前程。","尽日徘徊处，归鴻過玉京。"]', '诗', 'shi', '', NULL, '長安春日野中 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c299babc-97c9-4c53-bfdb-be76eb96c076', '長城', '长城', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["秦帝防胡虜，關心倍可嗟。","一人如有德，四海盡爲家。","往事乾坤在，荒基草木遮。","至今徒者骨，猶自哭風沙。"]', '["秦帝防胡虜，关心倍可嗟。","一人如有德，四海尽爲家。","往事乾坤在，荒基草木遮。","至今徒者骨，猶自哭风沙。"]', '诗', 'shi', '', NULL, '長城 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8f38d88-a7dd-41c0-ba93-020831fe7d75', '酬李躔侍御', '酬李躔侍御', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["此去非關興，君行不當遊。","無因兩處馬，共飲一溪流。"]', '["此去非关兴，君行不當游。","無因兩处马，共饮一溪流。"]', '诗', 'shi', '', NULL, '酬李躔侍御 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffb49fbd-d3cd-45a7-9fb9-9774444eeacb', '別李侍御後亭夜坐却寄', '別李侍御後亭夜坐却寄', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["已作亭下別，未忘燈下情。","吟今欲就枕，更漏轉分明。"]', '["已作亭下別，未忘灯下情。","吟今欲就枕，更漏轉分明。"]', '诗', 'shi', '', NULL, '別李侍御後亭夜坐却寄 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7df188b7-5728-4d57-8667-4ddf221db3fa', '題錢宇別墅', '題錢宇別墅', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["林居向晚饒清景，惜去非關戀酒桮。","石淨每因杉露滴，地幽漸覺水禽來。","藥蔬秋後供僧盡，竹杖吟中望月回。","紅葉閑飄籬落迥，行人遠見草堂開。"]', '["林居向晚饒清景，惜去非关戀酒桮。","石淨每因杉露滴，地幽漸覺水禽来。","藥蔬秋後供僧尽，竹杖吟中望月回。","紅葉闲飄籬落迥，行人远见草堂开。"]', '诗', 'shi', '', NULL, '題錢宇別墅 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27ff54ab-4861-43d8-b3c1-69113d2e4e10', '近試上張籍水部', '近試上張籍水部', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["洞房昨夜停紅燭，待曉堂前拜舅姑。","[妝]罷低聲問夫壻，畫眉深淺入時無。"]', '["洞房昨夜停紅燭，待晓堂前拜舅姑。","[妝]罷低声问夫壻，畫眉深淺入时無。"]', '诗', 'shi', '', NULL, '近試上張籍水部 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b58c5082-f5d7-4939-a0c5-a3f02eaecb9e', '留別盧玄休歸荆門', '留別盧玄休归荆门', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["江邊離別心，言罷各霑襟。","以我去帆遠，知君離恨深。","雲開孤島出，浪起白鷗沈。","更作來年約，陽臺許伴尋。"]', '["江邊離別心，言罷各霑襟。","以我去帆远，知君離恨深。","云开孤島出，浪起白鷗沈。","更作来年約，陽台許伴尋。"]', '诗', 'shi', '', NULL, '留別盧玄休歸荆門 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a1c7ef7-c726-4910-b2e4-dfd4a5409a9c', '采蓮', '采蓮', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["隔煙花草遠濛濛，恨箇來時路不同。","正是停橈相遇處，鴛鴦飛去急流中。"]', '["隔煙花草远濛濛，恨箇来时路不同。","正是停橈相遇处，鴛鴦飞去急流中。"]', '诗', 'shi', '', NULL, '采蓮 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c747259c-72ea-4440-b377-b71b6f399b45', '都門晚望', '都门晚望', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["綠槐花墮御溝邊，步出都門雨後天。","日暮野人耕種罷，烽樓原上一條煙。"]', '["綠槐花墮御溝邊，步出都门雨後天。","日暮野人耕種罷，烽楼原上一條煙。"]', '诗', 'shi', '', NULL, '都門晚望 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70190e71-fe5c-403a-b5da-bce75cd93f7a', '舜井', '舜井', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["碧甃磷磷不記年，青蘿鎖在小山顛。","向來下視千山水，疑是蒼梧萬里天。"]', '["碧甃磷磷不記年，青蘿鎖在小山顛。","向来下視千山水，疑是蒼梧万里天。"]', '诗', 'shi', '', NULL, '舜井 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('357bfd78-344a-4c05-8c47-5efeb9da1c35', '商州王中丞留喫枳殼', '商州王中丞留喫枳殼', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["方物就中名最遠，只應愈疾味偏佳。","若交盡乞人人與，采盡商山枳殼花。"]', '["方物就中名最远，只應愈疾味偏佳。","若交尽乞人人與，采尽商山枳殼花。"]', '诗', 'shi', '', NULL, '商州王中丞留喫枳殼 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccbf43a1-7dda-4e2e-9092-20c1d8966ca0', '登玄都閣', '登玄都閣', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["野色晴宜上閣看，樹陰遙映御溝寒。","豪家舊宅無人住，空見朱門鎖牡丹。"]', '["野色晴宜上閣看，樹陰遙映御溝寒。","豪家旧宅無人住，空见朱门鎖牡丹。"]', '诗', 'shi', '', NULL, '登玄都閣 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87b3b9b5-81f8-4e0b-8ec1-b3f7e64fa3bf', '贈鳳翔柳司錄', '贈鳳翔柳司錄', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["杏園北寺題名日，數到如今四十年。","點檢生涯與官職，一莖野竹在身邊。"]', '["杏园北寺題名日，數到如今四十年。","点檢生涯與官職，一莖野竹在身邊。"]', '诗', 'shi', '', NULL, '贈鳳翔柳司錄 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d28f0767-5f81-4529-9280-1dd6538a0980', '啄木兒', '啄木兒', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["丁丁向晚急還稀，啄遍庭槐未肯歸。","終日與君除蠹害，莫嫌無事不頻飛。"]', '["丁丁向晚急還稀，啄遍庭槐未肯归。","終日與君除蠹害，莫嫌無事不頻飞。"]', '诗', 'shi', '', NULL, '啄木兒 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92f6364f-d21b-45dd-bf49-adce92f74435', '榜曲', '榜曲', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["荷花明滅水煙空，惆悵來時徑不同。","欲到前洲堪入處，鴛鴦飛出碧流中。"]', '["荷花明滅水煙空，惆悵来时徑不同。","欲到前洲堪入处，鴛鴦飞出碧流中。"]', '诗', 'shi', '', NULL, '榜曲 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfdf3ee1-e5c0-499f-9359-d897a6ba388d', '逢山人', '逢山人', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["星月相逢現此身，自然無跡又無塵。","秋來若向金天會，便是青蓮葉上人。"]', '["星月相逢現此身，自然無跡又無塵。","秋来若向金天會，便是青蓮葉上人。"]', '诗', 'shi', '', NULL, '逢山人 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01db2ff5-3041-470a-8b13-44baf31a3fab', '過耶溪', '過耶溪', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["春溪繚繞出無窮，兩岸桃花正好風。","恰是扁舟堪入處，鴛鴦飛起碧流中。"]', '["春溪繚繞出無窮，兩岸桃花正好风。","恰是扁舟堪入处，鴛鴦飞起碧流中。"]', '诗', 'shi', '', NULL, '過耶溪 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1106d2c-d783-401d-96f6-caea6112767b', '賀張水部員外拜命', '賀張水部員外拜命', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["省中官最美，無似水曹郎。","前代佳名遜，當時重姓張。","白鬚吟麗句，紅葉吐朝陽。","徒有歸山意，君恩未可忘。"]', '["省中官最美，無似水曹郎。","前代佳名遜，當时重姓張。","白鬚吟丽句，紅葉吐朝陽。","徒有归山意，君恩未可忘。"]', '诗', 'shi', '', NULL, '賀張水部員外拜命 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f9c08bb-3a1d-4ff5-90b1-6b4092f898b5', '送璧州劉使君', '送璧州劉使君', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["王府登朝後，巴鄉典郡新。","江分入峽路，山見採鞭人。","舊業孤城夢，生祠幾處身。","知君素清儉，料得却來貧。"]', '["王府登朝後，巴乡典郡新。","江分入峽路，山见採鞭人。","旧業孤城梦，生祠幾处身。","知君素清儉，料得却来貧。"]', '诗', 'shi', '', NULL, '送璧州劉使君 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a355760-3384-4229-ad39-a9b8a1e7d54d', '贈江夏盧使君', '贈江夏盧使君', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["詩人中最屈，無與使君儔。","白髮雖求退，明時合見收。","登山猶自健，縱酒可多愁。","好是能騎馬，相逢見鄂州。"]', '["诗人中最屈，無與使君儔。","白髮雖求退，明时合见收。","登山猶自健，縱酒可多愁。","好是能騎马，相逢见鄂州。"]', '诗', 'shi', '', NULL, '贈江夏盧使君 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c171c454-08a8-4512-8008-1fb76713def6', '送崔秀才遊江陵', '送崔秀才游江陵', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["樽前荆楚客，雲外思縈迴。","秦野春已盡，商山花正開。","鷗驚帆乍起，虹見雨初來。","自有歸期在，蟬聲處處催。"]', '["樽前荆楚客，云外思縈迴。","秦野春已尽，商山花正开。","鷗驚帆乍起，虹见雨初来。","自有归期在，蟬声处处催。"]', '诗', 'shi', '', NULL, '送崔秀才遊江陵 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c90cee11-8d27-4537-91bc-0ff7b6ecbd57', '觀濤', '观濤', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["木落霜飛天地清，空江百里見潮生。","鮮飆出海魚龍氣，晴雪噴山雷鼓聲。","雲日半陰川漸滿，客帆皆過浪難平。","高樓曉望無窮意，丹葉黃花繞郡城。"]', '["木落霜飞天地清，空江百里见潮生。","鲜飆出海鱼龙氣，晴雪噴山雷鼓声。","云日半陰川漸满，客帆皆過浪难平。","高楼晓望無窮意，丹葉黄花繞郡城。"]', '诗', 'shi', '', NULL, '觀濤 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5023b104-9ff7-4b84-bb76-f9332fd06520', '南湖', '南湖', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["湖上微風小檻涼，翻翻菱荇滿迴塘。","野船著岸入春草，水鳥帶波飛夕陽。","蘆葉有聲疑露雨，浪花無際似瀟湘。","飄然蓬艇東歸客，盡日相看憶楚鄉。"]', '["湖上微风小檻涼，翻翻菱荇满迴塘。","野船著岸入春草，水鸟带波飞夕陽。","蘆葉有声疑露雨，浪花無際似瀟湘。","飄然蓬艇东归客，尽日相看憶楚乡。"]', '诗', 'shi', '', NULL, '南湖 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e944273-bee8-4763-a6bb-52e236f81ac2', '鏡湖西島言事', '镜湖西島言事', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["慵拙幸便荒僻地，縱聞猨鳥亦何愁。","偶因藥酒欺梅雨，却著寒衣過麥秋。","歲計有餘添橡實，生涯一半在漁舟。","世人若便無知己，應向此溪成白頭。"]', '["慵拙幸便荒僻地，縱闻猨鸟亦何愁。","偶因藥酒欺梅雨，却著寒衣過麦秋。","歲計有餘添橡實，生涯一半在漁舟。","世人若便無知己，應向此溪成白头。"]', '诗', 'shi', '', NULL, '鏡湖西島言事 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ffeb13b-7689-44ef-a101-7803ca2af52a', '送劉思復南河從軍', '送劉思复南河從軍', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["七千里別寧無恨，且貴從軍樂事多。","不駐節旄先候發，偶逢山寺亦難過。","蠻人獨放畬田火，海獸羣遊落日波。","遠作受恩身不易，莫拋書劒近笙歌。"]', '["七千里別寧無恨，且貴從軍乐事多。","不駐節旄先候發，偶逢山寺亦难過。","蠻人独放畬田火，海獸羣游落日波。","远作受恩身不易，莫拋书劒近笙歌。"]', '诗', 'shi', '', NULL, '送劉思復南河從軍 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a844318-403b-47ed-9b46-99508519957a', '宣武軍鎮作', '宣武軍鎮作', 'b84c4a86-52ed-4f2f-9358-2681ba93b41e', '唐', '["天兵十萬勇如貔，正是酬恩報國時。","汴水波瀾喧鼓角，隋堤楊柳拂旌旗。","前驅紅斾關西將，坐間青娥趙國姬。","寄語長安舊冠蓋，麤官到底是男兒。"]', '["天兵十万勇如貔，正是酬恩報国时。","汴水波瀾喧鼓角，隋堤楊柳拂旌旗。","前驱紅斾关西將，坐间青娥趙国姬。","寄語长安旧冠蓋，麤官到底是男兒。"]', '诗', 'shi', '', NULL, '宣武軍鎮作 王彥威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79685d1d-473c-4305-9b57-94f4a4c00429', '春雪映早梅', '春雪映早梅', 'cbf45fb1-cc5e-478a-9cc1-1f2fb42a782e', '唐', '["清晨凝雪彩，新候變庭梅。","樹愛春榮徧，窗驚曙色催。","寒光添粉壁，積潤履青苔。","分明六出瑞，隱映幾枝開。","聞笛花疑落，揮琴興轉來。","曲成非寡和，長使思悠哉。"]', '["清晨凝雪彩，新候变庭梅。","樹愛春榮徧，窗驚曙色催。","寒光添粉壁，積潤履青苔。","分明六出瑞，隐映幾枝开。","闻笛花疑落，揮琴兴轉来。","曲成非寡和，长使思悠哉。"]', '诗', 'shi', '', NULL, '春雪映早梅 庾敬休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d765ff1-b81a-4cb2-922f-ac62ccbe280d', '題雁塔', '題雁塔', '4516b0d2-3592-4ef8-8cc1-1c1bbcd60085', '唐', '["寶輪金地壓人寰，獨坐蒼冥啓玉關。","北嶺風煙開魏闕，南軒氣象鎮商山。","灞陵車馬垂楊裏，京國城池落照間。","蹔放塵心游物外，六街鐘鼓又催還。"]', '["寶輪金地壓人寰，独坐蒼冥啓玉关。","北嶺风煙开魏闕，南軒氣象鎮商山。","灞陵车马垂楊裏，京国城池落照间。","蹔放塵心游物外，六街鐘鼓又催還。"]', '诗', 'shi', '', NULL, '題雁塔 許玫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d93cc379-539d-4ffa-84e7-a138a3372da8', '從軍行', '從軍行', '1bb99cff-8449-44c8-8297-1e5eb119b959', '唐', '["邊草旱不春，劒光增野塵。","戰場收驥尾，清瀚怯龍鱗。","帆色起歸越，松聲厭避秦。","幾時逢范蠡，處處是通津。"]', '["邊草旱不春，劒光增野塵。","戰場收驥尾，清瀚怯龙鱗。","帆色起归越，松声厭避秦。","幾时逢范蠡，处处是通津。"]', '诗', 'shi', '', NULL, '從軍行 厲玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80299698-0d78-46be-9dbf-c7aed3e1ee79', '寄婺州溫郎中', '寄婺州溫郎中', '1bb99cff-8449-44c8-8297-1e5eb119b959', '唐', '["積雪沒蘭溪，鄰州望不迷。","波中分鴈宿，樹杪接猨啼。","婺女家空在，星郎手未攜。","故山新寺額，掩泣荷重題。"]', '["積雪沒蘭溪，鄰州望不迷。","波中分鴈宿，樹杪接猨啼。","婺女家空在，星郎手未携。","故山新寺額，掩泣荷重題。"]', '诗', 'shi', '', NULL, '寄婺州溫郎中 厲玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c242f755-286f-45f7-b4e6-6bf7c17ae6b0', '送顧非熊及第歸茅山', '送顧非熊及第归茅山', '1bb99cff-8449-44c8-8297-1e5eb119b959', '唐', '["故山登第去，不似舊歸難。","帆卷江初夜，梅生洞少寒。","採薇留客飲，折竹掃仙壇。","名在儀曹籍，何人肯挂冠。"]', '["故山登第去，不似旧归难。","帆卷江初夜，梅生洞少寒。","採薇留客饮，折竹掃仙壇。","名在儀曹籍，何人肯挂冠。"]', '诗', 'shi', '', NULL, '送顧非熊及第歸茅山 厲玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('152b6cb5-2853-4927-88c7-c87678194e00', '送黃曄明府岳州湘陰赴任', '送黄曄明府岳州湘陰赴任', '1bb99cff-8449-44c8-8297-1e5eb119b959', '唐', '["恩霑譴雪幾人同，歸宰湘陰六月中。","商嶺馬嘶殘暑雨，席帆高挂早秋風。","貢名頻向書闈失，飛檄曾傳朔漠空。","西省尚嗟君宦遠，水雞啼處莫聽鴻。"]', '["恩霑譴雪幾人同，归宰湘陰六月中。","商嶺马嘶殘暑雨，席帆高挂早秋风。","貢名頻向书闈失，飞檄曾傳朔漠空。","西省尚嗟君宦远，水雞啼处莫听鴻。"]', '诗', 'shi', '', NULL, '送黃曄明府岳州湘陰赴任 厲玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eebd9390-7301-434a-90c8-73e52adcbf46', '緱山月夜聞王子晉吹笙', '緱山月夜闻王子晉吹笙', '1bb99cff-8449-44c8-8297-1e5eb119b959', '唐', '["緱山明月夜，岑寂隔塵氛。","紫府參差曲，清宵次第聞。","韻流多入洞，聲度半和雲。","拂竹鸞驚侶，經松鶴對羣。","蟾光聽處合，仙路望中分。","坐惜千巖曙，遺香過汝墳。"]', '["緱山明月夜，岑寂隔塵氛。","紫府參差曲，清宵次第闻。","韻流多入洞，声度半和云。","拂竹鸾驚侶，經松鹤对羣。","蟾光听处合，仙路望中分。","坐惜千巖曙，遺香過汝墳。"]', '诗', 'shi', '', NULL, '緱山月夜聞王子晉吹笙 厲玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('619def4c-884b-449f-9f38-51d971db4d71', '和白敏中聖德和平致茲休運歲終功就合詠盛明呈上', '和白敏中聖德和平致茲休運歲終功就合詠盛明呈上', 'e2b22bc4-7347-4772-b81b-831b0ad9c981', '唐', '["蕭關新復舊山川，古戍秦原景象鮮。","戎虜乞降歸惠化，皇威漸被懾腥膻。","穹廬遠戍煙塵滅，神武光揚竹帛傳。","左袵盡知謌帝澤，從茲不更備三邊。"]', '["蕭关新复旧山川，古戍秦原景象鲜。","戎虜乞降归惠化，皇威漸被懾腥膻。","穹廬远戍煙塵滅，神武光揚竹帛傳。","左袵尽知謌帝澤，從茲不更備三邊。"]', '诗', 'shi', '', NULL, '和白敏中聖德和平致茲休運歲終功就合詠盛明呈上 魏扶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30ed061e-91a8-4f5a-b247-aeb7e726b0d3', '貢院題', '貢院題', 'e2b22bc4-7347-4772-b81b-831b0ad9c981', '唐', '["梧桐葉落滿庭陰，鎖閉朱門試院深。","曾是昔年辛苦地，不將今日負初心。"]', '["梧桐葉落满庭陰，鎖閉朱门試院深。","曾是昔年辛苦地，不將今日負初心。"]', '诗', 'shi', '', NULL, '貢院題 魏扶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7f11624-e678-4947-99d6-9220cab527c7', '賦愁', '賦愁', 'e2b22bc4-7347-4772-b81b-831b0ad9c981', '唐', '["愁，逈野，深秋。","生枕上，起眉頭。","閨閤危坐，風塵遠遊。","巴猨啼不住，谷水咽還流。","送客泊舟入浦，思鄉望月登樓。","煙波早晚長羈旅，絃管終年樂五侯。"]', '["愁，逈野，深秋。","生枕上，起眉头。","閨閤危坐，风塵远游。","巴猨啼不住，谷水咽還流。","送客泊舟入浦，思乡望月登楼。","煙波早晚长羈旅，絃管終年乐五侯。"]', '诗', 'shi', '', NULL, '賦愁 魏扶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef0a15fb-477b-44e4-bff7-5ed47b249a39', '登郡中銷暑樓寄東川汝士', '登郡中銷暑楼寄东川汝士', '91ed4642-1a5f-4496-b08f-3b04a9540d06', '唐', '["岧嶤下瞰霅溪流，極目煙波望梓州。","雖有清風當夏景，只能銷暑不銷憂。"]', '["岧嶤下瞰霅溪流，極目煙波望梓州。","雖有清风當夏景，只能銷暑不銷憂。"]', '诗', 'shi', '', NULL, '登郡中銷暑樓寄東川汝士 楊漢公 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b429dece-1417-480a-b9f3-3c7d605df08e', '明月樓', '明月楼', '91ed4642-1a5f-4496-b08f-3b04a9540d06', '唐', '["吳興城闕水雲中，畫舫青簾處處通。","溪上玉樓樓上月，清光合作水晶宮。"]', '["吳兴城闕水云中，畫舫青簾处处通。","溪上玉楼楼上月，清光合作水晶宮。"]', '诗', 'shi', '', NULL, '明月樓 楊漢公 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64c55c5c-684b-4cb1-a755-64ca634b0f47', '送閬州妓人歸老', '送閬州妓人归老', '13ba245b-565e-4012-9f92-770cb03a1996', '唐', '["竹翠嬋娟草逕幽，佳人歸老傍汀洲。","玉蟾露冷梁塵暗，金鳳花開雲鬢秋。","十畝稻香新綠野，一聲歌斷舊青樓。","芭蕉半卷西池雨，日暮門前雙白鷗。"]', '["竹翠嬋娟草逕幽，佳人归老傍汀洲。","玉蟾露冷梁塵暗，金鳳花开云鬢秋。","十畝稻香新綠野，一声歌斷旧青楼。","芭蕉半卷西池雨，日暮门前雙白鷗。"]', '诗', 'shi', '', NULL, '送閬州妓人歸老 何扶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b54b1f8-7f9d-4efa-8a5e-38e7666cae6e', '寄舊同年', '寄旧同年', '13ba245b-565e-4012-9f92-770cb03a1996', '唐', '["金榜題名墨尚新，今年依舊去年春。","花間每被紅妝問，何事重來只一人。"]', '["金榜題名墨尚新，今年依旧去年春。","花间每被紅妝问，何事重来只一人。"]', '诗', 'shi', '', NULL, '寄舊同年 何扶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a4e6505-1883-421a-81d4-791f2fe109f4', '望九華山', '望九华山', 'b0bbd58b-d8cb-46ef-b647-66e1c2d3babb', '唐', '["九華如劍插雲霓，青靄連空望欲迷。","北截吳門疑地盡，南連楚界覺天低。","龍池水蘸中秋月，石路人攀上漢梯。","惆悵舊游無復到，會須登此出塵泥。"]', '["九华如劍插云霓，青靄連空望欲迷。","北截吳门疑地尽，南連楚界覺天低。","龙池水蘸中秋月，石路人攀上漢梯。","惆悵旧游無复到，會須登此出塵泥。"]', '诗', 'shi', '', NULL, '望九華山 柴夔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80bc7242-0faf-4e71-bd08-87dc7797434f', '寄妾趙氏', '寄妾趙氏', '0477a663-ce91-4f18-85e5-c308e875ba29', '唐', '["鸞鳳分飛海樹秋，忍聽鐘鼓越王樓。","只應霜月明君意，緩撫瑤琴送我愁。","山遠莫教雙淚盡，雁來空寄八行幽。","相如若返臨邛市，畫舸朱軒萬里游。"]', '["鸾鳳分飞海樹秋，忍听鐘鼓越王楼。","只應霜月明君意，緩撫瑤琴送我愁。","山远莫教雙泪尽，雁来空寄八行幽。","相如若返臨邛市，畫舸朱軒万里游。"]', '诗', 'shi', '', NULL, '寄妾趙氏 房千里 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad146e03-747a-4a4b-865c-97a8aff9f099', '早行', '早行', 'd8f779bd-27a7-4ec2-91ab-6dd95cdacb9e', '唐', '["鐘靜人猶寢，天高月自涼。","一星深戍火，殘月半橋霜。","客老愁塵下，蟬寒怨路傍。","青山依舊色，宛是馬卿鄉。"]', '["鐘静人猶寢，天高月自涼。","一星深戍火，殘月半橋霜。","客老愁塵下，蟬寒怨路傍。","青山依旧色，宛是马卿乡。"]', '诗', 'shi', '', NULL, '早行 劉郇伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a6f6407-5231-4002-be02-0e6301f5c3b0', '句', '句', 'd8f779bd-27a7-4ec2-91ab-6dd95cdacb9e', '唐', '["人生分外愁。"]', '["人生分外愁。"]', '诗', 'shi', '', NULL, '句 劉郇伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b394904-befe-4dd5-81b2-2ded491c6ea5', '贈成都僧', '贈成都僧', 'f1048891-b927-480c-8c32-61732c462574', '唐', '["南宗尚許通方便，何處心中更有經？好去苾蒭雲水畔，何山松栢不青青。"]', '["南宗尚許通方便，何处心中更有經？好去苾蒭云水畔，何山松栢不青青。"]', '诗', 'shi', '', NULL, '贈成都僧 李章武 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a388971-8cbd-4335-b787-db4dda3a604a', '享太廟樂章', '享太廟乐章', '10608f17-cdfe-469b-9081-e5550a6d85e2', '唐', '["聖祚無疆，慶傳樂章。","金枝繁茂，玉葉延長。","海瀆常晏，波濤不揚。","汪汪美化，垂範今王。"]', '["聖祚無疆，慶傳乐章。","金枝繁茂，玉葉延长。","海瀆常晏，波濤不揚。","汪汪美化，垂範今王。"]', '诗', 'shi', '', NULL, '享太廟樂章 蕭倣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26d2ab27-e7d2-4c53-9fb1-202bbc0138e0', '享太廟樂章', '享太廟乐章', '10608f17-cdfe-469b-9081-e5550a6d85e2', '唐', '["於鑠丕嗣，惟帝之光。","羽籥象德，金石薦祥。","聖系無極，景命永昌。","神降上哲，維天配長。"]', '["於鑠丕嗣，惟帝之光。","羽籥象德，金石薦祥。","聖系無極，景命永昌。","神降上哲，維天配长。"]', '诗', 'shi', '', NULL, '享太廟樂章 蕭倣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed41bb29-5728-4baf-a842-a124083eb671', '荅楊尚書', '荅楊尚书', '5cdad4f8-c204-490b-8d90-7b22911c4887', '唐', '["未向燕臺逢厚禮，幸因社會接餘歡。","一魚喫了終無媿，鵾化爲鵬也不難。"]', '["未向燕台逢厚禮，幸因社會接餘歡。","一鱼喫了終無媿，鵾化爲鵬也不难。"]', '诗', 'shi', '', NULL, '荅楊尚書 柳棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a5db9d9-af47-4083-97d7-088dd9447897', '席上戲東川楊尚書', '席上戲东川楊尚书', '5cdad4f8-c204-490b-8d90-7b22911c4887', '唐', '["莫言名位未相儔，風月何曾阻獻酬。","前輩不須輕後輩，靖安今日在衡州。"]', '["莫言名位未相儔，风月何曾阻獻酬。","前輩不須轻後輩，靖安今日在衡州。"]', '诗', 'shi', '', NULL, '席上戲東川楊尚書 柳棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7e9facb-cdfa-45db-ad83-38f2ba42c0ad', '緱山月夜聞王子晉吹笙', '緱山月夜闻王子晉吹笙', '372f736f-6a15-4398-b07a-c3d0ab78d6ea', '唐', '["月滿緱山夜，風傳子晉笙。","初聞盈谷遠，漸聽入雲清。","杳異人間曲，遙分鶴上情。","孤鸞驚欲舞，萬籟寂無聲。","此夕留煙駕，何時返玉京？","唯愁音響絕，曉色出都城。"]', '["月满緱山夜，风傳子晉笙。","初闻盈谷远，漸听入云清。","杳異人间曲，遙分鹤上情。","孤鸾驚欲舞，万籟寂無声。","此夕留煙駕，何时返玉京？","唯愁音响絕，晓色出都城。"]', '诗', 'shi', '', NULL, '緱山月夜聞王子晉吹笙 鍾輅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb539b2b-56bb-41a5-8e69-7f43af8d2b19', '南溪書院', '南溪书院', '829f931e-6219-4d4b-ba3b-492fe3cf0c36', '唐', '["茅屋住來久，山深不置門。","草生垂井口，花發接籬根。","入院將雛鳥，攀蘿抱子猨。","曾逢異人說，風景似桃源。"]', '["茅屋住来久，山深不置门。","草生垂井口，花發接籬根。","入院將雛鸟，攀蘿抱子猨。","曾逢異人说，风景似桃源。"]', '诗', 'shi', '', NULL, '南溪書院 楊發 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9d22e42-8b9b-4cdf-ad2e-94da89a8ccb3', '春園醉醒閑臥小齋', '春园醉醒闲臥小斋', '829f931e-6219-4d4b-ba3b-492fe3cf0c36', '唐', '["酣醉送餘春，醒來恨更頻。","花殘蜂蠹物，葉暗鳥欺人。","簾閉高眠貴，齋空浩氣新。","從今北牕蝶，長是夢中身。"]', '["酣醉送餘春，醒来恨更頻。","花殘蜂蠹物，葉暗鸟欺人。","簾閉高眠貴，斋空浩氣新。","從今北牕蝶，长是梦中身。"]', '诗', 'shi', '', NULL, '春園醉醒閑臥小齋 楊發 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d3748cf-ba8b-4f09-8628-b7e08f270193', '小園秋興', '小园秋兴', '829f931e-6219-4d4b-ba3b-492fe3cf0c36', '唐', '["誰言帝城裏，獨作野人居。","石磴晴看疊，山苗晚自鋤。","相慚五秉粟，尚癖一車書。","昔日揚雄宅，還無鄉相輿。"]', '["誰言帝城裏，独作野人居。","石磴晴看叠，山苗晚自鋤。","相慚五秉粟，尚癖一车书。","昔日揚雄宅，還無乡相輿。"]', '诗', 'shi', '', NULL, '小園秋興 楊發 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f527aa98-54ca-4175-a89d-e0e40db27c9f', '與諸公池上待月', '與諸公池上待月', '829f931e-6219-4d4b-ba3b-492fe3cf0c36', '唐', '["樹密雲縈岸，池遙水際空。","芰開方吐鏡，蘋動欲含風。","漸映沙汀白，微分渚葉紅。","金波宜共賞，仙櫂一宵同。"]', '["樹密云縈岸，池遙水際空。","芰开方吐镜，蘋动欲含风。","漸映沙汀白，微分渚葉紅。","金波宜共賞，仙櫂一宵同。"]', '诗', 'shi', '', NULL, '與諸公池上待月 楊發 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('285f77cd-a017-4e27-ad44-acaeaac79b37', '簷雀', '簷雀', '829f931e-6219-4d4b-ba3b-492fe3cf0c36', '唐', '["弱羽怯孤飛，投簷幸所依。","銜環唯報德，賀廈本知歸。","紅觜休爭顧，丹心自識機。","從來攀鳳足，生死戀光輝。"]', '["弱羽怯孤飞，投簷幸所依。","銜环唯報德，賀廈本知归。","紅觜休爭顧，丹心自識機。","從来攀鳳足，生死戀光輝。"]', '诗', 'shi', '', NULL, '簷雀 楊發 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f90f18d0-a857-4401-9b0c-88c70c642db5', '殘花', '殘花', '829f931e-6219-4d4b-ba3b-492fe3cf0c36', '唐', '["已笑良時晚，仍悲別酒催。","暖芳隨日薄，殘片逐風迴。","黛歛愁歌扇，妝殘泣鏡臺。","繁陰莫矜衒，終是共塵埃。"]', '["已笑良时晚，仍悲別酒催。","暖芳隨日薄，殘片逐风迴。","黛歛愁歌扇，妝殘泣镜台。","繁陰莫矜衒，終是共塵埃。"]', '诗', 'shi', '', NULL, '殘花 楊發 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3eb03db-284c-4eef-bbed-223f82a01565', '山泉', '山泉', '829f931e-6219-4d4b-ba3b-492fe3cf0c36', '唐', '["半空飛下水，勢去響如雷。","靜徹啼猨寺，高陵坐客臺。","耳同經劒閣，身若到天台。","濺樹吹成凍，鄰祠觸作灰。","深中試榔栗，淺處落莓苔。","半夜重城閉，潺湲枕底來。"]', '["半空飞下水，勢去响如雷。","静徹啼猨寺，高陵坐客台。","耳同經劒閣，身若到天台。","濺樹吹成凍，鄰祠觸作灰。","深中試榔栗，淺处落莓苔。","半夜重城閉，潺湲枕底来。"]', '诗', 'shi', '', NULL, '山泉 楊發 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('377bfc60-652a-45e0-a006-2b3429f87910', '秋晚日少陵原游山泉之什', '秋晚日少陵原游山泉之什', '829f931e-6219-4d4b-ba3b-492fe3cf0c36', '唐', '["喧濁侵肌性未沈，每來雲外恣幽尋。","塵衣更喜秋泉潔，倦跡方依竹洞深。","暫過偶然應繫分，有期終去但勞心。","唯憐一夜空山月，似許他年伴獨吟。"]', '["喧濁侵肌性未沈，每来云外恣幽尋。","塵衣更喜秋泉潔，倦跡方依竹洞深。","暫過偶然應繫分，有期終去但勞心。","唯怜一夜空山月，似許他年伴独吟。"]', '诗', 'shi', '', NULL, '秋晚日少陵原游山泉之什 楊發 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a00bd0c-8efa-4506-96d8-9a7a6cd8d64e', '秋晴獨立南亭', '秋晴独立南亭', '829f931e-6219-4d4b-ba3b-492fe3cf0c36', '唐', '["晝對南風獨閉關，暗期幽鳥去仍還。","如今有待終身貴，未若忘機盡日閑。","心似蒙莊遊物外，官慚許掾在人間。","開襟自向清風笑，無限秋光爲解顏。"]', '["晝对南风独閉关，暗期幽鸟去仍還。","如今有待終身貴，未若忘機尽日闲。","心似蒙莊游物外，官慚許掾在人间。","开襟自向清风笑，無限秋光爲解顏。"]', '诗', 'shi', '', NULL, '秋晴獨立南亭 楊發 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdefa73b-111d-4b67-ae50-343eb1acce7a', '宿黃花館', '宿黄花館', '829f931e-6219-4d4b-ba3b-492fe3cf0c36', '唐', '["孤館蕭條槐葉稀，暮蟬聲隔水聲微。","年年爲客路無盡，日日送人身未歸。","何處迷鴻離浦月，誰家愁婦擣霜衣。","夜深不臥簾猶捲，數點殘螢入戶飛。"]', '["孤館蕭條槐葉稀，暮蟬声隔水声微。","年年爲客路無尽，日日送人身未归。","何处迷鴻離浦月，誰家愁婦擣霜衣。","夜深不臥簾猶捲，數点殘螢入戶飞。"]', '诗', 'shi', '', NULL, '宿黃花館 楊發 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3858aba8-a434-4161-b876-30932cdb1de5', '南野逢田客', '南野逢田客', '829f931e-6219-4d4b-ba3b-492fe3cf0c36', '唐', '["桑柘悠悠水蘸堤，晚風晴景不妨犂。","高機猶織臥蠶子，下坂未饑逢飼妻。","杏色滿林羊酪熟，麥涼浮壠雉媒低。","生時自樂死由命，萬事在天管不迷。"]', '["桑柘悠悠水蘸堤，晚风晴景不妨犂。","高機猶织臥蠶子，下坂未饑逢飼妻。","杏色满林羊酪熟，麦涼浮壠雉媒低。","生时自乐死由命，万事在天管不迷。"]', '诗', 'shi', '', NULL, '南野逢田客 楊發 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd504db7-1451-43ed-8535-3d832aeeb913', '東齋夜宴酬紹之起居見贈', '东斋夜宴酬紹之起居见贈', '829f931e-6219-4d4b-ba3b-492fe3cf0c36', '唐', '["龍門八上不知津，唯有君心困益親。","白社追遊名自遠，青袍相映道逾新。","十年江海魚緘盡，一夜笙歌鳳吹頻。","漸老舊交情更重，莫將美酒負良辰。"]', '["龙门八上不知津，唯有君心困益親。","白社追游名自远，青袍相映道逾新。","十年江海鱼緘尽，一夜笙歌鳳吹頻。","漸老旧交情更重，莫將美酒負良辰。"]', '诗', 'shi', '', NULL, '東齋夜宴酬紹之起居見贈 楊發 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3b5ae5a-7283-4968-b235-37d4115c5d03', '翫殘花', '翫殘花', '829f931e-6219-4d4b-ba3b-492fe3cf0c36', '唐', '["十日濃芳一歲程，東風初急眼偏明。","低枝似泥幽人醉，莫道無情似有情。"]', '["十日濃芳一歲程，东风初急眼偏明。","低枝似泥幽人醉，莫道無情似有情。"]', '诗', 'shi', '', NULL, '翫殘花 楊發 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3338fae3-9357-4a05-9492-bc4c75aea40e', '詠蛙', '詠蛙', '4ad6fc77-e6c8-43a3-bf1c-3fdd891b6cd0', '唐', '["兔邊分玉樹，龍底耀銅儀。","會當同鼓吹，不復問官私。"]', '["兔邊分玉樹，龙底耀銅儀。","會當同鼓吹，不复问官私。"]', '诗', 'shi', '', NULL, '詠蛙 楊收 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbae43f0-12bb-40f6-853c-7d682bcf6c92', '筆', '笔', '4ad6fc77-e6c8-43a3-bf1c-3fdd891b6cd0', '唐', '["雖匪囊中物，何堅不可鑽。","一朝操政柄，定使冠三端。"]', '["雖匪囊中物，何堅不可鑽。","一朝操政柄，定使冠三端。"]', '诗', 'shi', '', NULL, '筆 楊收 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1b78a63-bf5c-4a86-8496-faab8b5f77a2', '嘲吳人觀者', '嘲吳人观者', '4ad6fc77-e6c8-43a3-bf1c-3fdd891b6cd0', '唐', '["爾幸無羸角，何用觸吾藩。","若是升堂者，還應自得門。"]', '["爾幸無羸角，何用觸吾藩。","若是升堂者，還應自得门。"]', '诗', 'shi', '', NULL, '嘲吳人觀者 楊收 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('795a0d30-7e33-4cb0-9c71-00640cc2630f', '甲子歲書事', '甲子歲书事', 'b3476288-6040-4dc5-aea4-564f97255037', '唐', '["豎子未鼎烹，大君尚旰食。","風雷隨出師，雲霞有戰色。","犒功椎萬牛，募勇懸千帛。","武士日曳柴，飛將競執馘。","喜氣迎捷書，懽聲送羽檄。","天兵日雄強，桀犬稍離析。","賊臂既已斷，賊喉既已搤。","樂禍但鯨鯢，同惡爲肘腋。","小大勢難侔，逆順初不敵。","違命固天亡，恃險乖長策。","蠆毒久萌牙，狼顧非日夕。","禮貌忽驕狂，疏奏遂指斥。","動衆豈佳兵，含忍恐無益。","鴻恩既已孤，小效不足惜。","腐儒一鉛刀，投筆時感激。","帝閽不敢干，恓恓坐長畫。"]', '["豎子未鼎烹，大君尚旰食。","风雷隨出師，云霞有戰色。","犒功椎万牛，募勇懸千帛。","武士日曳柴，飞將競執馘。","喜氣迎捷书，懽声送羽檄。","天兵日雄強，桀犬稍離析。","賊臂既已斷，賊喉既已搤。","乐禍但鯨鯢，同惡爲肘腋。","小大勢难侔，逆順初不敵。","違命固天亡，恃險乖长策。","蠆毒久萌牙，狼顧非日夕。","禮貌忽驕狂，疏奏遂指斥。","动衆豈佳兵，含忍恐無益。","鴻恩既已孤，小效不足惜。","腐儒一鉛刀，投笔时感激。","帝閽不敢干，恓恓坐长畫。"]', '诗', 'shi', '', NULL, '甲子歲書事 楊乘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f197988c-128c-4c5b-ba4c-12edc25ca5fb', '南徐春日懷古', '南徐春日懷古', 'b3476288-6040-4dc5-aea4-564f97255037', '唐', '["六代驕奢地，三春物象繁。","靈湖通漲海，天塹隔中原。","曉渡高帆駛，陰風巨艦翻。","旌旗西日落，戈甲夏雲屯。","豹變資陳武，龍飛擁晉元。","風流前事盡，文物舊儀存。","邪侮嘗移潤，忠貞幾度冤。","興亡山兀兀，今古水渾渾。","露滴蜂偷蘂，鶯啼日到軒。","酒腸堆麴糵，詩思遶乾坤。","愁夢全無蝶，離憂每愧萱。","形骸勞大塊，玉石任炎崑。","出處寧由己，升沈未足言。","且應中聖樂，坐起任昏昏。"]', '["六代驕奢地，三春物象繁。","靈湖通漲海，天塹隔中原。","晓渡高帆駛，陰风巨艦翻。","旌旗西日落，戈甲夏云屯。","豹变資陳武，龙飞擁晉元。","风流前事尽，文物旧儀存。","邪侮嘗移潤，忠貞幾度冤。","兴亡山兀兀，今古水渾渾。","露滴蜂偷蘂，鶯啼日到軒。","酒腸堆麴糵，诗思遶乾坤。","愁梦全無蝶，離憂每愧萱。","形骸勞大塊，玉石任炎崑。","出处寧由己，升沈未足言。","且應中聖乐，坐起任昏昏。"]', '诗', 'shi', '', NULL, '南徐春日懷古 楊乘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4485534f-6f1d-42fc-9e4e-5e436390a2ea', '吳中書事', '吳中书事', 'b3476288-6040-4dc5-aea4-564f97255037', '唐', '["十萬人家天塹東，管弦臺榭滿春風。","名歸范蠡五湖上，國破西施一笑中。","香逕自生蘭葉小，響廊深映月華空。","尊前多暇但懷古，盡日愁吟誰與同。"]', '["十万人家天塹东，管弦台榭满春风。","名归范蠡五湖上，国破西施一笑中。","香逕自生蘭葉小，响廊深映月华空。","尊前多暇但懷古，尽日愁吟誰與同。"]', '诗', 'shi', '', NULL, '吳中書事 楊乘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a611f612-6aac-4551-a73b-870f183cd0f3', '建鄴懷古', '建鄴懷古', 'b3476288-6040-4dc5-aea4-564f97255037', '唐', '["故城故壘滿江濆，盡是干戈舊苦辛。","見此即須知帝力，生來便作太平人。"]', '["故城故壘满江濆，尽是干戈旧苦辛。","见此即須知帝力，生来便作太平人。"]', '诗', 'shi', '', NULL, '建鄴懷古 楊乘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e3b4647-f4fb-433d-b152-262e74599ea4', '牓句', '牓句', 'b3476288-6040-4dc5-aea4-564f97255037', '唐', '["伶俜乖拙兩何如，晝泥琴聲夜泥書。","數拍胡笳彈未熟，故人新命畫胡車。"]', '["伶俜乖拙兩何如，晝泥琴声夜泥书。","數拍胡笳彈未熟，故人新命畫胡车。"]', '诗', 'shi', '', NULL, '牓句 楊乘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('595aa16c-a3e3-4d0b-bc7a-3eba6dbe736b', '題楊收相公宅', '題楊收相公宅', '5ce6407d-b707-4159-8c2c-103de12ceea5', '唐', '["禍福從來路不遙，偶然平地上煙霄。","煙霄未穩還平地，門對孤峯占寂寥。"]', '["禍福從来路不遙，偶然平地上煙霄。","煙霄未穩還平地，门对孤峯占寂寥。"]', '诗', 'shi', '', NULL, '題楊收相公宅 尹璞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09a4efce-fd84-4660-9ab4-ae9c502887e8', '明月照高樓', '明月照高楼', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["朗月何高高，樓中簾影寒。","一婦獨含歎，四坐誰成歡。","時節屢已移，遊旅杳不還。","滄溟儻未涸，妾淚終不乾。","君若無定雲，妾若不動山。","雲行出山易，山逐雲去難。","願爲邊塞塵，因風委君顏。","君顏良洗多，盪妾濁水間。"]', '["朗月何高高，楼中簾影寒。","一婦独含歎，四坐誰成歡。","时節屢已移，游旅杳不還。","滄溟儻未涸，妾泪終不乾。","君若無定云，妾若不动山。","云行出山易，山逐云去难。","願爲邊塞塵，因风委君顏。","君顏良洗多，盪妾濁水间。"]', '诗', 'shi', '', NULL, '明月照高樓 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57436bfa-b684-4645-ab8c-5e40fd4c4320', '酬秘書王丞見寄', '酬秘书王丞见寄', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["朝下有閑思，南溝邊水行。","因來見寥落，轉自嘆平生。","白首丈夫氣，赤心知己情。","留詩本相慰，却憶苦吟聲。"]', '["朝下有闲思，南溝邊水行。","因来见寥落，轉自嘆平生。","白首丈夫氣，赤心知己情。","留诗本相慰，却憶苦吟声。"]', '诗', 'shi', '', NULL, '酬秘書王丞見寄 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ae12a8a-8cea-4e3a-8e07-6de76cfbb9a0', '贈金河戍客', '贈金河戍客', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["慣獵金河路，曾逢雪不迷。","射鵰青塚北，走馬黑山西。","戍遠旌幡少，年深帳幕低。","酬恩須盡敵，休說夢中閨。"]', '["慣獵金河路，曾逢雪不迷。","射鵰青塚北，走马黑山西。","戍远旌幡少，年深帳幕低。","酬恩須尽敵，休说梦中閨。"]', '诗', 'shi', '', NULL, '贈金河戍客 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05bab583-1916-4f9d-aa6c-dac73dee60ca', '孤桐', '孤桐', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["疎桐餘一幹，風雨日蕭條。","歲晚琴材老，天寒桂葉凋。","已悲根半死，復恐尾全焦。","幸在龍門下，知音肯寂寥。"]', '["疎桐餘一幹，风雨日蕭條。","歲晚琴材老，天寒桂葉凋。","已悲根半死，复恐尾全焦。","幸在龙门下，知音肯寂寥。"]', '诗', 'shi', '', NULL, '孤桐 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b2afcfa-9338-4f4f-b953-2c7a775654f9', '秋露', '秋露', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["白露曖秋色，月明清漏中。","痕沾珠箔重，點落玉盤空。","竹動時驚鳥，莎寒暗滴蟲。","滿園生永夜，漸欲與霜同。"]', '["白露曖秋色，月明清漏中。","痕沾珠箔重，点落玉盤空。","竹动时驚鸟，莎寒暗滴蟲。","满园生永夜，漸欲與霜同。"]', '诗', 'shi', '', NULL, '秋露 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9c4d4bc-c37f-43ac-8d77-3bd2b6ecb9cc', '送徐使君赴岳州', '送徐使君赴岳州', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["渺渺楚江上，風旗搖去舟。","馬歸雲夢晚，猨叫洞庭秋。","別思滿南渡，鄉心生北樓。","巴陵山水郡，應稱謝公遊。"]', '["渺渺楚江上，风旗搖去舟。","马归云梦晚，猨叫洞庭秋。","別思满南渡，乡心生北楼。","巴陵山水郡，應稱謝公游。"]', '诗', 'shi', '', NULL, '送徐使君赴岳州 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4553423-a81d-42e4-815c-3b5a43cc02b4', '送裴璋還蜀因亦懷歸', '送裴璋還蜀因亦懷归', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["客在劒門外，新年音信稀。","自爲千里別，已送幾人歸。","陌上月初落，馬前花正飛。","離言殊未盡，春雨滿行衣。"]', '["客在劒门外，新年音信稀。","自爲千里別，已送幾人归。","陌上月初落，马前花正飞。","離言殊未尽，春雨满行衣。"]', '诗', 'shi', '', NULL, '送裴璋還蜀因亦懷歸 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e089b32-773a-45a3-ab40-662a8693087b', '送前鄠縣李少府', '送前鄠縣李少府', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["近出圭峯下，還期又不賒。","身閑多宿寺，官滿未移家。","罷釣臨秋水，開尊對月華。","自當蓬閣選，豈得臥煙霞。"]', '["近出圭峯下，還期又不賒。","身闲多宿寺，官满未移家。","罷釣臨秋水，开尊对月华。","自當蓬閣選，豈得臥煙霞。"]', '诗', 'shi', '', NULL, '送前鄠縣李少府 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8573c60-f0b3-42b8-ab1d-f360c6b5f005', '送宜春裴明府之任', '送宜春裴明府之任', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["南行春已滿，路半水茫然。","楚望花當渡，湘陰橘滿川。","山橫湖色上，帆出鳥行前。","此任無辭遠，親人貴用還。"]', '["南行春已满，路半水茫然。","楚望花當渡，湘陰橘满川。","山橫湖色上，帆出鸟行前。","此任無辞远，親人貴用還。"]', '诗', 'shi', '', NULL, '送宜春裴明府之任 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2112e9f-7bdd-463b-9509-10deee22b235', '贈宗靜上人', '贈宗静上人', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["世上方傳教，山中未得歸。","閑花飄講席，馴鴿汙禪衣。","積雨誰過寺，殘鐘自掩扉。","寒來垂頂帽，白髮剃應稀。"]', '["世上方傳教，山中未得归。","闲花飄講席，馴鴿汙禪衣。","積雨誰過寺，殘鐘自掩扉。","寒来垂頂帽，白髮剃應稀。"]', '诗', 'shi', '', NULL, '贈宗靜上人 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dea4bdd-ba6f-4636-bfd7-08b28aee5412', '同賈島宿無可上人院', '同賈島宿無可上人院', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["何處銷愁宿，攜囊就遠僧。","中宵吟有雪，空屋語無燈。","靜境唯聞鐸，寒牀但枕肱。","還因愛閑客，始得見南能。"]', '["何处銷愁宿，携囊就远僧。","中宵吟有雪，空屋語無灯。","静境唯闻鐸，寒牀但枕肱。","還因愛闲客，始得见南能。"]', '诗', 'shi', '', NULL, '同賈島宿無可上人院 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d1de8d4-9452-4b6a-a1df-0e0012a2297a', '和劉補闕秋園寓興六首 一', '和劉補闕秋园寓兴六首 一', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["水木夕陰冷，池塘秋意多。","庭風吹故葉，階露淨寒莎。","愁燕窺燈語，情人見月過。","砧聲聽已別，蟲響復相和。"]', '["水木夕陰冷，池塘秋意多。","庭风吹故葉，階露淨寒莎。","愁燕窺灯語，情人见月過。","砧声听已別，蟲响复相和。"]', '诗', 'shi', '', NULL, '和劉補闕秋園寓興六首 一 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87dc5771-82a5-4eb8-b1c0-6852e81c74e5', '和劉補闕秋園寓興六首 二', '和劉補闕秋园寓兴六首 二', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["閉門無事後，此地即山中。","但覺鳥聲異，不知人境同。","晚花開爲雨，殘果落因風。","獨坐還吟酌，詩成酒已空。"]', '["閉门無事後，此地即山中。","但覺鸟声異，不知人境同。","晚花开爲雨，殘果落因风。","独坐還吟酌，诗成酒已空。"]', '诗', 'shi', '', NULL, '和劉補闕秋園寓興六首 二 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5afec976-2eda-4c13-aaf8-9fed63e551be', '和劉補闕秋園寓興六首 三', '和劉補闕秋园寓兴六首 三', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["自得家林趣，常時在外稀。","對僧餐野食，迎客著山衣。","雀鬬翻簷散，蟬驚出樹飛。","功成他日後，何必五湖歸。"]', '["自得家林趣，常时在外稀。","对僧餐野食，迎客著山衣。","雀鬬翻簷散，蟬驚出樹飞。","功成他日後，何必五湖归。"]', '诗', 'shi', '', NULL, '和劉補闕秋園寓興六首 三 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d55ea231-d593-469f-a326-ca790f1e2385', '和劉補闕秋園寓興六首 四', '和劉補闕秋园寓兴六首 四', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["秋色庭蕪上，清朝見露華。","疎篁抽晚筍，幽藥吐寒芽。","引水新渠淨，登臺小徑斜。","人來多愛此，蕭爽似仙家。"]', '["秋色庭蕪上，清朝见露华。","疎篁抽晚筍，幽藥吐寒芽。","引水新渠淨，登台小徑斜。","人来多愛此，蕭爽似仙家。"]', '诗', 'shi', '', NULL, '和劉補闕秋園寓興六首 四 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bba2324-7492-4b19-b2ee-23b39efba0d7', '和劉補闕秋園寓興六首 五', '和劉補闕秋园寓兴六首 五', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["禁掖朝回後，林園勝賞時。","野人來辨藥，庭鶴往看棊。","晚日明丹棗，朝霜潤紫棃。","還因重風景，猶自有秋詩。"]', '["禁掖朝回後，林园勝賞时。","野人来辨藥，庭鹤往看棊。","晚日明丹棗，朝霜潤紫棃。","還因重风景，猶自有秋诗。"]', '诗', 'shi', '', NULL, '和劉補闕秋園寓興六首 五 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64c5aa73-dfc1-4fa1-af9a-e6b0f2fefb1d', '和劉補闕秋園寓興六首 六', '和劉補闕秋园寓兴六首 六', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["聖代少封事，閑居方屏喧。","漏寒雲外闕，木落月中園。","山鳥宿簷樹，水螢流洞門。","無人見清景，林下自開尊。"]', '["聖代少封事，闲居方屏喧。","漏寒云外闕，木落月中园。","山鸟宿簷樹，水螢流洞门。","無人见清景，林下自开尊。"]', '诗', 'shi', '', NULL, '和劉補闕秋園寓興六首 六 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b11a699-03ff-45a1-99ed-a316198e32bb', '岳陽晚景', '岳陽晚景', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["漢陽無遠寺，見說過汾城。","雲雨經春客，江山幾日程。","終隨鷗鳥去，祗在海潮生。","前路逢漁父，多愁問姓名。"]', '["漢陽無远寺，见说過汾城。","云雨經春客，江山幾日程。","終隨鷗鸟去，祗在海潮生。","前路逢漁父，多愁问姓名。"]', '诗', 'shi', '', NULL, '岳陽晚景 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06bef238-e5cb-4567-9189-181f7a5e69eb', '塞上宿野寺', '塞上宿野寺', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["塞上蕃僧老，天寒疾上關。","遠煙平似水，高樹暗如山。","去馬朝常急，行人夜始閑。","更深聽刁斗，時到磬聲間。"]', '["塞上蕃僧老，天寒疾上关。","远煙平似水，高樹暗如山。","去马朝常急，行人夜始闲。","更深听刁斗，时到磬声间。"]', '诗', 'shi', '', NULL, '塞上宿野寺 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5adaa05a-f57b-4138-b9bf-028e672bac51', '寒食夜池上對月懷友', '寒食夜池上对月懷友', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["人間多別離，處處是相思。","海內無煙夜，天涯有月時。","跳魚翻荇葉，驚鵲出花枝。","親友皆千里，三更獨遶池。"]', '["人间多別離，处处是相思。","海內無煙夜，天涯有月时。","跳鱼翻荇葉，驚鵲出花枝。","親友皆千里，三更独遶池。"]', '诗', 'shi', '', NULL, '寒食夜池上對月懷友 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1539263-1eb6-45df-8982-60a437696a1f', '自述', '自述', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["萬事誰能問，一名猶未知。","貧當多累日，閑過少年時。","燈下和愁睡，花前帶酒悲。","無謀常委命，轉覺命堪疑。"]', '["万事誰能问，一名猶未知。","貧當多累日，闲過少年时。","灯下和愁睡，花前带酒悲。","無謀常委命，轉覺命堪疑。"]', '诗', 'shi', '', NULL, '自述 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8412179c-bd1d-48e3-aade-f826edcbffaa', '送契玄上人南遊', '送契玄上人南游', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["紅葉落湘川，楓明映水天。","尋鐘過楚寺，擁錫上瀧船。","病客思留藥，迷人待說禪。","南中多古跡，應訪虎溪泉。"]', '["紅葉落湘川，楓明映水天。","尋鐘過楚寺，擁錫上瀧船。","病客思留藥，迷人待说禪。","南中多古跡，應訪虎溪泉。"]', '诗', 'shi', '', NULL, '送契玄上人南遊 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('808146d5-a8f9-46d0-884d-cde93df5ae4f', '少年行', '少年行', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["不倚軍功有俠名，可憐毬獵少年情。","戴鈴健鶻隨聲下，撼珮驕驄弄影行。","覓匠重裝燕客劒，對人新按越姬箏。","豈知儒者心偏苦，吟向秋風白髮生。"]', '["不倚軍功有俠名，可怜毬獵少年情。","戴鈴健鶻隨声下，撼珮驕驄弄影行。","覓匠重裝燕客劒，对人新按越姬箏。","豈知儒者心偏苦，吟向秋风白髮生。"]', '诗', 'shi', '', NULL, '少年行 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93b34abe-9243-43b6-8505-2ad7af3ef323', '詠雙白鷺', '詠雙白鷺', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["雙鷺應憐水滿池，風飄不動頂絲垂。","立當青草人先見，行傍白蓮魚未知。","一足獨拳寒雨裏，數聲相叫早秋時。","林塘得爾須增價，況與詩家物色宜。"]', '["雙鷺應怜水满池，风飄不动頂絲垂。","立當青草人先见，行傍白蓮鱼未知。","一足独拳寒雨裏，數声相叫早秋时。","林塘得爾須增價，況與诗家物色宜。"]', '诗', 'shi', '', NULL, '詠雙白鷺 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6b73bba-eac6-46e0-a5f6-d0ea0fa5e936', '晴詩', '晴诗', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["晚虹斜日塞天昏，一半山川帶雨痕。","新水亂侵青草路，殘煙猶傍綠楊村。","胡人羊馬休南牧，漢將旌旗在北門。","行子喜聞無戰伐，閑看遊騎獵秋原。"]', '["晚虹斜日塞天昏，一半山川带雨痕。","新水亂侵青草路，殘煙猶傍綠楊村。","胡人羊马休南牧，漢將旌旗在北门。","行子喜闻無戰伐，闲看游騎獵秋原。"]', '诗', 'shi', '', NULL, '晴詩 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f940e81-a45b-4f3d-8829-43c433da6ab5', '送徐山人歸睦州舊隱', '送徐山人归睦州旧隐', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["君在桐廬何處住，草堂應與戴家鄰。","初歸山犬翻驚主，久別江鷗却避人。","終日欲爲相逐計，臨岐空羨獨行身。","秋風釣艇遙相憶，七里灘西片月新。"]', '["君在桐廬何处住，草堂應與戴家鄰。","初归山犬翻驚主，久別江鷗却避人。","終日欲爲相逐計，臨岐空羨独行身。","秋风釣艇遙相憶，七里灘西片月新。"]', '诗', 'shi', '', NULL, '送徐山人歸睦州舊隱 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8fcdc71-3b18-424c-a250-ce19088b64ec', '到蜀後記途中經歷', '到蜀後記途中經歷', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["劒峯重疊雪雲漫，憶昨來時處處難。","大散嶺頭春足雨，褒斜谷裏夏猶寒。","蜀門去國三千里，巴路登山八十盤。","自到成都燒酒熟，不思身更入長安。"]', '["劒峯重叠雪云漫，憶昨来时处处难。","大散嶺头春足雨，褒斜谷裏夏猶寒。","蜀门去国三千里，巴路登山八十盤。","自到成都燒酒熟，不思身更入长安。"]', '诗', 'shi', '', NULL, '到蜀後記途中經歷 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55543300-bb16-4e6e-b0ce-3422a17c1cea', '憶山寄僧', '憶山寄僧', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["塵路誰知蹋雪蹤，到來空認出雲峯。","天晴遠見月中樹，風便細聽煙際鐘。","閱世數思僧並院，憶山長羨鶴歸松。","新愁舊恨多難說，半在眉間半在胸。"]', '["塵路誰知蹋雪蹤，到来空認出云峯。","天晴远见月中樹，风便細听煙際鐘。","閱世數思僧並院，憶山长羨鹤归松。","新愁旧恨多难说，半在眉间半在胸。"]', '诗', 'shi', '', NULL, '憶山寄僧 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a9ddafd-10aa-4315-83e8-d07579fe7e9f', '贈玉芝觀王尊師', '贈玉芝观王尊師', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["處處煙霞尋總遍，却來城市喜逢師。","時流見說無人在，年紀唯應有鶴知。","大藥已成寧畏晚，小松初種不嫌遲。","長憂一日歸天去，未授靈方遣問誰。"]', '["处处煙霞尋總遍，却来城市喜逢師。","时流见说無人在，年紀唯應有鹤知。","大藥已成寧畏晚，小松初種不嫌遲。","长憂一日归天去，未授靈方遣问誰。"]', '诗', 'shi', '', NULL, '贈玉芝觀王尊師 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e986045-2e4d-489b-8910-963b8c8d4c95', '哭饒州吳諫議使君', '哭饒州吳諫議使君', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["忽聞身謝滿朝驚，俄感鄱陽罷市情。","遺愛永存今似古，高名不朽死如生。","神仙難見青騾事，諫議空留白馬名。","授館曾爲門下客，幾迴垂淚過宣平。"]', '["忽闻身謝满朝驚，俄感鄱陽罷市情。","遺愛永存今似古，高名不朽死如生。","神仙难见青騾事，諫議空留白马名。","授館曾爲门下客，幾迴垂泪過宣平。"]', '诗', 'shi', '', NULL, '哭饒州吳諫議使君 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46029df5-24e5-4990-b730-31d3940ee419', '經杜甫舊宅', '經杜甫旧宅', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["浣花溪裏花多處，爲憶先生在蜀時。","萬古只應留舊宅，千金無復換新詩。","沙崩水檻鷗飛盡，樹壓村橋馬過遲。","山月不知人事變，夜來江上與誰期。"]', '["浣花溪裏花多处，爲憶先生在蜀时。","万古只應留旧宅，千金無复換新诗。","沙崩水檻鷗飞尽，樹壓村橋马過遲。","山月不知人事变，夜来江上與誰期。"]', '诗', 'shi', '', NULL, '經杜甫舊宅 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51fed55b-4e4a-4bcf-81d1-43fa4af68d20', '河陰新城', '河陰新城', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["高城新築壓長川，虎踞龍盤氣色全。","五里似雲根不動，一重如月暈長圓。","河流暗與溝池合，山色遙將睥睨連。","自有此來當汴口，武牢何用鎖風煙。"]', '["高城新築壓长川，虎踞龙盤氣色全。","五里似云根不动，一重如月暈长圓。","河流暗與溝池合，山色遙將睥睨連。","自有此来當汴口，武牢何用鎖风煙。"]', '诗', 'shi', '', NULL, '河陰新城 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce799406-a49b-4646-ae01-49120de3cc37', '秋居病中', '秋居病中', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["幽居悄悄何人到，落日清涼滿樹梢。","新句有時愁裏得，古方無效病來拋。","荒簷數蝶懸蛛網，空屋孤螢入燕巢。","獨臥南窗秋色晚，一庭紅葉掩衡茅。"]', '["幽居悄悄何人到，落日清涼满樹梢。","新句有时愁裏得，古方無效病来拋。","荒簷數蝶懸蛛網，空屋孤螢入燕巢。","独臥南窗秋色晚，一庭紅葉掩衡茅。"]', '诗', 'shi', '', NULL, '秋居病中 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09da74fc-bb33-417e-b21d-54de471a641e', '罷還邊將', '罷還邊將', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["白鬚虜將話邊事，自失公權怨語多。","漢主豈勞思李牧，趙王猶是用廉頗。","新鷹飽肉唯閑獵，舊劒生衣嬾更磨。","百戰無功身老去，羨他年少渡黃河。"]', '["白鬚虜將話邊事，自失公權怨語多。","漢主豈勞思李牧，趙王猶是用廉頗。","新鷹飽肉唯闲獵，旧劒生衣嬾更磨。","百戰無功身老去，羨他年少渡黄河。"]', '诗', 'shi', '', NULL, '罷還邊將 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('997c7f3c-b416-442a-871d-1b2ed86d53c3', '永樂殷堯藩明府縣池嘉蓮詠', '永乐殷堯藩明府縣池嘉蓮詠', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["青蘋白石匝蓮塘，水裏蓮開帶瑞光。","露濕紅芳雙朵重，風飄綠蔕一枝長。","同心梔子徒誇豔，合穗嘉禾豈解香。","不獨豐祥先有應，更宜花縣對潘郎。"]', '["青蘋白石匝蓮塘，水裏蓮开带瑞光。","露濕紅芳雙朵重，风飄綠蔕一枝长。","同心梔子徒誇豔，合穗嘉禾豈解香。","不独豐祥先有應，更宜花縣对潘郎。"]', '诗', 'shi', '', NULL, '永樂殷堯藩明府縣池嘉蓮詠 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0a1eb79-2490-48d7-98de-1402ebc5cabd', '詶李紺歲除送酒', '詶李紺歲除送酒', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["歲盡貧生事事須，就中深恨酒錢無。","故人充壽能分送，遠客消愁免自沽。","一夜四乘傾鑿落，五更三點把屠蘇。","已供時節深珍重，況許今朝更挈壺。"]', '["歲尽貧生事事須，就中深恨酒錢無。","故人充壽能分送，远客消愁免自沽。","一夜四乘傾鑿落，五更三点把屠蘇。","已供时節深珍重，況許今朝更挈壺。"]', '诗', 'shi', '', NULL, '詶李紺歲除送酒 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f1ebde3-7bbd-4265-802a-e31b2444e864', '蜀路倦行因有所感', '蜀路倦行因有所感', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["亂峯碎石金牛路，過客應騎鐵馬行。","白日欲斜催後乘，青雲何處問前程？","飛蠅一一皆先去，度鳥雙雙亦遠鳴。","蹇步不唯傷旅思，此中兼見宦途情。"]', '["亂峯碎石金牛路，過客應騎鐵马行。","白日欲斜催後乘，青云何处问前程？","飞蠅一一皆先去，度鸟雙雙亦远鳴。","蹇步不唯傷旅思，此中兼见宦途情。"]', '诗', 'shi', '', NULL, '蜀路倦行因有所感 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9632ef0e-385e-4ec2-88ff-9f80fdd52463', '寄永樂殷堯藩明府', '寄永乐殷堯藩明府', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["古縣蕭條秋景晚，昔年陶令亦如君。","頭巾漉酒臨黃菊，手[板]支頤向白雲。","百里豈能容驥足，九霄終自別雞羣。","相思不恨書來少，佳句多從闕下聞。"]', '["古縣蕭條秋景晚，昔年陶令亦如君。","头巾漉酒臨黄菊，手[板]支頤向白云。","百里豈能容驥足，九霄終自別雞羣。","相思不恨书来少，佳句多從闕下闻。"]', '诗', 'shi', '', NULL, '寄永樂殷堯藩明府 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06ec6a0b-4db5-4104-aa04-9fa73e229134', '蜀中戰後感事', '蜀中戰後感事', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["蜀道英靈地，山重水又回。","文章四子盛，道路五丁開。","詞客題橋去，忠臣叱馭來。","臥龍同駭浪，躍馬比浮埃。","已謂無妖土，那知有禍胎。","蕃兵依𣾴柳，蠻斾指江梅。","戰後悲逢血，燒餘恨見灰。","空留犀厭怪，無復酒除災。","歲積萇弘怨，春深杜宇哀。","家貧移未得，愁上望鄉臺。"]', '["蜀道英靈地，山重水又回。","文章四子盛，道路五丁开。","词客題橋去，忠臣叱馭来。","臥龙同駭浪，躍马比浮埃。","已謂無妖土，那知有禍胎。","蕃兵依𣾴柳，蠻斾指江梅。","戰後悲逢血，燒餘恨见灰。","空留犀厭怪，無复酒除災。","歲積萇弘怨，春深杜宇哀。","家貧移未得，愁上望乡台。"]', '诗', 'shi', '', NULL, '蜀中戰後感事 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32e5bd2d-a284-40d9-8560-c7ea7235c0f5', '荅蜀中經蠻後友人馬艾見寄', '荅蜀中經蠻後友人马艾见寄', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["茜馬渡瀘水，北來如鳥輕。","幾年朝鳳闕，一日破龜城。","此地有征戰，誰家無死生。","人悲還舊里，鳥喜下空營。","弟姪意初定，交朋心尚驚。","自從經難後，吟苦似猿聲。"]', '["茜马渡瀘水，北来如鸟轻。","幾年朝鳳闕，一日破龟城。","此地有征戰，誰家無死生。","人悲還旧里，鸟喜下空營。","弟姪意初定，交朋心尚驚。","自從經难後，吟苦似猿声。"]', '诗', 'shi', '', NULL, '荅蜀中經蠻後友人馬艾見寄 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6628482-6536-4067-90c5-d1b02cb347be', '盧岳閑居十韻', '盧岳闲居十韻', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["擾擾走人寰，爭如占得閑。","防愁心付酒，求靜力登山。","見藥芳時採，逢花好處攀。","望雲開病眼，臨澗洗愁顏。","春色流巖下，秋聲碎竹間。","錦文苔點點，錢樣菊斑斑。","路遠朝無客，門深夜不關。","鶴飛高縹緲，鶯語巧綿蠻。","養拙甘沈默，忘懷絕險艱。","更憐雲外路，空去又空還。"]', '["擾擾走人寰，爭如占得闲。","防愁心付酒，求静力登山。","见藥芳时採，逢花好处攀。","望云开病眼，臨澗洗愁顏。","春色流巖下，秋声碎竹间。","錦文苔点点，錢樣菊斑斑。","路远朝無客，门深夜不关。","鹤飞高縹緲，鶯語巧綿蠻。","養拙甘沈默，忘懷絕險艱。","更怜云外路，空去又空還。"]', '诗', 'shi', '', NULL, '盧岳閑居十韻 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('773f76c6-5be9-4050-9723-2b89bdae4e33', '送于中丞使北蕃', '送于中丞使北蕃', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["朔將引雙旌，山遙磧雪平。","經年通國信，計日得蕃情。","野次依泉宿，沙中望火行。","遠鵰秋有力，寒馬夜無聲。","看獵臨胡帳，思鄉見漢城。","來春擁邊騎，新草滿歸程。"]', '["朔將引雙旌，山遙磧雪平。","經年通国信，計日得蕃情。","野次依泉宿，沙中望火行。","远鵰秋有力，寒马夜無声。","看獵臨胡帳，思乡见漢城。","来春擁邊騎，新草满归程。"]', '诗', 'shi', '', NULL, '送于中丞使北蕃 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47bbf9de-0bca-45be-b958-fbddeeb7512a', '和河南白尹西池北新葺水齋招賞十二韻', '和河南白尹西池北新葺水斋招賞十二韻', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["二室峯前水，三川府右亭。","亂流深竹逕，分遶小花汀。","池角通泉脈，堂心豁地形。","坐中寒瑟瑟，牀下細泠泠。","雨夜思巫峽，秋朝想洞庭。","千年孤鏡碧，一片遠天青。","魚戲搖紅尾，鷗閑退白翎。","荷傾瀉珠露，沙亂動金星。","藤架如紗帳，苔牆似錦屏。","龍門人少到，仙棹自多停。","游憶高僧伴，吟招野客聽。","餘波不能惜，便欲養浮萍。"]', '["二室峯前水，三川府右亭。","亂流深竹逕，分遶小花汀。","池角通泉脈，堂心豁地形。","坐中寒瑟瑟，牀下細泠泠。","雨夜思巫峽，秋朝想洞庭。","千年孤镜碧，一片远天青。","鱼戲搖紅尾，鷗闲退白翎。","荷傾瀉珠露，沙亂动金星。","藤架如紗帳，苔牆似錦屏。","龙门人少到，仙棹自多停。","游憶高僧伴，吟招野客听。","餘波不能惜，便欲養浮萍。"]', '诗', 'shi', '', NULL, '和河南白尹西池北新葺水齋招賞十二韻 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a66f7be8-b89b-472f-956c-31efd573429f', '感興', '感兴', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["貧女貌非醜，要須緣嫁遲。","還似求名客，無媒不及時。"]', '["貧女貌非醜，要須緣嫁遲。","還似求名客，無媒不及时。"]', '诗', 'shi', '', NULL, '感興 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1863ef7-4329-4565-90f8-ec88d7c7ec50', '長安客感', '长安客感', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["日過千萬家，一家非所依。","不及行塵影，猶隨馬蹄歸。"]', '["日過千万家，一家非所依。","不及行塵影，猶隨马蹄归。"]', '诗', 'shi', '', NULL, '長安客感 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df3dcbc5-cbdc-4c41-863f-9854a0f1779f', '春懷舊游', '春懷旧游', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["吟想舊經過，花時奈遠何。","別來長似見，春夢入關多。"]', '["吟想旧經過，花时奈远何。","別来长似见，春梦入关多。"]', '诗', 'shi', '', NULL, '春懷舊游 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f4a339e-b4f4-472a-9355-28e1d409cb48', '離京城宿商山作', '離京城宿商山作', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["山月吟聲苦，春風引思長。","無由及塵土，猶帶杏花香。"]', '["山月吟声苦，春风引思长。","無由及塵土，猶带杏花香。"]', '诗', 'shi', '', NULL, '離京城宿商山作 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82752dc9-5dc8-4e2f-8a47-871d1d9afca9', '秋館雨夜', '秋館雨夜', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["夜雨空館靜，幽人起裴回。","長安醉眠客，豈知新鴈來。"]', '["夜雨空館静，幽人起裴回。","长安醉眠客，豈知新鴈来。"]', '诗', 'shi', '', NULL, '秋館雨夜 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9736cffd-e84d-432c-a95a-0fcd7aff143c', '聞子規', '闻子規', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["百鳥有啼時，子規聲不歇。","春寒四鄰靜，獨叫三更月。"]', '["百鸟有啼时，子規声不歇。","春寒四鄰静，独叫三更月。"]', '诗', 'shi', '', NULL, '聞子規 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1a5b5ca-86c5-4188-b596-b8470e9a3588', '懷無可上人', '懷無可上人', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["山寺秋時後，僧家夏滿時。","清涼多古跡，幾處有新詩。"]', '["山寺秋时後，僧家夏满时。","清涼多古跡，幾处有新诗。"]', '诗', 'shi', '', NULL, '懷無可上人 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0275485d-b5e1-4e1d-9c89-4e0800d3b433', '長安客感', '长安客感', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["客淚如危葉，長懸零落心。","況是悲秋日，臨風制不禁。"]', '["客泪如危葉，长懸零落心。","況是悲秋日，臨风制不禁。"]', '诗', 'shi', '', NULL, '長安客感 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ace8d2e7-ac57-4e08-b5ca-058ee2a393a8', '送客遙望', '送客遙望', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["別遠心更苦，遙將目送君。","光華不可見，孤鶴沒秋雲。"]', '["別远心更苦，遙將目送君。","光华不可见，孤鹤沒秋云。"]', '诗', 'shi', '', NULL, '送客遙望 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f6dab81-59e0-4f1a-96e9-6e7fbd0e8979', '傷靡草', '傷靡草', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["靡草似客心，年年亦先死。","無由伴花落，暫得因風起。"]', '["靡草似客心，年年亦先死。","無由伴花落，暫得因风起。"]', '诗', 'shi', '', NULL, '傷靡草 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f5853c3-c168-48aa-8761-33d1ecae62bc', '放鶴', '放鹤', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["從今一去不須低，見說遼東好去棲。","努力莫辭仙路遠，白雲飛處免羣雞。"]', '["從今一去不須低，见说遼东好去棲。","努力莫辞仙路远，白云飞处免羣雞。"]', '诗', 'shi', '', NULL, '放鶴 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68c2d980-05a9-4967-865a-10b02cfe0966', '早秋月夜', '早秋月夜', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["身閑伴月夜深行，風觸衣裳四體輕。","爲見近來天氣好，幾篇詩興入秋成。"]', '["身闲伴月夜深行，风觸衣裳四體轻。","爲见近来天氣好，幾篇诗兴入秋成。"]', '诗', 'shi', '', NULL, '早秋月夜 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5281616-fd34-4fff-b9a7-3ae56e73c5b8', '蟬', '蟬', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["高樹蟬聲入晚雲，不唯愁我亦愁君。","何時各得身無事，每到聞時似不聞。"]', '["高樹蟬声入晚云，不唯愁我亦愁君。","何时各得身無事，每到闻时似不闻。"]', '诗', 'shi', '', NULL, '蟬 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d199dc3-5e23-4ea2-8fd5-b941bbeaef41', '公子行', '公子行', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["公子風流嫌錦繡，新裁白紵作春衣。","金鞭留當誰家酒，拂柳穿花信馬歸。"]', '["公子风流嫌錦繡，新裁白紵作春衣。","金鞭留當誰家酒，拂柳穿花信马归。"]', '诗', 'shi', '', NULL, '公子行 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b3ba1a2-fa7f-4867-995a-e716a4ec58b4', '題情盡橋', '題情尽橋', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["從來只有情難盡，何事名爲情盡橋。","自此改名爲折柳，任他離恨一條條。"]', '["從来只有情难尽，何事名爲情尽橋。","自此改名爲折柳，任他離恨一條條。"]', '诗', 'shi', '', NULL, '題情盡橋 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b01efbd-02ec-4187-8db6-00011c47b9a6', '峽中行', '峽中行', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["兩崖開盡水回環，一葉纔通石罅間。","楚客莫言山勢險，世人心更險於山。"]', '["兩崖开尽水回环，一葉纔通石罅间。","楚客莫言山勢險，世人心更險於山。"]', '诗', 'shi', '', NULL, '峽中行 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a13ddfc2-a8d9-4b2f-b3c7-9f4522f69f6f', '韋處士郊居', '韋处士郊居', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["滿庭詩境飄紅葉，繞砌琴聲滴暗泉。","門外晚晴秋色老，萬條寒玉一溪煙。"]', '["满庭诗境飄紅葉，繞砌琴声滴暗泉。","门外晚晴秋色老，万條寒玉一溪煙。"]', '诗', 'shi', '', NULL, '韋處士郊居 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c604c137-7a45-4a46-935a-de348a28cc1a', '秋懷', '秋懷', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["古槐煙薄晚鴉愁，獨向黃昏立御溝。","南國望中生遠思，一行新鴈去汀洲。"]', '["古槐煙薄晚鴉愁，独向黄昏立御溝。","南国望中生远思，一行新鴈去汀洲。"]', '诗', 'shi', '', NULL, '秋懷 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('185b0401-991c-49e1-8230-c79729846aea', '再下第將歸荆楚上白舍人', '再下第將归荆楚上白舍人', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["窮通應計一時間，今日甘從刖足還。","長倚玉人心自醉，不辭歸去哭荆山。"]', '["窮通應計一时间，今日甘從刖足還。","长倚玉人心自醉，不辞归去哭荆山。"]', '诗', 'shi', '', NULL, '再下第將歸荆楚上白舍人 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('454cc153-21c1-4f60-a4a0-20206159ed59', '春行武關作', '春行武关作', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["風香春暖展歸程，全勝遊仙入洞情。","一路緣溪花覆水，不妨閑看不妨行。"]', '["风香春暖展归程，全勝游仙入洞情。","一路緣溪花覆水，不妨闲看不妨行。"]', '诗', 'shi', '', NULL, '春行武關作 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('271a28b6-c938-4d63-820c-3cc9823b185d', '恨別二首 一', '恨別二首 一', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["知君餞酒深深意，圖使行人涕不流。","如今卻恨酒中別，不得一言千里愁。"]', '["知君餞酒深深意，圖使行人涕不流。","如今卻恨酒中別，不得一言千里愁。"]', '诗', 'shi', '', NULL, '恨別二首 一 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fef4bf7-fe52-4e72-a735-28f9450b009e', '恨別二首 二', '恨別二首 二', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["人言日遠還疎索，別後都非未別心。","唯我憶君千里意，一年不見一重深。"]', '["人言日远還疎索，別後都非未別心。","唯我憶君千里意，一年不见一重深。"]', '诗', 'shi', '', NULL, '恨別二首 二 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0e6bb57-7c66-4b07-a870-b8480c5fc134', '送人歸吳', '送人归吳', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["遠愛春波正滿湖，羨君東去是歸途。","吟詩好向月中宿，一叫水天沙鶴孤。"]', '["远愛春波正满湖，羨君东去是归途。","吟诗好向月中宿，一叫水天沙鹤孤。"]', '诗', 'shi', '', NULL, '送人歸吳 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23d71422-51f5-4102-aa3f-ac5f699a2ffb', '喜夢歸', '喜梦归', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["旅館歲闌頻有夢，分明最似此宵希。","覺來莫道還無益，未得歸時且當歸。"]', '["旅館歲闌頻有梦，分明最似此宵希。","覺来莫道還無益，未得归时且當归。"]', '诗', 'shi', '', NULL, '喜夢歸 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fda0464b-d28c-4b55-b83c-c8d385a2753e', '路中問程知欲達青雲驛', '路中问程知欲達青云驛', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["行愁驛路問來人，西去經過願一聞。","落日回鞭相指點，前程從此是青雲。"]', '["行愁驛路问来人，西去經過願一闻。","落日回鞭相指点，前程從此是青云。"]', '诗', 'shi', '', NULL, '路中問程知欲達青雲驛 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f5e562a-ff78-42e3-8c1b-d9b3686907c5', '題君山', '題君山', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["風波不動影沈沈，翠色全微碧色深。","應是水仙梳洗處，一螺青黛鏡中心。"]', '["风波不动影沈沈，翠色全微碧色深。","應是水仙梳洗处，一螺青黛镜中心。"]', '诗', 'shi', '', NULL, '題君山 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcdb22e2-d567-4001-a280-e36d5af8b18f', '離家後作', '離家後作', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["世上無媒似我希，一身惟有影相隨。","出門便作焚舟計，生不成名死不歸。"]', '["世上無媒似我希，一身惟有影相隨。","出门便作焚舟計，生不成名死不归。"]', '诗', 'shi', '', NULL, '離家後作 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bc24bea-e491-4ef4-9037-ebfb1d5ae116', '寄題峴亭', '寄題峴亭', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["峴亭留恨爲傷杯，未得醒醒看便回。","卻想醉游如夢見，直疑元本不曾來。"]', '["峴亭留恨爲傷杯，未得醒醒看便回。","卻想醉游如梦见，直疑元本不曾来。"]', '诗', 'shi', '', NULL, '寄題峴亭 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b36f5e87-a4f1-43f2-a6d1-3a35c262cf7e', '病鶴', '病鹤', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["憶得當時病未遭，身爲仙馭雪爲毛。","今來沙上飛無力，羞見檣烏立處高。"]', '["憶得當时病未遭，身爲仙馭雪爲毛。","今来沙上飞無力，羞见檣烏立处高。"]', '诗', 'shi', '', NULL, '病鶴 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('685d2b2d-54ec-42f5-a5fc-f820297948c4', '狀春', '狀春', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["含春笑日花心豔，帶雨牽風柳態妖。","珍重兩般堪比處，醉時紅臉舞時腰。"]', '["含春笑日花心豔，带雨牽风柳態妖。","珍重兩般堪比处，醉时紅臉舞时腰。"]', '诗', 'shi', '', NULL, '狀春 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('519ee5bd-bf84-4ba7-bf20-20c7d56f24bc', '春詠', '春詠', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["風惱花枝不耐頻，等閑飛落易愁人。","殷勤最是章臺柳，一樹千條管帶春。"]', '["风惱花枝不耐頻，等闲飞落易愁人。","殷勤最是章台柳，一樹千條管带春。"]', '诗', 'shi', '', NULL, '春詠 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59a794f6-e56e-434b-8e94-ceb9edf97e96', '非酒', '非酒', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["人人慢說酒消憂，我道翻爲引恨由。","一夜醒來燈火暗，不應愁事亦成愁。"]', '["人人慢说酒消憂，我道翻爲引恨由。","一夜醒来灯火暗，不應愁事亦成愁。"]', '诗', 'shi', '', NULL, '非酒 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ccc9c65-c2e3-4b90-b682-c0b20bb23267', '苦寒', '苦寒', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["今年無異去年寒，何事朝來獨忍難。","應是漸爲貧客久，錦衣著盡布衣單。"]', '["今年無異去年寒，何事朝来独忍难。","應是漸爲貧客久，錦衣著尽布衣單。"]', '诗', 'shi', '', NULL, '苦寒 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5642809b-e7a0-4822-9998-85a505373808', '送客', '送客', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["若論秋思人人苦，最覺愁多客又深。","何況病來惆悵盡，不知爭作送君心。"]', '["若論秋思人人苦，最覺愁多客又深。","何況病来惆悵尽，不知爭作送君心。"]', '诗', 'shi', '', NULL, '送客 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8c0fb8a-68ed-4776-a28f-a6dbd190a327', '人問應舉', '人问應舉', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["莫驚西上獨遲迴，只爲衡門未有媒。","惆悵賦成身不去，一名閑事逐秋回。"]', '["莫驚西上独遲迴，只爲衡门未有媒。","惆悵賦成身不去，一名闲事逐秋回。"]', '诗', 'shi', '', NULL, '人問應舉 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62e4f8c3-ae49-46f7-91a1-99350292cd7d', '送客不及', '送客不及', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["水闊江天兩不分，行人兩處更相聞。","遙遙已失風帆影，半日虛銷指點雲。"]', '["水闊江天兩不分，行人兩处更相闻。","遙遙已失风帆影，半日虛銷指点云。"]', '诗', 'shi', '', NULL, '送客不及 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7b77900-69fb-4320-9bc5-7625d6acdce9', '聞杜鵑二首 一', '闻杜鵑二首 一', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["碧竿微露月玲瓏，謝豹傷心獨叫風。","高處已應聞滴血，山榴一夜幾枝紅。"]', '["碧竿微露月玲瓏，謝豹傷心独叫风。","高处已應闻滴血，山榴一夜幾枝紅。"]', '诗', 'shi', '', NULL, '聞杜鵑二首 一 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43f9c536-92c4-4567-b655-661b714d34c2', '聞杜鵑二首 二', '闻杜鵑二首 二', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["蜀客春城聞蜀鳥，思歸聲引未歸心。","卻知夜夜愁相似，爾正啼時我正吟。"]', '["蜀客春城闻蜀鸟，思归声引未归心。","卻知夜夜愁相似，爾正啼时我正吟。"]', '诗', 'shi', '', NULL, '聞杜鵑二首 二 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0604d5bb-0e38-4384-aa23-cecfa2c6eaaf', '西歸出斜谷', '西归出斜谷', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["行過險棧出褒斜，出盡平川似到家。","萬里客愁今日散，馬前初見米囊花。"]', '["行過險棧出褒斜，出尽平川似到家。","万里客愁今日散，马前初见米囊花。"]', '诗', 'shi', '', NULL, '西歸出斜谷 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed58dbdf-a5b3-4ebe-b180-4a480c2450a8', '宿嘉陵驛', '宿嘉陵驛', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["離思茫茫正值秋，每因風景卻生愁。","今宵難作刀州夢，月色江聲共一樓。"]', '["離思茫茫正值秋，每因风景卻生愁。","今宵难作刀州梦，月色江声共一楼。"]', '诗', 'shi', '', NULL, '宿嘉陵驛 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79e14711-13e9-43a4-8170-16d6e2f8f450', '旅懷', '旅懷', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["舊里已悲無產業，故山猶戀有煙霞。","自從爲客歸時少，旅館僧房卻是家。"]', '["旧里已悲無產業，故山猶戀有煙霞。","自從爲客归时少，旅館僧房卻是家。"]', '诗', 'shi', '', NULL, '旅懷 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a578133-51ba-4fe8-998c-94177843d2d0', '貧居春怨', '貧居春怨', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["貧居盡日冷風煙，獨向簷牀看雨眠。","寂寞春風花落盡，滿庭榆莢似秋天。"]', '["貧居尽日冷风煙，独向簷牀看雨眠。","寂寞春风花落尽，满庭榆莢似秋天。"]', '诗', 'shi', '', NULL, '貧居春怨 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb5eae9e-835d-4b27-9f23-125b58d9ccc9', '憶江南舊居', '憶江南旧居', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["閑思往事在湖亭，亭上秋燈照月明。","宿客盡眠眠不得，半牕窗殘月帶潮聲。"]', '["闲思往事在湖亭，亭上秋灯照月明。","宿客尽眠眠不得，半牕窗殘月带潮声。"]', '诗', 'shi', '', NULL, '憶江南舊居 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82a1c3be-15ca-4599-a6d7-9c8f2d406b78', '夷陵城', '夷陵城', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["世家曾覽楚英雄，國破城荒萬事空。","唯有郵亭階下柳，春來猶似細腰宮。"]', '["世家曾覽楚英雄，国破城荒万事空。","唯有郵亭階下柳，春来猶似細腰宮。"]', '诗', 'shi', '', NULL, '夷陵城 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c77fb633-9cea-407c-8922-12546d7472de', '訪友人幽居二首 一', '訪友人幽居二首 一', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["落花門外春將盡，飛絮庭前日欲高。","深院客來人未起，黃鸝枝上啄櫻桃。"]', '["落花门外春將尽，飞絮庭前日欲高。","深院客来人未起，黄鸝枝上啄櫻桃。"]', '诗', 'shi', '', NULL, '訪友人幽居二首 一 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97354cfc-c230-4ad3-9b11-0e0b98e7b1a9', '訪友人幽居二首 二', '訪友人幽居二首 二', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["莎深苔滑地無塵，竹冷花遲剩駐春。","盡日弄琴誰共聽，與君兼鶴是三人。"]', '["莎深苔滑地無塵，竹冷花遲剩駐春。","尽日弄琴誰共听，與君兼鹤是三人。"]', '诗', 'shi', '', NULL, '訪友人幽居二首 二 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ec9f861-5e65-4680-aecd-15d6d85ead53', '宿大徹禪師故院', '宿大徹禪師故院', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["竹房誰繼生前事，松月空懸過去心。","秋磬數聲天欲曉，影堂斜掩一燈深。"]', '["竹房誰繼生前事，松月空懸過去心。","秋磬數声天欲晓，影堂斜掩一灯深。"]', '诗', 'shi', '', NULL, '宿大徹禪師故院 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c46bce1c-f4c3-4342-9bf3-eeffb240d03a', '送蜀客', '送蜀客', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["劒南風景臘前春，山鳥江風得雨新。","莫怪送君行較遠，自緣身是憶歸人。"]', '["劒南风景臘前春，山鸟江风得雨新。","莫怪送君行較远，自緣身是憶归人。"]', '诗', 'shi', '', NULL, '送蜀客 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd9c13f8-4dd5-4a24-9645-7ccf8a33d734', '題寶應縣', '題寶應縣', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["雪樓當日動晴寒，渭水梁山鳥外看。","聞說德宗曾到此，吟詩不敢倚闌干。"]', '["雪楼當日动晴寒，渭水梁山鸟外看。","闻说德宗曾到此，吟诗不敢倚闌干。"]', '诗', 'shi', '', NULL, '題寶應縣 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc34afc8-6de8-480c-a039-06b4ef25a487', '和孫明府懷舊山', '和孫明府懷旧山', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["五柳先生本在山，偶然爲客落人間。","秋來見月多歸思，自起開籠放白鷴。"]', '["五柳先生本在山，偶然爲客落人间。","秋来见月多归思，自起开籠放白鷴。"]', '诗', 'shi', '', NULL, '和孫明府懷舊山 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c8cd3bd-4cd4-428b-8fa9-e88c13c6e5ee', '城西訪友人別墅', '城西訪友人別墅', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["澧水橋西小路斜，日高猶未到君家。","村園門巷多相似，處處春風枳殼花。"]', '["澧水橋西小路斜，日高猶未到君家。","村园门巷多相似，处处春风枳殼花。"]', '诗', 'shi', '', NULL, '城西訪友人別墅 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5c830c6-4bb3-4a89-92a2-d49251cb4039', '題大安池亭', '題大安池亭', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["幽島曲池相隱映，小橋虛閣半高低。","好風好月無人宿，夜夜水禽船上棲。"]', '["幽島曲池相隐映，小橋虛閣半高低。","好风好月無人宿，夜夜水禽船上棲。"]', '诗', 'shi', '', NULL, '題大安池亭 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62078cee-7614-4160-8b0e-da2578bc5498', '送春', '送春', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["勿言春盡春還至，少壯看花復幾回。","今日已從愁裏去，明年更莫共愁來。"]', '["勿言春尽春還至，少壯看花复幾回。","今日已從愁裏去，明年更莫共愁来。"]', '诗', 'shi', '', NULL, '送春 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a07c63bc-6070-46bf-a533-96f93af2ec7e', '武侯廟古柏', '武侯廟古柏', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["密葉四時同一色，高枝千歲對孤峯。","此中疑有精靈在，爲見盤根似臥龍。"]', '["密葉四时同一色，高枝千歲对孤峯。","此中疑有精靈在，爲见盤根似臥龙。"]', '诗', 'shi', '', NULL, '武侯廟古柏 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e2e4f2f-4b7f-4034-a7ec-a444ce875a8c', '哀蜀人爲南蠻俘虜五章 初出成都聞哭聲', '哀蜀人爲南蠻俘虜五章 初出成都闻哭声', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["但見城池還漢將，豈知佳麗屬蠻兵。","錦江南度遙聞哭，盡是離家別國聲。"]', '["但见城池還漢將，豈知佳丽屬蠻兵。","錦江南度遙闻哭，尽是離家別国声。"]', '诗', 'shi', '', NULL, '哀蜀人爲南蠻俘虜五章 初出成都聞哭聲 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edb9bc9d-5e6d-4c59-8e3b-25d7ebb54ee3', '哀蜀人爲南蠻俘虜五章 過大渡河蠻使許之泣望鄉國', '哀蜀人爲南蠻俘虜五章 過大渡河蠻使許之泣望乡国', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["大渡河邊蠻亦愁，漢人將渡盡回頭。","此中剩寄思鄉淚，南去應無水北流。"]', '["大渡河邊蠻亦愁，漢人將渡尽回头。","此中剩寄思乡泪，南去應無水北流。"]', '诗', 'shi', '', NULL, '哀蜀人爲南蠻俘虜五章 過大渡河蠻使許之泣望鄉國 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f759b115-8a12-4a56-9fe4-cd034dc5643f', '哀蜀人爲南蠻俘虜五章 出青溪關有遲留之意', '哀蜀人爲南蠻俘虜五章 出青溪关有遲留之意', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["欲出鄉關行步遲，此生無復卻回時。","千冤萬恨何人見，唯有空山鳥獸知。"]', '["欲出乡关行步遲，此生無复卻回时。","千冤万恨何人见，唯有空山鸟獸知。"]', '诗', 'shi', '', NULL, '哀蜀人爲南蠻俘虜五章 出青溪關有遲留之意 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9de564c9-92f3-4e9d-b8a3-4cc14e152820', '哀蜀人爲南蠻俘虜五章 別巂州一時慟哭雲日爲之變色', '哀蜀人爲南蠻俘虜五章 別巂州一时慟哭云日爲之变色', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["越巂城南無漢地，傷心從此便爲蠻。","冤聲一慟悲風起，雲暗青天日下山。"]', '["越巂城南無漢地，傷心從此便爲蠻。","冤声一慟悲风起，云暗青天日下山。"]', '诗', 'shi', '', NULL, '哀蜀人爲南蠻俘虜五章 別巂州一時慟哭雲日爲之變色 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c3620a5-17cf-4c29-8d55-05e9145ed6db', '哀蜀人爲南蠻俘虜五章 入蠻界不許有悲泣之聲', '哀蜀人爲南蠻俘虜五章 入蠻界不許有悲泣之声', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["雲南路出陷河西，毒草長青瘴色低。","漸近蠻城誰敢哭，一時收淚羨猨啼。"]', '["云南路出陷河西，毒草长青瘴色低。","漸近蠻城誰敢哭，一时收泪羨猨啼。"]', '诗', 'shi', '', NULL, '哀蜀人爲南蠻俘虜五章 入蠻界不許有悲泣之聲 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eddef5e9-c17f-4a2b-8401-33477ef41fed', '宿石門山居', '宿石门山居', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["牕燈欲滅夜愁生，螢火飛來促織鳴。","宿客幾回眠又起，一溪秋水枕邊聲。"]', '["牕灯欲滅夜愁生，螢火飞来促织鳴。","宿客幾回眠又起，一溪秋水枕邊声。"]', '诗', 'shi', '', NULL, '宿石門山居 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('906ae2e9-d78e-44ce-95f1-0facb3cf3dfe', '過舊宅看花', '過旧宅看花', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["山桃野杏兩三栽，樹樹繁花去復開。","今日主人相引看，誰知曾是客移來。"]', '["山桃野杏兩三栽，樹樹繁花去复开。","今日主人相引看，誰知曾是客移来。"]', '诗', 'shi', '', NULL, '過舊宅看花 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('283b0f7e-c069-4c82-940a-62c1267e7322', '寄襄陽章孝標', '寄襄陽章孝標', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["青油幕下白雲邊，日日空山夜夜泉。","聞說小齋多野意，枳花陰裏麝香眠。"]', '["青油幕下白云邊，日日空山夜夜泉。","闻说小斋多野意，枳花陰裏麝香眠。"]', '诗', 'shi', '', NULL, '寄襄陽章孝標 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('122c59a4-4d5e-4553-81c7-34a8a9c17412', '洛中感事', '洛中感事', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["洛城今古足繁華，最恨喬家似石家。","行到窈娘身沒處，水邊愁見亞枝花。"]', '["洛城今古足繁华，最恨喬家似石家。","行到窈娘身沒处，水邊愁见亞枝花。"]', '诗', 'shi', '', NULL, '洛中感事 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2493c94-6bfb-4ed8-a977-63a27e7aafe2', '陰地關見入蕃公主石上手跡', '陰地关见入蕃公主石上手跡', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["漢家公主昔和蕃，石上今餘手跡存。","風雨幾年侵不滅，分明纖指印苔痕。"]', '["漢家公主昔和蕃，石上今餘手跡存。","风雨幾年侵不滅，分明纖指印苔痕。"]', '诗', 'shi', '', NULL, '陰地關見入蕃公主石上手跡 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('145f0c10-1652-446d-abd8-5f26f8a6c52e', '美人春風怨', '美人春风怨', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["澹蕩春風滿眼來，落花飛蝶共裴回。","偏能飄散同心蔕，無那愁眉吹不開。"]', '["澹蕩春风满眼来，落花飞蝶共裴回。","偏能飄散同心蔕，無那愁眉吹不开。"]', '诗', 'shi', '', NULL, '美人春風怨 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66d9c1cf-c3cb-40b6-b79e-56c037ac2942', '過南鄰花園', '過南鄰花园', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["莫怪頻過有酒家，多情長是惜年華。","春風堪賞還堪恨，纔見開花又落花。"]', '["莫怪頻過有酒家，多情长是惜年华。","春风堪賞還堪恨，纔见开花又落花。"]', '诗', 'shi', '', NULL, '過南鄰花園 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a074ff63-4c95-4b68-a783-4250b4478609', '勸行樂', '勸行乐', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["老去風光不屬身，黃金莫惜買青春。","白頭縱作花園主，醉折花枝是別人。"]', '["老去风光不屬身，黄金莫惜買青春。","白头縱作花园主，醉折花枝是別人。"]', '诗', 'shi', '', NULL, '勸行樂 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79d47a97-af2c-442d-89bc-8e7b1dff540a', '渡桑乾河', '渡桑乾河', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["南客豈曾諳塞北，年年唯見鴈飛回。","今朝忽渡桑乾水，不似身來似夢來。"]', '["南客豈曾諳塞北，年年唯见鴈飞回。","今朝忽渡桑乾水，不似身来似梦来。"]', '诗', 'shi', '', NULL, '渡桑乾河 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b304eac-7b7a-47c0-8d3c-b7cbfcf6df72', '月下喜呂郎中除兵部', '月下喜呂郎中除兵部', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["北闕雲間見碧天，南宮月似舊時圓。","喜看列宿今朝正，休嘆參差十四年。"]', '["北闕云间见碧天，南宮月似旧时圓。","喜看列宿今朝正，休嘆參差十四年。"]', '诗', 'shi', '', NULL, '月下喜呂郎中除兵部 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdf2ae96-0962-451e-a120-f3bbcd1fd167', '天津橋望春', '天津橋望春', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["津橋春水浸紅霞，煙柳風絲拂岸斜。","翠輦不來金殿閉，宮鶯銜出上陽花。"]', '["津橋春水浸紅霞，煙柳风絲拂岸斜。","翠輦不来金殿閉，宮鶯銜出上陽花。"]', '诗', 'shi', '', NULL, '天津橋望春 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de6c8f6f-65e7-47ee-a66c-3361196ad584', '自蔚州南入真谷有似劒門因有歸思', '自蔚州南入真谷有似劒门因有归思', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["我家蜀地身離久，忽見胡山似劒門。","馬上欲垂千里淚，耳邊唯欠一聲猨。"]', '["我家蜀地身離久，忽见胡山似劒门。","马上欲垂千里泪，耳邊唯欠一声猨。"]', '诗', 'shi', '', NULL, '自蔚州南入真谷有似劒門因有歸思 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40a9c093-74d2-48c0-b1e5-5f45cead2cd2', '再經天涯地角山', '再經天涯地角山', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["每憶雲山養短才，悔緣名利入塵埃。","十年馬足行多少，兩度天涯地角來。"]', '["每憶云山養短才，悔緣名利入塵埃。","十年马足行多少，兩度天涯地角来。"]', '诗', 'shi', '', NULL, '再經天涯地角山 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a663f45-4944-41ee-bf77-19c6f27559b1', '題等界寺二首 一', '題等界寺二首 一', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["吳蜀千年等界村，英雄無主豈長存。","思量往事今何在，萬里山中一寺門。"]', '["吳蜀千年等界村，英雄無主豈长存。","思量往事今何在，万里山中一寺门。"]', '诗', 'shi', '', NULL, '題等界寺二首 一 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aec396fc-9374-40ef-9ffb-3ff7f69f385f', '題等界寺二首 二', '題等界寺二首 二', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["兩國道塗都萬里，來從此地等平分。","行人競說東西利，事不關心耳不聞。"]', '["兩国道塗都万里，来從此地等平分。","行人競说东西利，事不关心耳不闻。"]', '诗', 'shi', '', NULL, '題等界寺二首 二 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e34568b3-9eb2-4c23-ab6a-597e931868f3', '洛源驛戲題', '洛源驛戲題', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["柳陰春嶺鳥新啼，暖色濃煙深處迷。","如恨往來人不見，水聲呦咽出花溪。"]', '["柳陰春嶺鸟新啼，暖色濃煙深处迷。","如恨往来人不见，水声呦咽出花溪。"]', '诗', 'shi', '', NULL, '洛源驛戲題 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11c120bd-370e-4fae-b220-783ca371bf66', '遣愁', '遣愁', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["拋擲泥中一聽沈，不能三嘆引愁深。","莫言客子無愁易，須識愁多暗損心。"]', '["拋擲泥中一听沈，不能三嘆引愁深。","莫言客子無愁易，須識愁多暗損心。"]', '诗', 'shi', '', NULL, '遣愁 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c844c80-fb5d-4cfe-9615-d40e4f1c62cf', '送友人棄官歸山居', '送友人棄官归山居', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["不愛人間紫與緋，卻思松下著山衣。","春郊雨盡多新草，一路青青蹋雨歸。"]', '["不愛人间紫與緋，卻思松下著山衣。","春郊雨尽多新草，一路青青蹋雨归。"]', '诗', 'shi', '', NULL, '送友人棄官歸山居 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2e9c93d-d2ba-4e1a-ae7f-1f845f6f9ded', '山行', '山行', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["野花幽鳥幾千般，頭白山僧遍識難。","世上遊人無復見，一生唯向畫圖看。"]', '["野花幽鸟幾千般，头白山僧遍識难。","世上游人無复见，一生唯向畫圖看。"]', '诗', 'shi', '', NULL, '山行 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('baac4c63-098b-4e93-aaa0-5e39282f60a2', '送客二首 一', '送客二首 一', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["與君同在少年場，知己蕭條壯士傷。","可惜報恩無處所，卻提孤劒過咸陽。"]', '["與君同在少年場，知己蕭條壯士傷。","可惜報恩無处所，卻提孤劒過咸陽。"]', '诗', 'shi', '', NULL, '送客二首 一 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('888e10c7-e8e1-4e6c-bbc0-4831d58b2c16', '送客二首 二', '送客二首 二', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["行人立馬強盤回，別字猶含未忍開。","好去出門休落淚，不如前路早歸來。"]', '["行人立马強盤回，別字猶含未忍开。","好去出门休落泪，不如前路早归来。"]', '诗', 'shi', '', NULL, '送客二首 二 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9bff660-8bbe-4855-9cfe-31e1f46c7c2a', '安國寺贈廣宣上人', '安国寺贈廣宣上人', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["馬急人忙塵路喧，幾從朝出到黃昏。","今來合掌聽師語，一似敲冰清耳根。"]', '["马急人忙塵路喧，幾從朝出到黄昏。","今来合掌听師語，一似敲冰清耳根。"]', '诗', 'shi', '', NULL, '安國寺贈廣宣上人 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7aaa720b-10fe-446a-921c-781f96bacd36', '初醒', '初醒', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["心中得勝暫拋愁，醉臥涼風拂簟秋。","半夜覺來新酒醒，一條斜月到牀頭。"]', '["心中得勝暫拋愁，醉臥涼风拂簟秋。","半夜覺来新酒醒，一條斜月到牀头。"]', '诗', 'shi', '', NULL, '初醒 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('524d846c-9251-439c-931c-96a586db7016', '送客歸襄陽舊居', '送客归襄陽旧居', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["襄陽耆舊別來稀，此去何人共掩扉。","唯有白銅鞮上月，水樓閑處待君歸。"]', '["襄陽耆旧別来稀，此去何人共掩扉。","唯有白銅鞮上月，水楼闲处待君归。"]', '诗', 'shi', '', NULL, '送客歸襄陽舊居 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3de8ca41-7c50-42e9-a3cd-09d8a8e02dca', '夜聞方響', '夜闻方响', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["方響聞時夜已深，聲聲敲著客愁心。","不知正在誰家樂，月下猶疑是遠砧。"]', '["方响闻时夜已深，声声敲著客愁心。","不知正在誰家乐，月下猶疑是远砧。"]', '诗', 'shi', '', NULL, '夜聞方響 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3e407cb-e48b-4bb0-9a05-8a7e25ff6382', '路逢有似亡友者惻然賦此', '路逢有似亡友者惻然賦此', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["吾友今生不可逢，風流空想舊儀容。","朝來馬上頻回首，惆悵他人似蔡邕。"]', '["吾友今生不可逢，风流空想旧儀容。","朝来马上頻回首，惆悵他人似蔡邕。"]', '诗', 'shi', '', NULL, '路逢有似亡友者惻然賦此 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('faf0ba7b-e32d-4f9c-893a-e008d9e2c213', '望月懷江上舊遊', '望月懷江上旧游', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["往歲曾隨江客船，秋風明月洞庭邊。","爲看今夜天如水，憶得當時水似天。"]', '["往歲曾隨江客船，秋风明月洞庭邊。","爲看今夜天如水，憶得當时水似天。"]', '诗', 'shi', '', NULL, '望月懷江上舊遊 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('268d8c2d-b2fc-4f84-9922-ca18d6e8248b', '途中西望', '途中西望', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["行行何處散離愁，長路無因暫上樓。","唯到高原即西望，馬知人意亦回頭。"]', '["行行何处散離愁，长路無因暫上楼。","唯到高原即西望，马知人意亦回头。"]', '诗', 'shi', '', NULL, '途中西望 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b5e1e84-ae60-48d2-a122-715654cee265', '題友人所居', '題友人所居', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["亞尹故居經幾主，只因君住有詩情。","夜吟鄰叟聞惆悵，七八年來無此聲。"]', '["亞尹故居經幾主，只因君住有诗情。","夜吟鄰叟闻惆悵，七八年来無此声。"]', '诗', 'shi', '', NULL, '題友人所居 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66047bcf-84cd-431f-a29f-355e6a6e3d78', '蔚州晏內遇新雪', '蔚州晏內遇新雪', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["胡盧河畔逢秋雪，疑是風飄白鶴毛。","坐客停杯看未定，將軍已濕褐花袍。"]', '["胡盧河畔逢秋雪，疑是风飄白鹤毛。","坐客停杯看未定，將軍已濕褐花袍。"]', '诗', 'shi', '', NULL, '蔚州晏內遇新雪 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3551a13-c26e-4099-a455-70bb9c0cc0a3', '蔚州晏內遇新雪 句', '蔚州晏內遇新雪 句', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["古木閩州道，驅羸落照間。","投村礙野水，問店隔荒山。"]', '["古木閩州道，驱羸落照间。","投村礙野水，问店隔荒山。"]', '诗', 'shi', '', NULL, '蔚州晏內遇新雪 句 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e48200a3-357b-43fd-8dd0-a8432e7b647c', '立春日', '立春日', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["暖日傍簾曉，濃春開篋紅。","釵斜穿綵燕，羅薄翦春蟲。","巧著金刀力，寒侵玉指風。","娉婷何處戴，山鬢綠成藂。"]', '["暖日傍簾晓，濃春开篋紅。","釵斜穿綵燕，羅薄翦春蟲。","巧著金刀力，寒侵玉指风。","娉婷何处戴，山鬢綠成藂。"]', '诗', 'shi', '', NULL, '立春日 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ed4857e-0b00-433c-aefd-24df862b57ae', '翦綵', '翦綵', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["翦綵贈相親，銀釵綴鳳真。","雙雙銜綬鳥，兩兩度橋人。","葉逐金刀出，花隨玉指新。","願君千萬歲，無歲不逢春。"]', '["翦綵贈相親，銀釵綴鳳真。","雙雙銜綬鸟，兩兩度橋人。","葉逐金刀出，花隨玉指新。","願君千万歲，無歲不逢春。"]', '诗', 'shi', '', NULL, '翦綵 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7133973-6d0b-4bee-b6de-9bcfd0f67969', '題僧院', '題僧院', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["不用問湯休，何人免白頭。","百年如過鳥，萬事盡浮漚。","別緒長牽夢，情由亂種愁。","却嫌風景麗，窗外碧雲秋。"]', '["不用问湯休，何人免白头。","百年如過鸟，万事尽浮漚。","別緒长牽梦，情由亂種愁。","却嫌风景丽，窗外碧云秋。"]', '诗', 'shi', '', NULL, '題僧院 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55905a23-5d50-4ca0-932e-c990214f12df', '觀廉女真葬', '观廉女真葬', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["玉窗拋翠管，輕袖掩銀鸞。","錯落雲車斷，丁泠金磬寒。","鶴尋深院宿，人借舊書看。","寂寞焚香處，紅花滿石壇。"]', '["玉窗拋翠管，轻袖掩銀鸾。","錯落云车斷，丁泠金磬寒。","鹤尋深院宿，人借旧书看。","寂寞焚香处，紅花满石壇。"]', '诗', 'shi', '', NULL, '觀廉女真葬 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('870b4a7a-aec4-4c48-b1e6-715b7ca6a5e6', '閑居', '闲居', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["塵事久相棄，沈浮皆不知。","牛羊歸古巷，燕雀遶疎籬。","買藥經年曬，留僧盡日棊。","唯憂釣魚伴，秋水隔波時。"]', '["塵事久相棄，沈浮皆不知。","牛羊归古巷，燕雀遶疎籬。","買藥經年曬，留僧尽日棊。","唯憂釣鱼伴，秋水隔波时。"]', '诗', 'shi', '', NULL, '閑居 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c582b40-4bb7-4f52-892b-e76a872845c0', '及第後送家兄遊蜀', '及第後送家兄游蜀', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["人誰無遠別，此別意多違。","正鵠雖言中，冥鴻不共飛。","玉京煙雨斷，巴國夢魂歸。","若過嚴家瀨，慇懃看釣磯。"]', '["人誰無远別，此別意多違。","正鵠雖言中，冥鴻不共飞。","玉京煙雨斷，巴国梦魂归。","若過嚴家瀨，慇懃看釣磯。"]', '诗', 'shi', '', NULL, '及第後送家兄遊蜀 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57de2aec-4d31-4870-b93e-07531830ae29', '送人入蜀', '送人入蜀', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["蜀客本多愁，君今是勝遊。","碧藏雲外樹，紅露驛邊樓。","杜魄呼名語，巴江作字流。"]', '["蜀客本多愁，君今是勝游。","碧藏云外樹，紅露驛邊楼。","杜魄呼名語，巴江作字流。"]', '诗', 'shi', '', NULL, '送人入蜀 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dafb0652-6b76-4b05-be12-1c6f10d12ae8', '遊故王駙馬池亭', '游故王駙马池亭', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["花樹杳玲瓏，漁舟處處通。","醉銷羅綺豔，香暖芰荷風。","野鳥翻萍綠，斜橋印水紅。","子猷簫管絕，誰愛碧鮮濃。"]', '["花樹杳玲瓏，漁舟处处通。","醉銷羅綺豔，香暖芰荷风。","野鸟翻萍綠，斜橋印水紅。","子猷簫管絕，誰愛碧鲜濃。"]', '诗', 'shi', '', NULL, '遊故王駙馬池亭 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('165060cb-4603-4748-809d-aaa12fe3550e', '悲銅雀臺', '悲銅雀台', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["西陵樹已盡，銅雀思偏多。","雪密疑樓閣，花開想綺羅。","影銷堂上舞，聲斷帳前歌。","唯有漳河水，年年舊綠波。"]', '["西陵樹已尽，銅雀思偏多。","雪密疑楼閣，花开想綺羅。","影銷堂上舞，声斷帳前歌。","唯有漳河水，年年旧綠波。"]', '诗', 'shi', '', NULL, '悲銅雀臺 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0329a85-c983-495e-ab69-0ac4fb2f4fe7', '陪新及第赴同年會', '陪新及第赴同年會', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["曾攀芳桂英，處處共君行。","今日杏園宴，當時天樂聲。","柳濃堪繫馬，花上未藏鶯。","滿座皆仙侶，同年別有情。"]', '["曾攀芳桂英，处处共君行。","今日杏园宴，當时天乐声。","柳濃堪繫马，花上未藏鶯。","满座皆仙侶，同年別有情。"]', '诗', 'shi', '', NULL, '陪新及第赴同年會 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85125048-bcdd-4cd7-ad88-ddde4a980bdd', '詠鴈', '詠鴈', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["早晚辭沙漠，南來處處飛。","關山多雨雪，風水損毛衣。","碧海魂應斷，紅樓信自稀。","不知矰繳外，留得幾行歸。"]', '["早晚辞沙漠，南来处处飞。","关山多雨雪，风水損毛衣。","碧海魂應斷，紅楼信自稀。","不知矰繳外，留得幾行归。"]', '诗', 'shi', '', NULL, '詠鴈 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('118acfbc-537b-43cc-bb31-9684c4168376', '與碧溪上人別', '與碧溪上人別', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["欲入鳳城遊，西溪別惠休。","色隨花旋落，年共水爭流。","客思偏來夜，蟬聲覺送秋。","明朝逢舊侶，唯擬上歌樓。"]', '["欲入鳳城游，西溪別惠休。","色隨花旋落，年共水爭流。","客思偏来夜，蟬声覺送秋。","明朝逢旧侶，唯擬上歌楼。"]', '诗', 'shi', '', NULL, '與碧溪上人別 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab057de0-336c-480e-9e2d-6c46808b2755', '贈殷山人', '贈殷山人', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["有客抱琴宿，值予多怨懷。","啼烏弦易斷，嘯鶴調難諧。","曲罷月移幌，韻清風滿齋。","誰能將此妙，一爲奏金堦。"]', '["有客抱琴宿，值予多怨懷。","啼烏弦易斷，嘯鹤調难諧。","曲罷月移幌，韻清风满斋。","誰能將此妙，一爲奏金堦。"]', '诗', 'shi', '', NULL, '贈殷山人 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a215e20-5cce-4a5e-aa7a-634730d432bc', '詠壁魚', '詠壁鱼', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["鱗細粉光鮮，開書亂眼前。","透窗疑漏網，落硯似流泉。","潛穴河圖內，吞鉤乙字邊。","莫言鬐鬣小，食盡白蘋篇。"]', '["鱗細粉光鲜，开书亂眼前。","透窗疑漏網，落硯似流泉。","潛穴河圖內，吞鉤乙字邊。","莫言鬐鬣小，食尽白蘋篇。"]', '诗', 'shi', '', NULL, '詠壁魚 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9c5a2a2-6e6c-44fe-bb5c-32c616b21df1', '聽話叢臺', '听話叢台', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["有客新從趙地回，自言曾上古叢臺。","雲遮襄國天邊去，樹繞漳河地裏來。","弦管變成山鳥哢，綺羅留作野花開。","金輿玉輦無行跡，風雨惟知長綠苔。"]', '["有客新從趙地回，自言曾上古叢台。","云遮襄国天邊去，樹繞漳河地裏来。","弦管变成山鸟哢，綺羅留作野花开。","金輿玉輦無行跡，风雨惟知长綠苔。"]', '诗', 'shi', '', NULL, '聽話叢臺 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8de1ab43-e5cf-456f-852a-4f33e63c9a21', '失鶴', '失鹤', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["秋風吹却九臯禽，一片閑雲萬里心。","碧落有情應悵望，青天無路可追尋。","來時白雪翎猶短，去日丹砂頂漸深。","華表柱頭留語後，更無消息到如今。"]', '["秋风吹却九臯禽，一片闲云万里心。","碧落有情應悵望，青天無路可追尋。","来时白雪翎猶短，去日丹砂頂漸深。","华表柱头留語後，更無消息到如今。"]', '诗', 'shi', '', NULL, '失鶴 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e2cec01-d9df-4f66-a946-cdd1abb6607a', '贈寫御容李長史', '贈寫御容李长史', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["玉座塵消硯水清，龍髯不動綵毫輕。","初分隆準山河秀，乍點重瞳日月明。","宮女捲簾皆暗認，侍臣開殿盡遙驚。","三朝供奉無人敵，始覺僧繇浪得名。"]', '["玉座塵消硯水清，龙髯不动綵毫轻。","初分隆準山河秀，乍点重瞳日月明。","宮女捲簾皆暗認，侍臣开殿尽遙驚。","三朝供奉無人敵，始覺僧繇浪得名。"]', '诗', 'shi', '', NULL, '贈寫御容李長史 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3f436df-bca0-4f92-9c6a-ea5f8f158e3b', '贈潼關不下山僧', '贈潼关不下山僧', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["與君同在苦空間，君得空門我愛閑。","禁足已教修鴈塔，終身不擬下雞山。","窗中遙指三千界，枕上斜看百二關。","香茗一甌從此別，轉蓬流水幾時還。"]', '["與君同在苦空间，君得空门我愛闲。","禁足已教修鴈塔，終身不擬下雞山。","窗中遙指三千界，枕上斜看百二关。","香茗一甌從此別，轉蓬流水幾时還。"]', '诗', 'shi', '', NULL, '贈潼關不下山僧 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e956efde-6ec2-4761-aef6-fc04fcb1081d', '過舊遊見雙鶴愴然有懷', '過旧游见雙鹤愴然有懷', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["謝公何歲掩松楸，雙鶴依然傍玉樓。","朱頂巑岏荒草上，雪毛零落小池頭。","蓬瀛路斷君何在，雲水情深我尚留。","他日若來華表上，更添多少令威愁。"]', '["謝公何歲掩松楸，雙鹤依然傍玉楼。","朱頂巑岏荒草上，雪毛零落小池头。","蓬瀛路斷君何在，云水情深我尚留。","他日若来华表上，更添多少令威愁。"]', '诗', 'shi', '', NULL, '過舊遊見雙鶴愴然有懷 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('994dadf1-6e44-4c8c-be17-0842dece1c77', '贈友人', '贈友人', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["鳳城煙靄思偏多，曾向劉郎住處過。","銀燭焰前貪勸酒，玉簫聲裏已聞歌。","佳人惜別看嘶馬，公子含情向翠蛾。","今日重來門巷改，出牆桐樹綠婆娑。"]', '["鳳城煙靄思偏多，曾向劉郎住处過。","銀燭焰前貪勸酒，玉簫声裏已闻歌。","佳人惜別看嘶马，公子含情向翠蛾。","今日重来门巷改，出牆桐樹綠婆娑。"]', '诗', 'shi', '', NULL, '贈友人 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb853ae0-19b8-4653-94e9-a5a7f5d3777c', '贈南嶽僧', '贈南嶽僧', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["曾住衡陽嶽寺邊，門開江水與雲連。","數州城郭藏寒樹，一片風帆著遠天。","猨嘯不離行道處，客來皆到臥牀前。","今朝惆悵紅塵裏，惟憶閑陪盡日眠。"]', '["曾住衡陽嶽寺邊，门开江水與云連。","數州城郭藏寒樹，一片风帆著远天。","猨嘯不離行道处，客来皆到臥牀前。","今朝惆悵紅塵裏，惟憶闲陪尽日眠。"]', '诗', 'shi', '', NULL, '贈南嶽僧 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ddbf022-4355-4f60-bade-2947377653f1', '贈弘文杜校書', '贈弘文杜校书', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["高倚霞梯萬丈餘，共看移步入宸居。","曉隨鵷鷺排金鎖，靜對鉛黃校玉書。","漠漠禁煙籠遠樹，泠泠宮漏響前除。","還聞漢帝親詞賦，好爲從容奏子虛。"]', '["高倚霞梯万丈餘，共看移步入宸居。","晓隨鵷鷺排金鎖，静对鉛黄校玉书。","漠漠禁煙籠远樹，泠泠宮漏响前除。","還闻漢帝親词賦，好爲從容奏子虛。"]', '诗', 'shi', '', NULL, '贈弘文杜校書 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fd24ce0-d0b8-4214-bbf7-e9c5c0b24601', '聽王氏話歸州昭君廟', '听王氏話归州昭君廟', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["獻之閑坐說歸州，曾到昭君廟裏遊。","自古行人多怨恨，至今鄉土盡風流。","泉如珠淚侵階滴，花似紅妝滿岸愁。","河畔猶殘翠眉樣，有時新月傍簾鉤。"]', '["獻之闲坐说归州，曾到昭君廟裏游。","自古行人多怨恨，至今乡土尽风流。","泉如珠泪侵階滴，花似紅妝满岸愁。","河畔猶殘翠眉樣，有时新月傍簾鉤。"]', '诗', 'shi', '', NULL, '聽王氏話歸州昭君廟 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('250b668c-c0c3-4be6-be3b-bf94f7b20b7a', '過馬嵬山', '過马嵬山', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["金甲雲旗盡日迴，倉皇羅袖滿塵埃。","濃香猶自飄鑾輅，恨魄無因離馬嵬。","南內宮人悲帳殿，東溟方士問蓬萊。","唯餘坡上彎環月，時送殘蛾入帝臺。"]', '["金甲云旗尽日迴，倉皇羅袖满塵埃。","濃香猶自飄鑾輅，恨魄無因離马嵬。","南內宮人悲帳殿，东溟方士问蓬萊。","唯餘坡上彎环月，时送殘蛾入帝台。"]', '诗', 'shi', '', NULL, '過馬嵬山 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9f767bb-d3e5-4ab7-8080-680f2dcfcb64', '吳越懷古', '吳越懷古', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["吳越千年奈怨何，兩宮清吹作樵歌。","姑蘇一敗雲無色，范蠡長遊水自波。","霞拂故城疑轉斾，月依荒樹想嚬蛾。","行人欲問西施館，江鳥寒飛碧草多。"]', '["吳越千年奈怨何，兩宮清吹作樵歌。","姑蘇一敗云無色，范蠡长游水自波。","霞拂故城疑轉斾，月依荒樹想嚬蛾。","行人欲问西施館，江鸟寒飞碧草多。"]', '诗', 'shi', '', NULL, '吳越懷古 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d56cec1d-da48-43e6-9442-6bdbdf696077', '長安即事寄友人', '长安即事寄友人', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["綺陌千年思斷蓬，今來還宿鳳城東。","瑤臺鐘鼓長依舊，巫峽煙花自不同。","千結故心爲怨網，萬條新景作愁籠。","何時更伴劉郎去，却見夭桃滿樹紅。"]', '["綺陌千年思斷蓬，今来還宿鳳城东。","瑤台鐘鼓长依旧，巫峽煙花自不同。","千結故心爲怨網，万條新景作愁籠。","何时更伴劉郎去，却见夭桃满樹紅。"]', '诗', 'shi', '', NULL, '長安即事寄友人 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('842e4ae4-920c-49a6-b89e-bc77b7d29c9b', '聞明上人逝寄友人', '闻明上人逝寄友人', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["蕭寺曾過最上方，碧桐濃葉覆西廊。","遊人縹緲紅衣亂，座客從容白日長。","別後旋成莊叟夢，書來忽報惠休亡。","他時若更相隨去，祗是含酸對影堂。"]', '["蕭寺曾過最上方，碧桐濃葉覆西廊。","游人縹緲紅衣亂，座客從容白日长。","別後旋成莊叟梦，书来忽報惠休亡。","他时若更相隨去，祗是含酸对影堂。"]', '诗', 'shi', '', NULL, '聞明上人逝寄友人 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d236a8fc-2a32-4025-bbd3-076adddd7754', '贈咸陽李少府', '贈咸陽李少府', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["美貌雄才已少齊，寶書仙簡兩看題。","金刀片片裁新錦，玉步重重上舊梯。","鵬到碧天排霧去，鳳遊瓊樹揀枝棲。","蓬瀛宴罷試迴首，一望塵中路正迷。"]', '["美貌雄才已少齊，寶书仙簡兩看題。","金刀片片裁新錦，玉步重重上旧梯。","鵬到碧天排霧去，鳳游瓊樹揀枝棲。","蓬瀛宴罷試迴首，一望塵中路正迷。"]', '诗', 'shi', '', NULL, '贈咸陽李少府 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb0d112a-4d21-451d-898c-5feecb52d6bf', '隣人自金仙觀移竹', '隣人自金仙观移竹', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["移居新竹已堪看，斸破莓苔得幾竿。","圓節不教傷粉籜，低枝猶擬拂霜壇。","牆頭枝動如煙綠，枕上風來送夜寒。","第一莫教漁父見，且從蕭颯滿朱欄。"]', '["移居新竹已堪看，斸破莓苔得幾竿。","圓節不教傷粉籜，低枝猶擬拂霜壇。","牆头枝动如煙綠，枕上风来送夜寒。","第一莫教漁父见，且從蕭颯满朱欄。"]', '诗', 'shi', '', NULL, '隣人自金仙觀移竹 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b6c88b1-eeb4-4913-a98d-d46985a99bc9', '慈恩寺避暑', '慈恩寺避暑', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["香荷疑散麝，風鐸似調琴。","不覺清涼晚，歸人滿柳陰。"]', '["香荷疑散麝，风鐸似調琴。","不覺清涼晚，归人满柳陰。"]', '诗', 'shi', '', NULL, '慈恩寺避暑 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea98ac3f-be2f-4b1c-8d3b-35a34c54dfdd', '讀田光傳', '读田光傳', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["秦滅燕丹怨正深，古來豪客盡沾襟。","荆卿不了真閑事，辜負田光一片心。"]', '["秦滅燕丹怨正深，古来豪客尽沾襟。","荆卿不了真闲事，辜負田光一片心。"]', '诗', 'shi', '', NULL, '讀田光傳 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98e3bfe7-c57b-4fc8-a321-46a43e42a1c7', '友人下第因以贈之', '友人下第因以贈之', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["劉毅雖然不擲盧，誰人不道解樗蒲。","黃金百萬終須得，只有挼莎更一呼。"]', '["劉毅雖然不擲盧，誰人不道解樗蒲。","黄金百万終須得，只有挼莎更一呼。"]', '诗', 'shi', '', NULL, '友人下第因以贈之 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27c6b7fc-73cd-44f1-8cea-6c735af3d387', '詠鴛鴦', '詠鴛鴦', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["鴛鴦離別傷，人意似鴛鴦。","試取鴛鴦看，多應斷寸腸。"]', '["鴛鴦離別傷，人意似鴛鴦。","試取鴛鴦看，多應斷寸腸。"]', '诗', 'shi', '', NULL, '詠鴛鴦 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f643d4e-9431-46e7-b47e-b9514f28ebfd', '贈箏妓伍卿', '贈箏妓伍卿', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["輕輕沒後更無箏，玉腕紅紗到伍卿。","座客滿筵都不語，一行哀鴈十三聲。"]', '["轻轻沒後更無箏，玉腕紅紗到伍卿。","座客满筵都不語，一行哀鴈十三声。"]', '诗', 'shi', '', NULL, '贈箏妓伍卿 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96666100-2922-45d3-9c4a-3bcc1b0fff7f', '黃陵廟詞', '黄陵廟词', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["黃陵廟前莎草春，黃陵女兒蒨裙新。","輕舟小楫唱歌去，水遠山長愁殺人。"]', '["黄陵廟前莎草春，黄陵女兒蒨裙新。","轻舟小楫唱歌去，水远山长愁殺人。"]', '诗', 'shi', '', NULL, '黃陵廟詞 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b11a45bf-1185-4535-bf0c-74b87e6a532c', '句', '句', 'e253c306-862d-45e9-b0be-f690cff97912', '唐', '["人事三杯酒，流年一局棋。","青山不厭三杯酒，長日惟消一局棋。"]', '["人事三杯酒，流年一局棋。","青山不厭三杯酒，长日惟消一局棋。"]', '诗', 'shi', '', NULL, '句 李遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('068a3721-4aa5-44d9-abfd-10e1d010ad6b', '感懷詩一首', '感懷诗一首', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["高文會隋季，提劒徇天意。","扶持萬代人，步驟三皇地。","聖云繼之神，神仍用文治。","德澤酌生靈，沈酣薰骨髓。","旄頭騎箕尾，風塵薊門起。","胡兵殺漢兵，屍滿咸陽市。","宣皇走豪傑，談笑開中否。","蟠聯兩河間，燼萌終不弭。","號爲精兵處，齊蔡燕趙魏。","合環千里疆，爭爲一家事。","逆子嫁虜孫，西隣聘東里。","急熱同手足，唱和如宮徵。","法制自作爲，禮文爭僭擬。","壓階螭鬬角，畫屋龍交尾。","署紙日替名，分財賞稱賜。","刳隍𣤮萬尋，繚垣疊千雉。","誓將付孱孫，血絕然方已。","九廟仗神靈，四海爲輸委。","如何七十年，汗赩含羞恥。","韓彭不再生，英衛皆爲鬼。","凶門爪牙輩，穰穰如兒戲。","累聖但日吁，閫外將誰寄。","屯田數十萬，隄防常慴惴。","急征赴軍須，厚賦資凶器。","因隳畫一法，且逐隨時利。","流品極蒙尨，網羅漸離弛。","夷狄日開張，黎元愈憔悴。","邈矣遠太平，蕭然盡煩費。","至於貞元末，風流恣綺靡。","艱極泰循來，元和聖天子。","元和聖天子，英明湯武上。","茅茨覆宮殿，封章綻帷帳。","伍旅拔雄兒，夢卜庸真相。","勃雲走轟霆，河南一平盪。","繼于長慶初，燕趙終舁襁。","攜妻負子來，北闕爭頓顙。","故老撫兒孫，爾生今有望。","茹鯁喉尚隘，負重力未壯。","坐幄無奇兵，吞舟漏疎網。","骨添薊垣沙，血漲滹沱浪。","秖云徒有征，安能問無狀。","一日五諸侯，奔亡如鳥往。","取之難梯天，失之易反掌。","蒼然太行路，翦翦還榛莽。","關西賤男子，誓肉虜杯羹。","請數繫虜事，誰其爲我聽。","蕩蕩乾坤大，曈曈日月明。","叱起文武業，可以豁洪溟。","安得封域內，長有扈苗征。","七十里百里，彼亦何嘗爭。","往往念所至，得醉愁蘇醒。","韜舌辱壯心，叫閽無助聲。","聊書感懷韻，焚之遺賈生。"]', '["高文會隋季，提劒徇天意。","扶持万代人，步驟三皇地。","聖云繼之神，神仍用文治。","德澤酌生靈，沈酣薰骨髓。","旄头騎箕尾，风塵薊门起。","胡兵殺漢兵，屍满咸陽市。","宣皇走豪傑，談笑开中否。","蟠聯兩河间，燼萌終不弭。","號爲精兵处，齊蔡燕趙魏。","合环千里疆，爭爲一家事。","逆子嫁虜孫，西隣聘东里。","急熱同手足，唱和如宮徵。","法制自作爲，禮文爭僭擬。","壓階螭鬬角，畫屋龙交尾。","署紙日替名，分財賞稱賜。","刳隍𣤮万尋，繚垣叠千雉。","誓將付孱孫，血絕然方已。","九廟仗神靈，四海爲輸委。","如何七十年，汗赩含羞恥。","韓彭不再生，英衛皆爲鬼。","凶门爪牙輩，穰穰如兒戲。","累聖但日吁，閫外將誰寄。","屯田數十万，隄防常慴惴。","急征赴軍須，厚賦資凶器。","因隳畫一法，且逐隨时利。","流品極蒙尨，網羅漸離弛。","夷狄日开張，黎元愈憔悴。","邈矣远太平，蕭然尽煩費。","至於貞元末，风流恣綺靡。","艱極泰循来，元和聖天子。","元和聖天子，英明湯武上。","茅茨覆宮殿，封章綻帷帳。","伍旅拔雄兒，梦卜庸真相。","勃云走轟霆，河南一平盪。","繼于长慶初，燕趙終舁襁。","携妻負子来，北闕爭頓顙。","故老撫兒孫，爾生今有望。","茹鯁喉尚隘，負重力未壯。","坐幄無奇兵，吞舟漏疎網。","骨添薊垣沙，血漲滹沱浪。","秖云徒有征，安能问無狀。","一日五諸侯，奔亡如鸟往。","取之难梯天，失之易反掌。","蒼然太行路，翦翦還榛莽。","关西賤男子，誓肉虜杯羹。","請數繫虜事，誰其爲我听。","蕩蕩乾坤大，曈曈日月明。","叱起文武業，可以豁洪溟。","安得封域內，长有扈苗征。","七十里百里，彼亦何嘗爭。","往往念所至，得醉愁蘇醒。","韜舌辱壯心，叫閽無助声。","聊书感懷韻，焚之遺賈生。"]', '诗', 'shi', '', NULL, '感懷詩一首 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eba238d6-5856-4554-9945-fd22d9a421f8', '杜秋娘詩', '杜秋娘诗', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["京江水清滑，生女白如脂。","其間杜秋者，不勞朱粉施。","老濞即山鑄，後庭千雙眉。","秋持玉斝醉，與唱金縷衣。","濞既白首叛，秋亦紅淚滋。","吳江落日渡，灞岸綠楊垂。","聯裾見天子，盼眄獨依依。","椒壁懸錦幕，鏡奩蟠蛟螭。","低鬟認新寵，窈裊復融怡。","月上白璧門，桂影涼參差。","金階露新重，閑捻紫簫吹。","莓苔夾城路，南苑鴈初飛。","紅粉羽林仗，獨賜辟邪旗。","歸來煮豹胎，饜飫不能飴。","咸池昇日慶，銅雀分香悲。","雷音後車遠，事往落花時。","燕禖得皇子，壯髪綠緌緌。","畫堂授傅姆，天人親捧持。","虎睛珠絡褓，金盤犀鎮帷。","長楊射熊羆，武帳弄啞咿。","漸拋竹馬劇，稍出舞雞奇。","嶄嶄整冠珮，侍宴坐瑤池。","眉宇儼圖畫，神秀射朝輝。","一尺桐偶人，江充知自欺。","王幽茅土削，秋放故鄉歸。","觚稜拂斗極，回首尚遲遲。","四朝三十載，似夢復疑非。","潼關識舊吏，吏髪已如絲。","却喚吳江渡，舟人那得知。","歸來四隣改，茂苑草菲菲。","清血灑不盡，仰天知問誰。","寒衣一匹素，夜借隣人機。","我昨金陵過，聞之爲歔欷。","自古皆一貫，變化安能推。","夏姬滅兩國，逃作巫臣姬。","西子下姑蘇，一舸逐鴟夷。","織室魏豹俘，作漢太平基。","誤置代籍中，兩朝尊母儀。","光武紹高祖，本係生唐兒。","珊瑚破高齊，作婢舂黃糜。","蕭后去揚州，突厥爲閼氏。","女子固不定，士林亦難期。","射鉤後呼父，釣翁王者師。","無國要孟子，有人毀仲尼。","秦因逐客令，柄歸丞相斯。","安知魏齊首，見斷簀中屍。","給喪蹶張輩，廊廟冠峩危。","珥貂七葉貴，何妨戎虜支。","蘇武却生返，鄧通終死飢。","主張既難測，翻覆亦其宜。","地盡有何物，天外復何之。","指何爲而捉，足何爲而馳。","耳何爲而聽，目何爲而窺。","己身不自曉，此外何思惟。","因傾一樽酒，題作杜秋詩。","愁來獨長詠，聊可以自怡。"]', '["京江水清滑，生女白如脂。","其间杜秋者，不勞朱粉施。","老濞即山鑄，後庭千雙眉。","秋持玉斝醉，與唱金縷衣。","濞既白首叛，秋亦紅泪滋。","吳江落日渡，灞岸綠楊垂。","聯裾见天子，盼眄独依依。","椒壁懸錦幕，镜奩蟠蛟螭。","低鬟認新寵，窈裊复融怡。","月上白璧门，桂影涼參差。","金階露新重，闲捻紫簫吹。","莓苔夾城路，南苑鴈初飞。","紅粉羽林仗，独賜辟邪旗。","归来煮豹胎，饜飫不能飴。","咸池昇日慶，銅雀分香悲。","雷音後车远，事往落花时。","燕禖得皇子，壯髪綠緌緌。","畫堂授傅姆，天人親捧持。","虎睛珠絡褓，金盤犀鎮帷。","长楊射熊羆，武帳弄啞咿。","漸拋竹马劇，稍出舞雞奇。","嶄嶄整冠珮，侍宴坐瑤池。","眉宇儼圖畫，神秀射朝輝。","一尺桐偶人，江充知自欺。","王幽茅土削，秋放故乡归。","觚稜拂斗極，回首尚遲遲。","四朝三十載，似梦复疑非。","潼关識旧吏，吏髪已如絲。","却喚吳江渡，舟人那得知。","归来四隣改，茂苑草菲菲。","清血灑不尽，仰天知问誰。","寒衣一匹素，夜借隣人機。","我昨金陵過，闻之爲歔欷。","自古皆一貫，变化安能推。","夏姬滅兩国，逃作巫臣姬。","西子下姑蘇，一舸逐鴟夷。","织室魏豹俘，作漢太平基。","誤置代籍中，兩朝尊母儀。","光武紹高祖，本係生唐兒。","珊瑚破高齊，作婢舂黄糜。","蕭后去揚州，突厥爲閼氏。","女子固不定，士林亦难期。","射鉤後呼父，釣翁王者師。","無国要孟子，有人毀仲尼。","秦因逐客令，柄归丞相斯。","安知魏齊首，见斷簀中屍。","給喪蹶張輩，廊廟冠峩危。","珥貂七葉貴，何妨戎虜支。","蘇武却生返，鄧通終死飢。","主張既难測，翻覆亦其宜。","地尽有何物，天外复何之。","指何爲而捉，足何爲而驰。","耳何爲而听，目何爲而窺。","己身不自晓，此外何思惟。","因傾一樽酒，題作杜秋诗。","愁来独长詠，聊可以自怡。"]', '诗', 'shi', '', NULL, '杜秋娘詩 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bf6ce08-f7a1-4c94-b690-0bf055d27c98', '郡齋獨酌', '郡斋独酌', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["前年鬢生雪，今年鬚帶霜。","時節序鱗次，古今同鴈行。","甘英窮西海，四萬到洛陽。","東南我所見，北可計幽荒。","中畫一萬國，角角棊布方。","地頑壓不穴，天逈老不僵。","屈指百萬世，過如霹靂忙。","人生落其內，何者爲彭殤。","促束自繫縛，儒衣寬且長。","旗亭雪中過，敢問當壚娘。","我愛李侍中，標標七尺強。","白羽八扎弓，䏶壓綠檀槍。","風前略橫陣，紫髯分兩傍。","淮西萬虎士，怒目不敢當。","功成賜宴麟德殿，猨超鶻掠廣毬場。","三千宮女側頭看，相排踏碎雙明璫。","旌竿幖幖旗㸌㸌，意氣橫鞭歸故鄉。","我愛朱處士，三吳當中央。","罷亞百頃稻，西風吹半黃。","尚可活鄉里，豈唯滿囷倉。","後嶺翠撲撲，前溪碧泱泱。","霧曉起鳧鴈，日晚下牛羊。","叔舅欲飲我，社甕爾來嘗。","伯姊子欲歸，彼亦有壺漿。","西阡下柳塢，東陌繞荷塘。","姻親骨肉舍，烟火遙相望。","太守政如水，長官貪似狼。","征輸一云畢，任爾自存亡。","我昔造其室，羽儀鸞鶴翔。","交橫碧流上，竹映琴書牀。","出語無近俗，堯舜禹武湯。","問今天子少，誰人爲棟梁。","我曰天子聖，晉公提紀綱。","聯兵數十萬，附海正誅滄。","謂言大義小不義，取易卷席如探囊。","犀甲吳兵鬬弓弩，虵矛燕戟馳鋒鋩。","豈知三載幾百戰，鉤車不得望其牆。","荅云此山外，有事同胡羌。","誰將國伐叛，話與釣魚郎。","溪南重迴首，一徑出修篁。","爾來十三歲，斯人未曾忘。","往往自撫己，淚下神蒼茫。","御史詔分洛，舉趾何猖狂。","闕下諫官業，拜疏無文章。","尋僧解憂夢，乞酒緩愁腸。","豈爲妻子計，未去山林藏。","平生五色線，願補舜衣裳。","弦歌教燕趙，蘭芷浴河湟。","腥膻一掃灑，兇狠皆披攘。","生人但眠食，壽域富農桑。","孤吟志在此，自亦笑荒唐。","江郡雨初霽，刀好截秋光。","池邊成獨酌，擁鼻菊枝香。","醺酣更唱太平曲，仁聖天子壽無疆。"]', '["前年鬢生雪，今年鬚带霜。","时節序鱗次，古今同鴈行。","甘英窮西海，四万到洛陽。","东南我所见，北可計幽荒。","中畫一万国，角角棊布方。","地頑壓不穴，天逈老不僵。","屈指百万世，過如霹靂忙。","人生落其內，何者爲彭殤。","促束自繫縛，儒衣寬且长。","旗亭雪中過，敢问當壚娘。","我愛李侍中，標標七尺強。","白羽八扎弓，䏶壓綠檀槍。","风前略橫陣，紫髯分兩傍。","淮西万虎士，怒目不敢當。","功成賜宴麟德殿，猨超鶻掠廣毬場。","三千宮女側头看，相排踏碎雙明璫。","旌竿幖幖旗㸌㸌，意氣橫鞭归故乡。","我愛朱处士，三吳當中央。","罷亞百頃稻，西风吹半黄。","尚可活乡里，豈唯满囷倉。","後嶺翠撲撲，前溪碧泱泱。","霧晓起鳧鴈，日晚下牛羊。","叔舅欲饮我，社甕爾来嘗。","伯姊子欲归，彼亦有壺漿。","西阡下柳塢，东陌繞荷塘。","姻親骨肉舍，烟火遙相望。","太守政如水，长官貪似狼。","征輸一云畢，任爾自存亡。","我昔造其室，羽儀鸾鹤翔。","交橫碧流上，竹映琴书牀。","出語無近俗，堯舜禹武湯。","问今天子少，誰人爲棟梁。","我曰天子聖，晉公提紀綱。","聯兵數十万，附海正誅滄。","謂言大義小不義，取易卷席如探囊。","犀甲吳兵鬬弓弩，虵矛燕戟驰鋒鋩。","豈知三載幾百戰，鉤车不得望其牆。","荅云此山外，有事同胡羌。","誰將国伐叛，話與釣鱼郎。","溪南重迴首，一徑出修篁。","爾来十三歲，斯人未曾忘。","往往自撫己，泪下神蒼茫。","御史詔分洛，舉趾何猖狂。","闕下諫官業，拜疏無文章。","尋僧解憂梦，乞酒緩愁腸。","豈爲妻子計，未去山林藏。","平生五色線，願補舜衣裳。","弦歌教燕趙，蘭芷浴河湟。","腥膻一掃灑，兇狠皆披攘。","生人但眠食，壽域富農桑。","孤吟志在此，自亦笑荒唐。","江郡雨初霽，刀好截秋光。","池邊成独酌，擁鼻菊枝香。","醺酣更唱太平曲，仁聖天子壽無疆。"]', '诗', 'shi', '', NULL, '郡齋獨酌 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19b95441-a769-42ee-89b6-dc618f37b993', '張好好詩', '張好好诗', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["君爲豫章姝，十三纔有餘。","翠茁鳳生尾，丹葉蓮含跗。","高閣倚天半，章江聯碧虛。","此地試君唱，特使華筵鋪。","主人顧四座，始訝來踟蹰。","吳娃起引贊，低徊映長裾。","雙鬟可高下，纔過青羅襦。","盼盼乍垂袖，一聲雛鳳呼。","繁弦迸關紐，塞管裂圓蘆。","衆音不能逐，褭褭穿雲衢。","主人再三歎，謂言天下殊。","贈之天馬錦，副以水犀梳。","龍沙看秋浪，明月遊朱湖。","自此每相見，三日已爲疎。","玉質隨月滿，豔態逐春舒。","絳脣漸輕巧，雲步轉虛徐。","旌斾忽東下，笙歌隨舳艫。","霜凋謝樓樹，沙暖句溪蒲。","身外任塵土，罇前極歡娛。","飄然集仙客，諷賦欺相如。","聘之碧瑤珮，載以紫雲車。","洞閉水聲遠，月高蟾影孤。","爾來未幾歲，散盡高陽徒。","洛城重相見，婥婥爲當壚。","怪我苦何事，少年垂白鬚。","朋遊今在否，落拓更能無。","門館慟哭後，水雲秋景初。","斜日挂衰柳，涼風生座隅。","灑盡滿襟淚，短歌聊一書。"]', '["君爲豫章姝，十三纔有餘。","翠茁鳳生尾，丹葉蓮含跗。","高閣倚天半，章江聯碧虛。","此地試君唱，特使华筵鋪。","主人顧四座，始訝来踟蹰。","吳娃起引贊，低徊映长裾。","雙鬟可高下，纔過青羅襦。","盼盼乍垂袖，一声雛鳳呼。","繁弦迸关紐，塞管裂圓蘆。","衆音不能逐，褭褭穿云衢。","主人再三歎，謂言天下殊。","贈之天马錦，副以水犀梳。","龙沙看秋浪，明月游朱湖。","自此每相见，三日已爲疎。","玉質隨月满，豔態逐春舒。","絳脣漸轻巧，云步轉虛徐。","旌斾忽东下，笙歌隨舳艫。","霜凋謝楼樹，沙暖句溪蒲。","身外任塵土，罇前極歡娛。","飄然集仙客，諷賦欺相如。","聘之碧瑤珮，載以紫云车。","洞閉水声远，月高蟾影孤。","爾来未幾歲，散尽高陽徒。","洛城重相见，婥婥爲當壚。","怪我苦何事，少年垂白鬚。","朋游今在否，落拓更能無。","门館慟哭後，水云秋景初。","斜日挂衰柳，涼风生座隅。","灑尽满襟泪，短歌聊一书。"]', '诗', 'shi', '', NULL, '張好好詩 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d151956a-dfeb-4637-a84c-740f8650dddc', '冬至日寄小姪阿宜詩', '冬至日寄小姪阿宜诗', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["小姪名阿宜，未得三尺長。","頭圓筋骨緊，兩眼明且光。","去年學官人，竹馬遶四廊。","指揮羣兒輩，意氣何堅剛。","今年始讀書，下口三五行。","隨兄旦夕去，歛手整衣裳。","去歲冬至日，拜我立我旁。","祝爾願爾貴，仍且壽命長。","今年我江外，今日生一陽。","憶爾不可見，祝爾傾一觴。","陽德比君子，初生甚微茫。","排陰出九地，萬物隨開張。","一似小兒學，日就復月將。","勤勤不自已，二十能文章。","仕宦至公相，致君作堯湯。","我家公相家，劒佩嘗丁當。","舊第開朱門，長安城中央。","第中無一物，萬卷書滿堂。","家集二百編，上下馳皇王。","多是撫州寫，今來五紀強。","尚可與爾讀，助爾爲賢良。","經書括根本，史書閱興亡。","高摘屈宋豔，濃薰班馬香。","李杜泛浩浩，韓柳摩蒼蒼。","近者四君子，與古爭強梁。","願爾一祝後，讀書日日忙。","一日讀十紙，一月讀一箱。","朝廷用文治，大開官職場。","願爾出門去，取官如驅羊。","吾兄苦好古，學問不可量。","晝居府中治，夜歸書滿牀。","後貴有金玉，必不爲汝藏。","崔昭生崔芸，李兼生窟郎。","堆錢一百屋，破散何披猖。","今雖未即死，餓凍幾欲僵。","參軍與縣尉，塵土驚劻勷。","一語不中治，笞箠身滿瘡。","官罷得絲髪，好買百樹桑。","稅錢未輸足，得米不敢嘗。","願爾聞我語，懽喜入心腸。","大明帝宮闕，杜曲我池塘。","我若自潦倒，看汝爭翶翔。","總語諸小道，此詩不可忘。"]', '["小姪名阿宜，未得三尺长。","头圓筋骨緊，兩眼明且光。","去年学官人，竹马遶四廊。","指揮羣兒輩，意氣何堅剛。","今年始读书，下口三五行。","隨兄旦夕去，歛手整衣裳。","去歲冬至日，拜我立我旁。","祝爾願爾貴，仍且壽命长。","今年我江外，今日生一陽。","憶爾不可见，祝爾傾一觴。","陽德比君子，初生甚微茫。","排陰出九地，万物隨开張。","一似小兒学，日就复月將。","勤勤不自已，二十能文章。","仕宦至公相，致君作堯湯。","我家公相家，劒佩嘗丁當。","旧第开朱门，长安城中央。","第中無一物，万卷书满堂。","家集二百編，上下驰皇王。","多是撫州寫，今来五紀強。","尚可與爾读，助爾爲賢良。","經书括根本，史书閱兴亡。","高摘屈宋豔，濃薰班马香。","李杜泛浩浩，韓柳摩蒼蒼。","近者四君子，與古爭強梁。","願爾一祝後，读书日日忙。","一日读十紙，一月读一箱。","朝廷用文治，大开官職場。","願爾出门去，取官如驱羊。","吾兄苦好古，学问不可量。","晝居府中治，夜归书满牀。","後貴有金玉，必不爲汝藏。","崔昭生崔芸，李兼生窟郎。","堆錢一百屋，破散何披猖。","今雖未即死，餓凍幾欲僵。","參軍與縣尉，塵土驚劻勷。","一語不中治，笞箠身满瘡。","官罷得絲髪，好買百樹桑。","稅錢未輸足，得米不敢嘗。","願爾闻我語，懽喜入心腸。","大明帝宮闕，杜曲我池塘。","我若自潦倒，看汝爭翶翔。","總語諸小道，此诗不可忘。"]', '诗', 'shi', '', NULL, '冬至日寄小姪阿宜詩 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d75971af-9e4f-4a60-b7ca-f66222d9e407', '李甘詩', '李甘诗', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["太和八九年，訓注極虓虎。","潛身九地底，轉上青天去。","四海鏡清澄，千官雲片縷。","公私各閑暇，追遊日相伍。","豈知禍亂根，枝葉潛滋莽。","九年夏四月，天誡若言語。","烈風駕地震，獰雷驅猛雨。","夜於正殿階，拔去千年樹。","吾君不省覺，二凶日威武。","操持北斗柄，開閉天門路。","森森明庭士，縮縮循牆鼠。","平生負奇節，一旦如奴虜。","指名爲錮黨，狀跡誰告訴。","喜無李杜誅，敢憚髡鉗苦。","時當秋夜月，日值曰庚午。","喧喧皆傳言，明晨相登注。","予時與和鼎，官班各持斧。","和鼎顧予言，我死知處所。","當庭裂詔書，退立須鼎俎。","君門曉日開，赭案橫霞布。","儼雅千官容，勃鬱吾累怒。","適屬命鄜將，昨之傳者誤。","明日詔書下，謫斥南荒去。","夜登青泥坂，墜車傷左股。","病妻尚在牀，稚子初離乳。","幽蘭思楚澤，恨水啼湘渚。","怳怳三閭魂，悠悠一千古。","其冬二兇敗，渙汗開湯罟。","賢者須喪亡，讒人尚堆堵。","予於後四年，諫官事明主。","常欲雪幽冤，於時一裨補。","拜章豈艱難，膽薄多憂懼。","如何干斗氣，竟作炎荒土。","題此涕滋筆，以代投湘賦。"]', '["太和八九年，訓注極虓虎。","潛身九地底，轉上青天去。","四海镜清澄，千官云片縷。","公私各闲暇，追游日相伍。","豈知禍亂根，枝葉潛滋莽。","九年夏四月，天誡若言語。","烈风駕地震，獰雷驱猛雨。","夜於正殿階，拔去千年樹。","吾君不省覺，二凶日威武。","操持北斗柄，开閉天门路。","森森明庭士，縮縮循牆鼠。","平生負奇節，一旦如奴虜。","指名爲錮黨，狀跡誰告訴。","喜無李杜誅，敢憚髡鉗苦。","时當秋夜月，日值曰庚午。","喧喧皆傳言，明晨相登注。","予时與和鼎，官班各持斧。","和鼎顧予言，我死知处所。","當庭裂詔书，退立須鼎俎。","君门晓日开，赭案橫霞布。","儼雅千官容，勃鬱吾累怒。","適屬命鄜將，昨之傳者誤。","明日詔书下，謫斥南荒去。","夜登青泥坂，墜车傷左股。","病妻尚在牀，稚子初離乳。","幽蘭思楚澤，恨水啼湘渚。","怳怳三閭魂，悠悠一千古。","其冬二兇敗，渙汗开湯罟。","賢者須喪亡，讒人尚堆堵。","予於後四年，諫官事明主。","常欲雪幽冤，於时一裨補。","拜章豈艱难，膽薄多憂懼。","如何干斗氣，竟作炎荒土。","題此涕滋笔，以代投湘賦。"]', '诗', 'shi', '', NULL, '李甘詩 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1552a0b-36d0-43ca-bc22-9e8653ec7eb8', '洛中送冀處士東遊', '洛中送冀处士东游', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["處士有儒術，走可挾車輈。","壇宇寬帖帖，符彩高酋酋。","不愛事耕稼，不樂干王侯。","四十餘年中，超超爲浪遊。","元和五六歲，客於幽魏州。","幽魏多壯士，意氣相淹留。","劉濟願跪履，田興請建籌。","處士拱兩手，笑之但掉頭。","自此南走越，尋山入羅浮。","願學不死藥，粗知其來由。","却於童頂上，蕭蕭玄髪抽。","我作八品吏，洛中如繫囚。","忽遭冀處士，豁若登高樓。","拂榻與之坐，十日語不休。","論今星璨璨，考古寒颼颼。","治亂掘根本，蔓延相牽鉤。","武事何駿壯，文理何優柔。","顏回捧俎豆，項羽橫戈矛。","祥雲遶毛髪，高浪開咽喉。","但可感神鬼，安能爲獻酬。","好入天子夢，刻像來爾求。","胡爲去吳會，欲浮滄海舟。","贈以蜀馬箠，副之胡罽裘。","餞酒載三斗，東郊黃葉稠。","我感有淚下，君唱高歌酬。","嵩山高萬尺，洛水流千秋。","往事不可問，天地空悠悠。","四百年炎漢，三十代宗周。","二三里遺堵，八九所高丘。","人生一世內，何必多悲愁。","謌闋解攜去，信非吾輩流。"]', '["处士有儒術，走可挾车輈。","壇宇寬帖帖，符彩高酋酋。","不愛事耕稼，不乐干王侯。","四十餘年中，超超爲浪游。","元和五六歲，客於幽魏州。","幽魏多壯士，意氣相淹留。","劉濟願跪履，田兴請建籌。","处士拱兩手，笑之但掉头。","自此南走越，尋山入羅浮。","願学不死藥，粗知其来由。","却於童頂上，蕭蕭玄髪抽。","我作八品吏，洛中如繫囚。","忽遭冀处士，豁若登高楼。","拂榻與之坐，十日語不休。","論今星璨璨，考古寒颼颼。","治亂掘根本，蔓延相牽鉤。","武事何駿壯，文理何優柔。","顏回捧俎豆，項羽橫戈矛。","祥云遶毛髪，高浪开咽喉。","但可感神鬼，安能爲獻酬。","好入天子梦，刻像来爾求。","胡爲去吳會，欲浮滄海舟。","贈以蜀马箠，副之胡罽裘。","餞酒載三斗，东郊黄葉稠。","我感有泪下，君唱高歌酬。","嵩山高万尺，洛水流千秋。","往事不可问，天地空悠悠。","四百年炎漢，三十代宗周。","二三里遺堵，八九所高丘。","人生一世內，何必多悲愁。","謌闋解携去，信非吾輩流。"]', '诗', 'shi', '', NULL, '洛中送冀處士東遊 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2187e5ea-af1d-4503-a3b5-29432a5c2316', '送沈處士赴蘇州李中丞招以詩贈行', '送沈处士赴蘇州李中丞招以诗贈行', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["山城樹葉紅，下有碧溪水。","溪橋向吳路，酒旗誇酒美。","下馬此送君，高歌爲君醉。","念君苞材能，百工在城壘。","空山三十年，鹿裘挂窓睡。","自言隴西公，飄然我知己。","舉酒屬吳門，今朝爲君起。","懸弓三百斤，囊書數萬紙。","戰賊即戰賊，爲吏即爲吏。","盡我所有無，惟公之指使。","予曰隴西公，滔滔大君子。","常思掄羣材，一爲國家治。","譬如匠見木，礙眼皆不棄。","大者麤十圍，小者細一指。","㨝橛與棟梁，施之皆有位。","忽然豎明堂，一揮立能致。","予亦何爲者，亦受公恩紀。","處士有常言，殘虜爲犬豕。","常恨兩手空，不得一馬箠。","今依隴西公，如虎傅兩翅。","公非刺史材，當坐巖廊地。","處士魁奇姿，必展平生志。","東吳饒風光，翠巘多名寺。","疎煙亹亹秋，獨酌平生思。","因書問故人，能忘批紙尾。","公或憶姓名，爲說都憔悴。"]', '["山城樹葉紅，下有碧溪水。","溪橋向吳路，酒旗誇酒美。","下马此送君，高歌爲君醉。","念君苞材能，百工在城壘。","空山三十年，鹿裘挂窓睡。","自言隴西公，飄然我知己。","舉酒屬吳门，今朝爲君起。","懸弓三百斤，囊书數万紙。","戰賊即戰賊，爲吏即爲吏。","尽我所有無，惟公之指使。","予曰隴西公，滔滔大君子。","常思掄羣材，一爲国家治。","譬如匠见木，礙眼皆不棄。","大者麤十圍，小者細一指。","㨝橛與棟梁，施之皆有位。","忽然豎明堂，一揮立能致。","予亦何爲者，亦受公恩紀。","处士有常言，殘虜爲犬豕。","常恨兩手空，不得一马箠。","今依隴西公，如虎傅兩翅。","公非刺史材，當坐巖廊地。","处士魁奇姿，必展平生志。","东吳饒风光，翠巘多名寺。","疎煙亹亹秋，独酌平生思。","因书问故人，能忘批紙尾。","公或憶姓名，爲说都憔悴。"]', '诗', 'shi', '', NULL, '送沈處士赴蘇州李中丞招以詩贈行 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d312c06e-0822-4f79-976e-a17d24284aec', '長安送友人遊湖南', '长安送友人游湖南', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["子性劇弘和，愚衷深褊狷。","相舍囂譊中，吾過何由鮮。","楚南饒風烟，湘岸苦縈宛。","山密夕陽多，人稀芳草遠。","青梅繁枝低，斑笋新梢短。","莫哭葬魚人，酒醒且眠飯。"]', '["子性劇弘和，愚衷深褊狷。","相舍囂譊中，吾過何由鲜。","楚南饒风烟，湘岸苦縈宛。","山密夕陽多，人稀芳草远。","青梅繁枝低，斑笋新梢短。","莫哭葬鱼人，酒醒且眠飯。"]', '诗', 'shi', '', NULL, '長安送友人遊湖南 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f98de59-a2b3-494f-a29f-d54bf52b2f19', '皇風', '皇风', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["仁聖天子神且武，內興文教外披攘。","以德化人漢文帝，側身修道周宣王。","迒蹊巢穴盡窒塞，禮樂刑政皆弛張。","何當提筆侍巡狩，前驅白斾弔河湟。"]', '["仁聖天子神且武，內兴文教外披攘。","以德化人漢文帝，側身修道周宣王。","迒蹊巢穴尽窒塞，禮乐刑政皆弛張。","何當提笔侍巡狩，前驱白斾弔河湟。"]', '诗', 'shi', '', NULL, '皇風 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c6e2c3e-933f-4b97-b448-e2b87508bca4', '雪中書懷', '雪中书懷', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["臘雪一尺厚，雲凍寒頑癡。","孤城大澤畔，人疎煙火微。","憤悱欲誰語，憂慍不能持。","天子號仁聖，任賢如事師。","凡稱曰治具，小大無不施。","明庭開廣敞，才雋受羈維。","如日月縆昇，若鸞鳳葳蕤。","人才自朽下，棄去亦其宜。","北虜壞亭障，聞屯千里師。","牽連久不解，他盜恐旁窺。","臣實有長策，彼可徐鞭笞。","如蒙一召議，食肉寢其皮。","斯乃廟堂事，爾微非爾知。","向來躐等語，長作陷身機。","行當臘欲破，酒齊不可遲。","且想春候暖，甕間傾一巵。"]', '["臘雪一尺厚，云凍寒頑癡。","孤城大澤畔，人疎煙火微。","憤悱欲誰語，憂慍不能持。","天子號仁聖，任賢如事師。","凡稱曰治具，小大無不施。","明庭开廣敞，才雋受羈維。","如日月縆昇，若鸾鳳葳蕤。","人才自朽下，棄去亦其宜。","北虜壞亭障，闻屯千里師。","牽連久不解，他盜恐旁窺。","臣實有长策，彼可徐鞭笞。","如蒙一召議，食肉寢其皮。","斯乃廟堂事，爾微非爾知。","向来躐等語，长作陷身機。","行當臘欲破，酒齊不可遲。","且想春候暖，甕间傾一巵。"]', '诗', 'shi', '', NULL, '雪中書懷 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ea22471-a39a-45de-a8f2-91b4f18058a0', '雨中作', '雨中作', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["賤子本幽慵，多爲雋賢侮。","得州荒僻中，更值連江雨。","一褐擁秋寒，小窗侵竹塢。","濁醪氣色嚴，皤腹瓶甖古。","酣酣天地寬，怳怳嵇劉伍。","但爲適性情，豈是藏鱗羽。","一世一萬朝，朝朝醉中去。"]', '["賤子本幽慵，多爲雋賢侮。","得州荒僻中，更值連江雨。","一褐擁秋寒，小窗侵竹塢。","濁醪氣色嚴，皤腹瓶甖古。","酣酣天地寬，怳怳嵇劉伍。","但爲適性情，豈是藏鱗羽。","一世一万朝，朝朝醉中去。"]', '诗', 'shi', '', NULL, '雨中作 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06c0883b-c3f2-4ad5-bb48-b95e9565ecf1', '偶遊石盎僧舍', '偶游石盎僧舍', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["敬岑草浮光，句沚水解脉。","益鬱乍怡融，凝嚴忽頹坼。","梅纇暖眠酣，風緒和無力。","鳧浴漲汪汪，雛嬌村冪冪。","落日美樓臺，輕烟飾阡陌。","瀲綠古津遠，積潤苔基釋。","孰謂漢陵人，來作江汀客。","載筆念無能，捧籌慙所畫。","任轡偶追閑，逢幽果遭適。","僧語淡如雲，塵事繁堪織。","今古幾輩人，而我何能息。"]', '["敬岑草浮光，句沚水解脉。","益鬱乍怡融，凝嚴忽頹坼。","梅纇暖眠酣，风緒和無力。","鳧浴漲汪汪，雛嬌村冪冪。","落日美楼台，轻烟飾阡陌。","瀲綠古津远，積潤苔基釋。","孰謂漢陵人，来作江汀客。","載笔念無能，捧籌慙所畫。","任轡偶追闲，逢幽果遭適。","僧語淡如云，塵事繁堪织。","今古幾輩人，而我何能息。"]', '诗', 'shi', '', NULL, '偶遊石盎僧舍 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ac6f62b-3cf7-4c7d-8e00-28964220dcce', '赴京初入汴口曉景即事先寄兵部李郎中', '赴京初入汴口晓景即事先寄兵部李郎中', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["清淮控隋漕，北走長安道。","檣形櫛櫛斜，浪態迤迤好。","初旭紅可染，明河澹如掃。","澤闊鳥來遲，村飢人語早。","露蔓蟲絲多，風蒲燕雛老。","秋思高蕭蕭，客態長褭褭。","因懷京洛間，宦遊何戚草。","什伍持津梁，澒湧爭追討。","翾便詎可尋，幾秘安能考。","小人乏馨香，上下將何禱。","唯有君子心，顯豁知幽抱。"]', '["清淮控隋漕，北走长安道。","檣形櫛櫛斜，浪態迤迤好。","初旭紅可染，明河澹如掃。","澤闊鸟来遲，村飢人語早。","露蔓蟲絲多，风蒲燕雛老。","秋思高蕭蕭，客態长褭褭。","因懷京洛间，宦游何戚草。","什伍持津梁，澒湧爭追討。","翾便詎可尋，幾秘安能考。","小人乏馨香，上下將何禱。","唯有君子心，显豁知幽抱。"]', '诗', 'shi', '', NULL, '赴京初入汴口曉景即事先寄兵部李郎中 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e167af1-7d67-4417-aa13-bff4bbe8f9f1', '獨酌', '独酌', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["長空碧杳杳，萬古一飛鳥。","生前酒伴閑，愁醉閑多少。","烟深隋家寺，殷葉暗相照。","獨佩一壺遊，秋毫泰山小。"]', '["长空碧杳杳，万古一飞鸟。","生前酒伴闲，愁醉闲多少。","烟深隋家寺，殷葉暗相照。","独佩一壺游，秋毫泰山小。"]', '诗', 'shi', '', NULL, '獨酌 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4621776-8acc-4c77-9d0e-26c2a8689b43', '惜春', '惜春', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["春半年已除，其餘強爲有。","即此醉殘花，便同嘗臘酒。","悵望送春杯，殷勤掃花箒。","誰爲駐東流，年年長在手。"]', '["春半年已除，其餘強爲有。","即此醉殘花，便同嘗臘酒。","悵望送春杯，殷勤掃花箒。","誰爲駐东流，年年长在手。"]', '诗', 'shi', '', NULL, '惜春 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae9b1b8f-777e-482a-9cf7-92ce97b1b2f0', '題安州浮雲寺樓寄湖州張郎中', '題安州浮云寺楼寄湖州張郎中', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["去夏疎雨餘，同倚朱闌語。","當時樓下水，今日到何處？","恨如春草多，事與孤鴻去。","楚岸柳何窮，別愁紛若絮。"]', '["去夏疎雨餘，同倚朱闌語。","當时楼下水，今日到何处？","恨如春草多，事與孤鴻去。","楚岸柳何窮，別愁紛若絮。"]', '诗', 'shi', '', NULL, '題安州浮雲寺樓寄湖州張郎中 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d156a2c-d295-4474-8422-786d994266a2', '過驪山作', '過驪山作', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["始皇東遊出周鼎，劉項縱觀皆引頸。","削平天下實辛勤，却爲道傍窮百姓。","黔首不愚爾益愚，千里函關囚獨夫。","牧童火入九泉底，燒作灰時猶未枯。"]', '["始皇东游出周鼎，劉項縱观皆引頸。","削平天下實辛勤，却爲道傍窮百姓。","黔首不愚爾益愚，千里函关囚独夫。","牧童火入九泉底，燒作灰时猶未枯。"]', '诗', 'shi', '', NULL, '過驪山作 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86292a61-8f33-4b35-bbcb-498430f26245', '池州送孟遲先輩', '池州送孟遲先輩', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["昔子來陵陽，時當苦炎熱。","我雖在金臺，頭角長垂折。","奉披塵意驚，立語平生豁。","寺樓最鶱軒，坐送飛鳥沒。","一罇中夜酒，半破前峰月。","烟院松飄蕭，風廊竹交戛。","時步郭西南，繚徑苔圓折。","好鳥響丁丁，小溪光汃汃。","籬落見娉婷，機絲弄啞軋。","烟濕樹姿嬌，雨餘山態活。","仲秋往歷陽，同上牛磯歇。","大江吞天去，一練橫坤抹。","千帆美滿風，曉日殷鮮血。","歷陽裴太守，襟韻苦超越。","鞔鼓畫麒麟，看君擊狂節。","離袖颭應勞，恨粉啼還咽。","明年忝諫官，綠樹秦川闊。","子提健筆來，勢若夸父渴。","九衢林馬撾，千門織車轍。","秦臺破心膽，黥陣驚毛髪。","子既屈一鳴，余固宜三刖。","慵憂長者來，病怯長街喝。","僧爐風雪夜，相對眠一褐。","暖灰重擁瓶，曉粥還分鉢。","青雲馬生角，黃州使持節。","秦嶺望樊川，秖得回頭別。","商山四皓祠，心與樗蒲說。","大澤蒹葭風，孤城狐兔窟。","且復考詩書，無因見簪笏。","古訓屹如山，古風冷刮骨。","周鼎列瓶罌，荆璧橫拋摋。","力盡不可取，忽忽狂歌發。","三年未爲苦，兩郡非不達。","秋浦倚吳江，去檝飛青鶻。","溪山好畫圖，洞壑深閨闥。","竹岡森羽林，花塢團宮纈。","景物非不佳，獨坐如韝紲。","丹鵲東飛來，喃喃送君札。","呼兒旋供衫，走門空踏襪。","手把一枝物，桂花香帶雪。","喜極至無言，笑餘翻不悅。","人生直作百歲翁，亦是萬古一瞬中。","我欲東召龍伯翁，上天揭取北斗柄。","蓬萊頂上斡海水，水盡到底看海空。","月於何處去，日于何處來？","跳丸相趁走不住，堯舜禹湯文武周孔皆爲灰。","酌此一杯酒，與君狂且歌。","離別豈足更關意，衰老相隨可奈何。"]', '["昔子来陵陽，时當苦炎熱。","我雖在金台，头角长垂折。","奉披塵意驚，立語平生豁。","寺楼最鶱軒，坐送飞鸟沒。","一罇中夜酒，半破前峰月。","烟院松飄蕭，风廊竹交戛。","时步郭西南，繚徑苔圓折。","好鸟响丁丁，小溪光汃汃。","籬落见娉婷，機絲弄啞軋。","烟濕樹姿嬌，雨餘山態活。","仲秋往歷陽，同上牛磯歇。","大江吞天去，一練橫坤抹。","千帆美满风，晓日殷鲜血。","歷陽裴太守，襟韻苦超越。","鞔鼓畫麒麟，看君擊狂節。","離袖颭應勞，恨粉啼還咽。","明年忝諫官，綠樹秦川闊。","子提健笔来，勢若夸父渴。","九衢林马撾，千门织车轍。","秦台破心膽，黥陣驚毛髪。","子既屈一鳴，余固宜三刖。","慵憂长者来，病怯长街喝。","僧爐风雪夜，相对眠一褐。","暖灰重擁瓶，晓粥還分鉢。","青云马生角，黄州使持節。","秦嶺望樊川，秖得回头別。","商山四皓祠，心與樗蒲说。","大澤蒹葭风，孤城狐兔窟。","且复考诗书，無因见簪笏。","古訓屹如山，古风冷刮骨。","周鼎列瓶罌，荆璧橫拋摋。","力尽不可取，忽忽狂歌發。","三年未爲苦，兩郡非不達。","秋浦倚吳江，去檝飞青鶻。","溪山好畫圖，洞壑深閨闥。","竹岡森羽林，花塢團宮纈。","景物非不佳，独坐如韝紲。","丹鵲东飞来，喃喃送君札。","呼兒旋供衫，走门空踏襪。","手把一枝物，桂花香带雪。","喜極至無言，笑餘翻不悅。","人生直作百歲翁，亦是万古一瞬中。","我欲东召龙伯翁，上天揭取北斗柄。","蓬萊頂上斡海水，水尽到底看海空。","月於何处去，日于何处来？","跳丸相趁走不住，堯舜禹湯文武周孔皆爲灰。","酌此一杯酒，與君狂且歌。","離別豈足更关意，衰老相隨可奈何。"]', '诗', 'shi', '', NULL, '池州送孟遲先輩 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a337ea22-8120-47eb-a23b-f8e3af843077', '重送', '重送', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["手撚金僕姑，腰懸玉轆轤。","爬頭峰北正好去，係取可汗鉗作奴。","六宮雖念相如賦，其那防邊重武夫。"]', '["手撚金僕姑，腰懸玉轆轤。","爬头峰北正好去，係取可汗鉗作奴。","六宮雖念相如賦，其那防邊重武夫。"]', '诗', 'shi', '', NULL, '重送 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbfba3c0-60a7-4b6a-95f0-1cf8ab994ff8', '題池州弄水亭', '題池州弄水亭', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["弄水亭前溪，颭灩翠綃舞。","綺席草芊芊，紫嵐峯伍伍。","螭蟠得形勢，翬飛如軒戶。","一鏡匳曲堤，萬丸跳猛雨。","檻前燕鴈棲，枕上巴帆去。","叢筠侍修廊，密蕙媚幽圃。","杉樹碧爲幢，花駢紅作堵。","停樽遲晚月，咽咽上幽渚。","客舟耿孤燈，萬里人夜語。","漫流罥苔槎，飢鳧曬雪羽。","玄絲落鉤餌，冰鱗看吞吐。","斷霓天帔垂，狂燒漢旗怒。","曠朗半秋曉，蕭瑟好風露。","光潔疑可攬，欲以襟懷貯。","幽抱吟九歌，羈情思湘浦。","四時皆異狀，終日爲良遇。","小山浸石稜，撑舟入幽處。","孤歌倚桂巖，晚酒眠松塢。","紆餘帶竹村，蠶鄉足砧杵。","塍泉落環珮，畦苗差纂組。","風俗知所尚，豪強耻孤侮。","隣喪不相舂，公租無詬負。","農時貴伏臘，簪瑱事禮賂。","鄉校富華禮，征行產強弩。","不能自勉去，但媿來何暮。","故園漢上林，信美非吾土。"]', '["弄水亭前溪，颭灩翠綃舞。","綺席草芊芊，紫嵐峯伍伍。","螭蟠得形勢，翬飞如軒戶。","一镜匳曲堤，万丸跳猛雨。","檻前燕鴈棲，枕上巴帆去。","叢筠侍修廊，密蕙媚幽圃。","杉樹碧爲幢，花駢紅作堵。","停樽遲晚月，咽咽上幽渚。","客舟耿孤灯，万里人夜語。","漫流罥苔槎，飢鳧曬雪羽。","玄絲落鉤餌，冰鱗看吞吐。","斷霓天帔垂，狂燒漢旗怒。","曠朗半秋晓，蕭瑟好风露。","光潔疑可攬，欲以襟懷貯。","幽抱吟九歌，羈情思湘浦。","四时皆異狀，終日爲良遇。","小山浸石稜，撑舟入幽处。","孤歌倚桂巖，晚酒眠松塢。","紆餘带竹村，蠶乡足砧杵。","塍泉落环珮，畦苗差纂組。","风俗知所尚，豪強耻孤侮。","隣喪不相舂，公租無詬負。","農时貴伏臘，簪瑱事禮賂。","乡校富华禮，征行產強弩。","不能自勉去，但媿来何暮。","故园漢上林，信美非吾土。"]', '诗', 'shi', '', NULL, '題池州弄水亭 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03c19b2c-c28a-4b55-a963-bf71b354f7a2', '題宣州開元寺', '題宣州开元寺', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["南朝謝眺城，東吳最深處。","亡國去如鴻，遺寺藏烟塢。","樓飛九十尺，廊環四百柱。","高高下下中，風繞松桂樹。","青苔照朱閣，白鳥兩相語。","溪聲入僧夢，月色暉粉堵。","閱景無旦夕，憑闌有今古。","留我酒一罇，前山看春雨。"]', '["南朝謝眺城，东吳最深处。","亡国去如鴻，遺寺藏烟塢。","楼飞九十尺，廊环四百柱。","高高下下中，风繞松桂樹。","青苔照朱閣，白鸟兩相語。","溪声入僧梦，月色暉粉堵。","閱景無旦夕，憑闌有今古。","留我酒一罇，前山看春雨。"]', '诗', 'shi', '', NULL, '題宣州開元寺 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c4f47e6-7e0d-4787-ac88-7e6921b33667', '大雨行', '大雨行', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["東垠黑風駕海水，海底卷上天中央。","三吳六月忽悽慘，晚後點滴來蒼茫。","錚棧雷車軸轍壯，矯躩蛟龍爪尾長。","神鞭鬼馭載陰帝，來往噴灑何顚狂。","四面崩騰玉京仗，萬里橫互羽林槍。","雲纏風束亂敲磕，黃帝未勝蚩尤強。","百川氣勢苦豪俊，坤關密鏁愁開張。","太和六年亦如此，我時壯氣神洋洋。","東樓聳首看不足，恨無羽翼高飛翔。","盡召邑中豪健者，闊展朱盤開酒場。","奔觥槌鼓助聲勢，眼底不顧纖腰娘。","今年闒茸鬢已白，奇遊壯觀唯深藏。","景物不盡人自老，誰知前事堪悲傷。"]', '["东垠黑风駕海水，海底卷上天中央。","三吳六月忽悽慘，晚後点滴来蒼茫。","錚棧雷车軸轍壯，矯躩蛟龙爪尾长。","神鞭鬼馭載陰帝，来往噴灑何顚狂。","四面崩腾玉京仗，万里橫互羽林槍。","云纏风束亂敲磕，黄帝未勝蚩尤強。","百川氣勢苦豪俊，坤关密鏁愁开張。","太和六年亦如此，我时壯氣神洋洋。","东楼聳首看不足，恨無羽翼高飞翔。","尽召邑中豪健者，闊展朱盤开酒場。","奔觥槌鼓助声勢，眼底不顧纖腰娘。","今年闒茸鬢已白，奇游壯观唯深藏。","景物不尽人自老，誰知前事堪悲傷。"]', '诗', 'shi', '', NULL, '大雨行 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80501b83-39ec-4237-b760-69cc32067ba0', '自宣州赴官入京路逢裴坦判官歸宣州因題贈', '自宣州赴官入京路逢裴坦判官归宣州因題贈', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["敬亭山下百頃竹，中有詩人小謝城。","城高跨樓滿金碧，下聽一溪寒水聲。","梅花落徑香繚繞，雪白玉璫花下行。","縈風酒斾挂朱閣，半醉遊人聞弄笙。","我初到此未三十，頭腦釤利筋骨輕。","畫堂檀板秋拍碎，一引有時聯十觥。","老閑腰下丈二組，塵土高懸千載名。","重遊鬢白事皆改，唯見東流春水平。","對酒不敢起，逢君還眼明。","雲罍看人捧，波臉任他橫。","一醉六十日，古來聞阮生。","是非離別際，始見醉中情。","今日送君話前事，高歌引劒還一傾。","江湖酒伴如相問，終老烟波不計程。"]', '["敬亭山下百頃竹，中有诗人小謝城。","城高跨楼满金碧，下听一溪寒水声。","梅花落徑香繚繞，雪白玉璫花下行。","縈风酒斾挂朱閣，半醉游人闻弄笙。","我初到此未三十，头腦釤利筋骨轻。","畫堂檀板秋拍碎，一引有时聯十觥。","老闲腰下丈二組，塵土高懸千載名。","重游鬢白事皆改，唯见东流春水平。","对酒不敢起，逢君還眼明。","云罍看人捧，波臉任他橫。","一醉六十日，古来闻阮生。","是非離別際，始见醉中情。","今日送君話前事，高歌引劒還一傾。","江湖酒伴如相问，終老烟波不計程。"]', '诗', 'shi', '', NULL, '自宣州赴官入京路逢裴坦判官歸宣州因題贈 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87007df8-aaeb-4050-aa30-c3ca59e9433c', '贈宣州元處士', '贈宣州元处士', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["陵陽北郭隱，身世兩忘者。","蓬蒿三畝居，寬於一天下。","罇酒對不酌，默與玄相話。","人生自不足，愛歎遭逢寡。"]', '["陵陽北郭隐，身世兩忘者。","蓬蒿三畝居，寬於一天下。","罇酒对不酌，默與玄相話。","人生自不足，愛歎遭逢寡。"]', '诗', 'shi', '', NULL, '贈宣州元處士 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd34c792-ce55-4e8c-9625-88802d985c38', '村行', '村行', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["春半南陽西，柔桑過村塢。","褭褭垂柳風，點點迴塘雨。","蓑唱牧牛兒，籬窺蒨裙女。","半濕解征衫，主人饋雞黍。"]', '["春半南陽西，柔桑過村塢。","褭褭垂柳风，点点迴塘雨。","蓑唱牧牛兒，籬窺蒨裙女。","半濕解征衫，主人饋雞黍。"]', '诗', 'shi', '', NULL, '村行 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62c91e86-2423-4741-84ab-d392d7df173d', '史將軍二首 一', '史將軍二首 一', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["長鉟周都尉，閑如秋嶺雲。","取蝥弧登壘，以駢隣翼軍。","百戰百勝價，河南河北聞。","今遇太平日，老去誰憐君。"]', '["长鉟周都尉，闲如秋嶺云。","取蝥弧登壘，以駢隣翼軍。","百戰百勝價，河南河北闻。","今遇太平日，老去誰怜君。"]', '诗', 'shi', '', NULL, '史將軍二首 一 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1a5a818-4f0b-4a55-a237-cc85e3767b7b', '史將軍二首 二', '史將軍二首 二', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["壯氣蓋燕趙，耽耽魁傑人。","彎弧五百步，長戟八十斤。","河湟非內地，安史有遺塵。","何日武臺坐，兵符授虎臣。"]', '["壯氣蓋燕趙，耽耽魁傑人。","彎弧五百步，长戟八十斤。","河湟非內地，安史有遺塵。","何日武台坐，兵符授虎臣。"]', '诗', 'shi', '', NULL, '史將軍二首 二 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0532d507-dd36-4bb4-868a-fe771d68c11e', '華清宮三十韻', '华清宮三十韻', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["繡嶺明珠殿，層巒下繚牆。","仰窺丹檻影，猶想赭袍光。","昔帝登封後，中原自古強。","一千年際會，三萬里農桑。","几席延堯舜，軒墀接禹湯。","雷霆馳號令，星斗煥文章。","釣築乘時用，芝蘭在處芳。","北扉閑木索，南面富循良。","至道思玄圃，平居厭未央。","鉤陳裹巖谷，文陛壓青蒼。","歌吹千秋節，樓臺八月涼。","神仙高縹緲，環珮碎丁當。","泉暖涵窓鏡，雲嬌惹粉囊。","嫩嵐滋翠葆，清渭照紅粧。","帖泰生靈壽，懽娛歲序長。","月聞仙曲調，霓作舞衣裳。","雨露偏金穴，乾坤入醉鄉。","玩兵師漢武，迴手倒干將。","黥鬣掀東海，胡牙揭上陽。","喧呼馬嵬血，零落羽林槍。","傾國留無路，還魂怨有香。","蜀峰橫慘澹，秦樹遠微茫。","鼎重山難轉，天扶業更昌。","望賢餘故老，花萼舊池塘。","往事人誰問，幽襟淚獨傷。","碧簷斜送日，殷葉半凋霜。","迸水傾瑤砌，疎風罅玉房。","塵埃羯鼓索，片段荔枝筐。","鳥啄摧寒木，蝸涎蠹畫梁。","孤煙知客恨，遙起泰陵傍。"]', '["繡嶺明珠殿，層巒下繚牆。","仰窺丹檻影，猶想赭袍光。","昔帝登封後，中原自古強。","一千年際會，三万里農桑。","几席延堯舜，軒墀接禹湯。","雷霆驰號令，星斗煥文章。","釣築乘时用，芝蘭在处芳。","北扉闲木索，南面富循良。","至道思玄圃，平居厭未央。","鉤陳裹巖谷，文陛壓青蒼。","歌吹千秋節，楼台八月涼。","神仙高縹緲，环珮碎丁當。","泉暖涵窓镜，云嬌惹粉囊。","嫩嵐滋翠葆，清渭照紅粧。","帖泰生靈壽，懽娛歲序长。","月闻仙曲調，霓作舞衣裳。","雨露偏金穴，乾坤入醉乡。","玩兵師漢武，迴手倒干將。","黥鬣掀东海，胡牙揭上陽。","喧呼马嵬血，零落羽林槍。","傾国留無路，還魂怨有香。","蜀峰橫慘澹，秦樹远微茫。","鼎重山难轉，天扶業更昌。","望賢餘故老，花萼旧池塘。","往事人誰问，幽襟泪独傷。","碧簷斜送日，殷葉半凋霜。","迸水傾瑤砌，疎风罅玉房。","塵埃羯鼓索，片段荔枝筐。","鸟啄摧寒木，蝸涎蠹畫梁。","孤煙知客恨，遙起泰陵傍。"]', '诗', 'shi', '', NULL, '華清宮三十韻 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d9eee90-19c6-46c5-95bc-3e34c86359aa', '長安雜題長句六首 一', '长安杂題长句六首 一', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["觚稜金碧照山高，萬國珪璋捧赭袍。","舐筆和鉛欺賈馬，讚功論道鄙蕭曹。","東南樓日珠簾卷，西北天宛玉厄豪。","四海一家無一事，將軍攜鏡泣霜毛。"]', '["觚稜金碧照山高，万国珪璋捧赭袍。","舐笔和鉛欺賈马，讚功論道鄙蕭曹。","东南楼日珠簾卷，西北天宛玉厄豪。","四海一家無一事，將軍携镜泣霜毛。"]', '诗', 'shi', '', NULL, '長安雜題長句六首 一 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a62027b9-ac14-4a96-a5b6-1471d107f42d', '長安雜題長句六首 二', '长安杂題长句六首 二', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["晴雲似絮惹低空，紫陌微微弄袖風。","韓嫣金丸莎覆綠，許公韉汗杏粘紅。","煙生窈窕深東第，輪撼流蘇下北宮。","自笑苦無樓護智，可憐鉛槧竟何功。"]', '["晴云似絮惹低空，紫陌微微弄袖风。","韓嫣金丸莎覆綠，許公韉汗杏粘紅。","煙生窈窕深东第，輪撼流蘇下北宮。","自笑苦無楼護智，可怜鉛槧竟何功。"]', '诗', 'shi', '', NULL, '長安雜題長句六首 二 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('435da91f-fece-442b-8567-107ba31ebaa0', '長安雜題長句六首 三', '长安杂題长句六首 三', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["雨晴九陌鋪江練，嵐嫩千峰疊海濤。","南苑草芳眠錦雉，夾城雲暖下霓旄。","少年羈絡青紋玉，遊女花簪紫蒂桃。","江碧柳深人盡醉，一瓢顏巷日空高。"]', '["雨晴九陌鋪江練，嵐嫩千峰叠海濤。","南苑草芳眠錦雉，夾城云暖下霓旄。","少年羈絡青紋玉，游女花簪紫蒂桃。","江碧柳深人尽醉，一瓢顏巷日空高。"]', '诗', 'shi', '', NULL, '長安雜題長句六首 三 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afc6681b-6e31-4b0f-988e-f2566d2808a5', '長安雜題長句六首 四', '长安杂題长句六首 四', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["束帶謬趨文石陛，有章曾拜皁囊封。","期嚴無奈睡留癖，勢窘猶爲酒泥慵。","偷釣侯家池上雨，醉吟隋寺日沈鐘。","九原可作吾誰與，師友瑯琊邴曼容。"]', '["束带謬趨文石陛，有章曾拜皁囊封。","期嚴無奈睡留癖，勢窘猶爲酒泥慵。","偷釣侯家池上雨，醉吟隋寺日沈鐘。","九原可作吾誰與，師友瑯琊邴曼容。"]', '诗', 'shi', '', NULL, '長安雜題長句六首 四 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48b8d48b-5e63-4cf2-be67-9f110823d690', '長安雜題長句六首 五', '长安杂題长句六首 五', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["洪河清渭天池濬，太白終南地軸橫。","祥雲輝映漢宮紫，春光繡畫秦川明。","草妬佳人鈿朵色，風回公子玉銜聲。","六飛南幸芙蓉苑，十里飄香入夾城。"]', '["洪河清渭天池濬，太白終南地軸橫。","祥云輝映漢宮紫，春光繡畫秦川明。","草妬佳人鈿朵色，风回公子玉銜声。","六飞南幸芙蓉苑，十里飄香入夾城。"]', '诗', 'shi', '', NULL, '長安雜題長句六首 五 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26ad42b7-b471-43d8-a403-61c70d011cf2', '長安雜題長句六首 六', '长安杂題长句六首 六', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["豐貂長組金張輩，駟馬文衣許史家。","白鹿原頭回獵騎，紫雲樓下醉江花。","九重樹影連清漢，萬壽山光學翠華。","誰識大君謙讓德，一毫名利鬬鼃蟇。"]', '["豐貂长組金張輩，駟马文衣許史家。","白鹿原头回獵騎，紫云楼下醉江花。","九重樹影連清漢，万壽山光学翠华。","誰識大君謙讓德，一毫名利鬬鼃蟇。"]', '诗', 'shi', '', NULL, '長安雜題長句六首 六 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22e1a6e4-3934-4d1d-a3ad-ce4606e423e4', '河湟', '河湟', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["元載相公曾借箸，憲宗皇帝亦留神。","旋見衣冠就東市，忽遺弓劒不西巡。","牧羊驅馬雖戎服，白髮丹心盡漢臣。","唯有涼州歌舞曲，流傳天下樂閑人。"]', '["元載相公曾借箸，憲宗皇帝亦留神。","旋见衣冠就东市，忽遺弓劒不西巡。","牧羊驱马雖戎服，白髮丹心尽漢臣。","唯有涼州歌舞曲，流傳天下乐闲人。"]', '诗', 'shi', '', NULL, '河湟 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1836f0d-c025-4227-994c-81fcc32abab4', '許七侍御棄官東歸瀟灑江南頗聞自適高秋企望題詩寄贈十韻', '許七侍御棄官东归瀟灑江南頗闻自適高秋企望題诗寄贈十韻', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["天子繡衣吏，東吳美退居。","有園同庾信，避事學相如。","蘭畹晴香嫩，筠溪翠影疎。","江山九秋後，風月六朝餘。","錦帙開詩軸，青囊結道書。","霜巖紅薜荔，露沼白芙蕖。","睡雨高梧密，棊燈小閣虛。","凍醪元亮秫，寒鱠季鷹魚。","塵意迷今古，雲情識卷舒。","他年雪中櫂，陽羨訪吾廬。"]', '["天子繡衣吏，东吳美退居。","有园同庾信，避事学相如。","蘭畹晴香嫩，筠溪翠影疎。","江山九秋後，风月六朝餘。","錦帙开诗軸，青囊結道书。","霜巖紅薜荔，露沼白芙蕖。","睡雨高梧密，棊灯小閣虛。","凍醪元亮秫，寒鱠季鷹鱼。","塵意迷今古，云情識卷舒。","他年雪中櫂，陽羨訪吾廬。"]', '诗', 'shi', '', NULL, '許七侍御棄官東歸瀟灑江南頗聞自適高秋企望題詩寄贈十韻 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21a25ad0-efcd-4736-bb8a-7bdd1718f45a', '李給事中敏二首 一', '李給事中敏二首 一', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["一章緘拜皁囊中，懍懍朝廷有古風。","元禮去歸緱氏學江充來見犬臺宮。","紛紜白晝驚千古，鈇鑕朱殷幾一空。","曲突徙薪人不會，海邊今作釣魚翁。"]', '["一章緘拜皁囊中，懍懍朝廷有古风。","元禮去归緱氏学江充来见犬台宮。","紛紜白晝驚千古，鈇鑕朱殷幾一空。","曲突徙薪人不會，海邊今作釣鱼翁。"]', '诗', 'shi', '', NULL, '李給事中敏二首 一 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbea466c-3c71-4c61-a50b-8528c8a23328', '李給事中敏二首 二', '李給事中敏二首 二', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["晚髪悶還梳，憶君秋醉餘。","可憐劉校尉，曾訟石中書。","消長雖殊事，仁賢每自如。"]', '["晚髪悶還梳，憶君秋醉餘。","可怜劉校尉，曾訟石中书。","消长雖殊事，仁賢每自如。"]', '诗', 'shi', '', NULL, '李給事中敏二首 二 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2656c476-8e06-4d52-bed8-5102a10e0130', '題永崇西平王宅太尉愬院六韻', '題永崇西平王宅太尉愬院六韻', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["天下無雙將，關西第一雄。","授符黃石老，學劒白猿翁。","矯矯雲長勇，恂恂郄縠風。","家呼小太尉，國號大梁公。","半夜龍驤去，中原虎穴空。","隴山兵十萬，嗣子握琱弓。"]', '["天下無雙將，关西第一雄。","授符黄石老，学劒白猿翁。","矯矯云长勇，恂恂郄縠风。","家呼小太尉，国號大梁公。","半夜龙驤去，中原虎穴空。","隴山兵十万，嗣子握琱弓。"]', '诗', 'shi', '', NULL, '題永崇西平王宅太尉愬院六韻 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16aeb267-54a8-4c49-9d94-3306022db14d', '東兵長句十韻', '东兵长句十韻', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["上黨爭爲天下脊，邯鄲四十萬秦坑。","狂童何者欲專地，聖主無私豈翫兵。","玄象森羅搖北落，詩人章句詠東征。","雄如馬武皆彈劒，少似終軍亦請纓。","屈指廟堂無失策，垂衣堯舜待昇平。","羽林東下雷霆怒，楚甲南來組練明。","即墨龍文光照曜，常山蛇陣勢縱橫。","落鵰都尉萬人敵，黑矟將軍一鳥輕。","漸見長圍雲欲合，可憐窮壘帶猶縈。","凱歌應是新年唱，便逐春風浩浩聲。"]', '["上黨爭爲天下脊，邯鄲四十万秦坑。","狂童何者欲專地，聖主無私豈翫兵。","玄象森羅搖北落，诗人章句詠东征。","雄如马武皆彈劒，少似終軍亦請纓。","屈指廟堂無失策，垂衣堯舜待昇平。","羽林东下雷霆怒，楚甲南来組練明。","即墨龙文光照曜，常山蛇陣勢縱橫。","落鵰都尉万人敵，黑矟將軍一鸟轻。","漸见长圍云欲合，可怜窮壘带猶縈。","凱歌應是新年唱，便逐春风浩浩声。"]', '诗', 'shi', '', NULL, '東兵長句十韻 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e0663db-9490-4fb0-9078-2893d7bea293', '過勤政樓', '過勤政楼', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["千秋令節名空在，承露絲囊世已無。","唯有紫苔偏得意，年年因雨上金鋪。"]', '["千秋令節名空在，承露絲囊世已無。","唯有紫苔偏得意，年年因雨上金鋪。"]', '诗', 'shi', '', NULL, '過勤政樓 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6530863-e268-46d9-8987-932b95880479', '過魏文貞公宅', '過魏文貞公宅', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["蟪蛄寧與雪霜期，賢哲難教俗士知。","可憐貞觀太平後，天且不留封德彝。"]', '["蟪蛄寧與雪霜期，賢哲难教俗士知。","可怜貞观太平後，天且不留封德彝。"]', '诗', 'shi', '', NULL, '過魏文貞公宅 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('690d298b-3851-4c06-9a4c-6fb0d2edf3b9', '早春閣下寓直蕭九舍人亦直內署因寄書懷四韻', '早春閣下寓直蕭九舍人亦直內署因寄书懷四韻', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["御水初銷凍，宮花尚怯寒。","千峰橫紫翠，雙闕凭闌干。","玉漏輕風順，金莖淡日殘。","王喬在何處，清漢正驂鸞。"]', '["御水初銷凍，宮花尚怯寒。","千峰橫紫翠，雙闕凭闌干。","玉漏轻风順，金莖淡日殘。","王喬在何处，清漢正驂鸾。"]', '诗', 'shi', '', NULL, '早春閣下寓直蕭九舍人亦直內署因寄書懷四韻 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('594fbb93-3c35-4cb6-a972-cbdfa2af3c48', '秋晚與沈十七舍人期遊樊川不至', '秋晚與沈十七舍人期游樊川不至', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["邀侶以官解，泛然成獨遊。","川光初媚日，山色正矜秋。","野竹疎還密，巖泉咽復流。","杜村連潏水，晚步見垂鉤。"]', '["邀侶以官解，泛然成独游。","川光初媚日，山色正矜秋。","野竹疎還密，巖泉咽复流。","杜村連潏水，晚步见垂鉤。"]', '诗', 'shi', '', NULL, '秋晚與沈十七舍人期遊樊川不至 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dd71670-cca1-4053-8717-7eae8e581eb0', '念昔遊三首 一', '念昔游三首 一', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["十載飄然繩檢外，罇前自獻自爲酬。","秋山春雨閑吟處，倚徧江南寺寺樓。"]', '["十載飄然繩檢外，罇前自獻自爲酬。","秋山春雨闲吟处，倚徧江南寺寺楼。"]', '诗', 'shi', '', NULL, '念昔遊三首 一 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4f7b1c2-21e2-469a-ab95-72927d5958d8', '念昔遊三首 二', '念昔游三首 二', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["雲門寺外逢猛雨，林黑山高雨脚長。","曾奉郊宮爲近侍，分明羽林槍。"]', '["云门寺外逢猛雨，林黑山高雨脚长。","曾奉郊宮爲近侍，分明羽林槍。"]', '诗', 'shi', '', NULL, '念昔遊三首 二 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab3d61d5-ed3d-4573-b61d-7e3b9af7715f', '念昔遊三首 三', '念昔游三首 三', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["李白題詩水西寺，古木回巖樓閣風。","半醒半醉遊三日，紅白花開山雨中。"]', '["李白題诗水西寺，古木回巖楼閣风。","半醒半醉游三日，紅白花开山雨中。"]', '诗', 'shi', '', NULL, '念昔遊三首 三 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8302824-60db-4898-b5f7-de39d4666f6b', '今皇帝陛下一詔徵兵不日功集河湟諸郡次第歸降臣獲覩聖功輒獻歌詠', '今皇帝陛下一詔徵兵不日功集河湟諸郡次第归降臣獲覩聖功輒獻歌詠', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["捷書皆應睿謀期，十萬曾無一鏃遺。","漢武慙誇朔方地，周宣休道太原師。","威加塞外寒來早，恩入河源凍合遲。","聽取滿城歌舞曲，涼州聲韻喜參差。"]', '["捷书皆應睿謀期，十万曾無一鏃遺。","漢武慙誇朔方地，周宣休道太原師。","威加塞外寒来早，恩入河源凍合遲。","听取满城歌舞曲，涼州声韻喜參差。"]', '诗', 'shi', '', NULL, '今皇帝陛下一詔徵兵不日功集河湟諸郡次第歸降臣獲覩聖功輒獻歌詠 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9c2e42e-a6c1-4203-9970-e23b77e06a78', '奉和白相公聖德和平致茲休運歲終功就合詠盛明呈上三相公長句四韻', '奉和白相公聖德和平致茲休運歲終功就合詠盛明呈上三相公长句四韻', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["行看臘破好年光，萬壽南山對未央。","黠戛可汗修職貢，文思天子復河湟。","應須日馭西巡狩，不假星弧北射狼。","吉甫裁詩歌盛業，一篇江漢美宣王。"]', '["行看臘破好年光，万壽南山对未央。","黠戛可汗修職貢，文思天子复河湟。","應須日馭西巡狩，不假星弧北射狼。","吉甫裁诗歌盛業，一篇江漢美宣王。"]', '诗', 'shi', '', NULL, '奉和白相公聖德和平致茲休運歲終功就合詠盛明呈上三相公長句四韻 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14316b5b-cba2-41e0-84bd-3c3ed0c02407', '過華清宮絕句三首 一', '過华清宮絕句三首 一', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["長安回望繡成堆，山頂千門次第開。","一騎紅塵妃子笑，無人知是荔枝來。"]', '["长安回望繡成堆，山頂千门次第开。","一騎紅塵妃子笑，無人知是荔枝来。"]', '诗', 'shi', '', NULL, '過華清宮絕句三首 一 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb86c6a7-f428-4126-8e80-262b9e3d7a52', '過華清宮絕句三首 二', '過华清宮絕句三首 二', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["新豐綠樹起黃埃，數騎漁陽探使回。","霓裳一曲千峰上，舞破中原始下來。"]', '["新豐綠樹起黄埃，數騎漁陽探使回。","霓裳一曲千峰上，舞破中原始下来。"]', '诗', 'shi', '', NULL, '過華清宮絕句三首 二 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('337d1cf5-29eb-44e3-a32e-30f97274ba7f', '過華清宮絕句三首 三', '過华清宮絕句三首 三', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["萬國笙歌醉太平，倚天樓殿月分明。","雲中亂拍祿山舞，風過重巒下笑聲。"]', '["万国笙歌醉太平，倚天楼殿月分明。","云中亂拍祿山舞，风過重巒下笑声。"]', '诗', 'shi', '', NULL, '過華清宮絕句三首 三 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a2432a7-d169-4216-8aaa-212a2ef3b690', '登樂遊原', '登乐游原', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["長空澹澹孤鳥沒，萬古銷沈向此中。","看取漢家何事業，五陵無樹起秋風。"]', '["长空澹澹孤鸟沒，万古銷沈向此中。","看取漢家何事業，五陵無樹起秋风。"]', '诗', 'shi', '', NULL, '登樂遊原 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a429d13-1d1b-4a15-9823-4abea75b9fa4', '聞慶州趙縱使君與党項戰中箭身死輒書長句', '闻慶州趙縱使君與党項戰中箭身死輒书长句', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["將軍獨乘鐵驄馬，榆溪戰中金僕姑。","死綏却是古來有，驍將自驚今日無。","青史文章爭點筆，朱門歌舞笑捐軀。","誰知我亦輕生者，不得君王丈二殳。"]', '["將軍独乘鐵驄马，榆溪戰中金僕姑。","死綏却是古来有，驍將自驚今日無。","青史文章爭点笔，朱门歌舞笑捐軀。","誰知我亦轻生者，不得君王丈二殳。"]', '诗', 'shi', '', NULL, '聞慶州趙縱使君與党項戰中箭身死輒書長句 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17172d81-1211-4265-8908-4a3ec146106c', '送容州唐中丞赴鎮', '送容州唐中丞赴鎮', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["交阯同星座，龍泉佩斗文。","燒香翠羽帳，看舞鬱金裙。","鷁首衝瀧浪，犀渠拂嶺雲。","莫教銅柱北，空說馬將軍。"]', '["交阯同星座，龙泉佩斗文。","燒香翠羽帳，看舞鬱金裙。","鷁首衝瀧浪，犀渠拂嶺云。","莫教銅柱北，空说马將軍。"]', '诗', 'shi', '', NULL, '送容州唐中丞赴鎮 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5cbf443-9e01-45ed-a539-112611295082', '夏州崔常侍自少常亞列出領麾幢十韻', '夏州崔常侍自少常亞列出領麾幢十韻', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["帝命詩書將，登壇禮樂卿。","三邊要高枕，萬里得長城。","對客猶褒博，填門已斾旌。","腰間五綬貴，天下一家榮。","野水差新燕，芳郊哢夏鶯。","別風嘶玉勒，殘日望金莖。","榆塞孤煙媚，銀川綠草明。","戈矛虓虎士，弓箭落鵰兵。","魏絳言堪採，陳湯事偶成。","若須垂竹帛，靜勝是功名。"]', '["帝命诗书將，登壇禮乐卿。","三邊要高枕，万里得长城。","对客猶褒博，填门已斾旌。","腰间五綬貴，天下一家榮。","野水差新燕，芳郊哢夏鶯。","別风嘶玉勒，殘日望金莖。","榆塞孤煙媚，銀川綠草明。","戈矛虓虎士，弓箭落鵰兵。","魏絳言堪採，陳湯事偶成。","若須垂竹帛，静勝是功名。"]', '诗', 'shi', '', NULL, '夏州崔常侍自少常亞列出領麾幢十韻 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('747fdddf-b43d-426c-bcbd-2f3b9eccb08e', '街西長句', '街西长句', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["碧池新漲浴嬌鴉，分鏁長安富貴家。","遊騎偶同人鬬酒，名園相倚杏交花。","銀鞦騕褭嘶宛馬，繡鞅璁瓏走鈿車。","一曲將軍何處笛，連雲芳草日初斜。"]', '["碧池新漲浴嬌鴉，分鏁长安富貴家。","游騎偶同人鬬酒，名园相倚杏交花。","銀鞦騕褭嘶宛马，繡鞅璁瓏走鈿车。","一曲將軍何处笛，連云芳草日初斜。"]', '诗', 'shi', '', NULL, '街西長句 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f06ddbb3-1a93-425c-9cc3-83d40f526348', '春申君', '春申君', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["烈士思酬國士恩，春申誰與快冤魂。","三千賓客總珠履，欲使何人殺李園。"]', '["烈士思酬国士恩，春申誰與快冤魂。","三千賓客總珠履，欲使何人殺李园。"]', '诗', 'shi', '', NULL, '春申君 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7ed23a0-683c-4d52-8e5e-abfed4b24bb5', '奉陵宮人', '奉陵宮人', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["相如死後無詞客，延壽亡來絕畫工。","玉顏不是黃金少，淚滴秋山入壽宮。"]', '["相如死後無词客，延壽亡来絕畫工。","玉顏不是黄金少，泪滴秋山入壽宮。"]', '诗', 'shi', '', NULL, '奉陵宮人 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30c9065b-873e-4240-a0ba-e4a4c7ec3cc6', '讀韓杜集', '读韓杜集', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["杜詩韓集愁來讀，似倩麻姑癢處抓。","天外鳳凰誰得髓，無人解合續弦膠。"]', '["杜诗韓集愁来读，似倩麻姑癢处抓。","天外鳳凰誰得髓，無人解合續弦膠。"]', '诗', 'shi', '', NULL, '讀韓杜集 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6688d66f-0e76-4669-a277-4a76316beacf', '春日言懷寄虢州李常侍十韻', '春日言懷寄虢州李常侍十韻', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["岸蘚生紅藥，巖泉漲碧塘。","地分蓮嶽秀，草接鼎原芳。","雨派潀漴急，風畦芷若香。","織蓬眠舴艋，驚夢起鴛鴦。","論吐開冰室，詩陳曝錦張。","貂簪荆玉潤，丹穴鳳毛光。","今日還珠守，何年執戟郎。","且嫌遊晝短，莫問積薪長。","無計披清裁，唯持祝壽觴。","願公如衛武，百歲尚康強。"]', '["岸蘚生紅藥，巖泉漲碧塘。","地分蓮嶽秀，草接鼎原芳。","雨派潀漴急，风畦芷若香。","织蓬眠舴艋，驚梦起鴛鴦。","論吐开冰室，诗陳曝錦張。","貂簪荆玉潤，丹穴鳳毛光。","今日還珠守，何年執戟郎。","且嫌游晝短，莫问積薪长。","無計披清裁，唯持祝壽觴。","願公如衛武，百歲尚康強。"]', '诗', 'shi', '', NULL, '春日言懷寄虢州李常侍十韻 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc087994-5a91-4153-89fe-92c6c51d2201', '李侍郎於陽羨里富有泉石牧亦於陽羨粗有薄產敘舊述懷因獻長句四韻', '李侍郎於陽羨里富有泉石牧亦於陽羨粗有薄產敘旧述懷因獻长句四韻', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["冥鴻不下非無意，塞馬歸來是偶然。","紫綬公卿今放曠，白頭郎吏尚留連。","終南山下拋泉洞，陽羨溪中買釣船。","欲與明公操履杖，願聞休去是何年。"]', '["冥鴻不下非無意，塞马归来是偶然。","紫綬公卿今放曠，白头郎吏尚留連。","終南山下拋泉洞，陽羨溪中買釣船。","欲與明公操履杖，願闻休去是何年。"]', '诗', 'shi', '', NULL, '李侍郎於陽羨里富有泉石牧亦於陽羨粗有薄產敘舊述懷因獻長句四韻 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f65a961-7967-4595-bce3-b7b094dfadfb', '贈李處士長句四韻', '贈李处士长句四韻', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["玉函怪牒鎖靈篆，紫洞香風吹碧桃。","老翁四目牙爪利，擲火萬里精神高。","靄靄祥雲隨步武，纍纍秋冢歎蓬蒿。","三山朝去應非久，姹女當窗繡羽袍。"]', '["玉函怪牒鎖靈篆，紫洞香风吹碧桃。","老翁四目牙爪利，擲火万里精神高。","靄靄祥云隨步武，纍纍秋冢歎蓬蒿。","三山朝去應非久，姹女當窗繡羽袍。"]', '诗', 'shi', '', NULL, '贈李處士長句四韻 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f97759c8-a206-4452-a695-8b0f40d7f720', '送國棊王逢', '送国棊王逢', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["玉子紋楸一路饒，最宜簷雨竹蕭蕭。","羸形暗去春泉長，拔勢橫來野火燒。","守道還如周柱史，鏖兵不羨霍嫖姚。","浮生七十更萬日，與子期于局上銷。"]', '["玉子紋楸一路饒，最宜簷雨竹蕭蕭。","羸形暗去春泉长，拔勢橫来野火燒。","守道還如周柱史，鏖兵不羨霍嫖姚。","浮生七十更万日，與子期于局上銷。"]', '诗', 'shi', '', NULL, '送國棊王逢 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d6d532d-4fe2-4883-b9c2-1a2af4f8ebb8', '重送絕句', '重送絕句', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["絕藝如君天下少，閑人似我世間無。","別後竹窓風雪夜，一燈明暗覆吳圖。"]', '["絕藝如君天下少，闲人似我世间無。","別後竹窓风雪夜，一灯明暗覆吳圖。"]', '诗', 'shi', '', NULL, '重送絕句 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51445201-8364-4479-8e38-44561562e28b', '少年行', '少年行', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["連環羈玉聲光碎，綠錦蔽泥虬卷高。","春風細雨走馬去，珠落璀璀白罽袍。"]', '["連环羈玉声光碎，綠錦蔽泥虬卷高。","春风細雨走马去，珠落璀璀白罽袍。"]', '诗', 'shi', '', NULL, '少年行 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a886252d-a06c-49f3-bc18-26a96a128dcd', '奉和門下相公送西川相公兼領相印出鎮全蜀詩十八韻', '奉和门下相公送西川相公兼領相印出鎮全蜀诗十八韻', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["盛業冠伊唐，台階翊戴光。","無私天雨露，有截舜衣裳。","蜀輟新衡鏡，池留舊鳳凰。","同心真石友，寫恨蔑河梁。","虎騎搖風斾，貂冠韻水蒼。","彤弓隨武庫，金印逐文房。","棧壓嘉陵咽，峰橫劒閣長。","前驅二星去，開險五丁忙。","回首崢嶸盡，連天草樹芳。","丹心懸魏闕，往事愴甘棠。","治化輕諸葛，威聲懾夜郎。","君平教說卦，夫子召升堂。","塞接西山雪，橋維萬里檣。","奪霞紅錦爛，撲地酒壚香。","忝逐三千客，曾依數仞牆。","滯頑堪白屋，攀附亦同行。","肉管伶倫曲，簫韶清廟章。","唱高知和寡，小子斐然狂。"]', '["盛業冠伊唐，台階翊戴光。","無私天雨露，有截舜衣裳。","蜀輟新衡镜，池留旧鳳凰。","同心真石友，寫恨蔑河梁。","虎騎搖风斾，貂冠韻水蒼。","彤弓隨武庫，金印逐文房。","棧壓嘉陵咽，峰橫劒閣长。","前驱二星去，开險五丁忙。","回首崢嶸尽，連天草樹芳。","丹心懸魏闕，往事愴甘棠。","治化轻諸葛，威声懾夜郎。","君平教说卦，夫子召升堂。","塞接西山雪，橋維万里檣。","奪霞紅錦爛，撲地酒壚香。","忝逐三千客，曾依數仞牆。","滯頑堪白屋，攀附亦同行。","肉管伶倫曲，簫韶清廟章。","唱高知和寡，小子斐然狂。"]', '诗', 'shi', '', NULL, '奉和門下相公送西川相公兼領相印出鎮全蜀詩十八韻 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b1d8442-4872-433e-9e0a-37be8fc98de8', '朱坡', '朱坡', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["下杜鄉園古，泉聲繞舍啼。","靜思長慘切，薄宦與乖暌。","北闕千門外，南山午谷西。","倚川紅葉嶺，連寺綠楊堤。","迥野翹霜鶴，澄潭舞錦雞。","濤驚堆萬岫，舸急轉千溪。","眉點萱牙嫩，風條柳幄迷。","岸藤梢虺尾，沙渚印麑蹄。","火燎湘桃塢，波光碧繡畦。","日痕絙翠巘，陂影墮晴霓。","蝸壁斕斑蘚，銀筵豆蔻泥。","洞雲生片段，苔徑繚高低。","偃蹇松公老，森嚴竹陣齊。","小蓮娃欲語，幽笋稚相攜。","漢館留餘趾，周臺接故蹊。","蟠蛟岡隱隱，班雉草萋萋。","樹老蘿紆組，巖深石啓閨。","侵窓紫桂茂，拂面翠禽棲。","有計冠終挂，無才筆謾提。","自塵何太甚，休笑觸藩羝。"]', '["下杜乡园古，泉声繞舍啼。","静思长慘切，薄宦與乖暌。","北闕千门外，南山午谷西。","倚川紅葉嶺，連寺綠楊堤。","迥野翹霜鹤，澄潭舞錦雞。","濤驚堆万岫，舸急轉千溪。","眉点萱牙嫩，风條柳幄迷。","岸藤梢虺尾，沙渚印麑蹄。","火燎湘桃塢，波光碧繡畦。","日痕絙翠巘，陂影墮晴霓。","蝸壁斕斑蘚，銀筵豆蔻泥。","洞云生片段，苔徑繚高低。","偃蹇松公老，森嚴竹陣齊。","小蓮娃欲語，幽笋稚相携。","漢館留餘趾，周台接故蹊。","蟠蛟岡隐隐，班雉草萋萋。","樹老蘿紆組，巖深石啓閨。","侵窓紫桂茂，拂面翠禽棲。","有計冠終挂，無才笔謾提。","自塵何太甚，休笑觸藩羝。"]', '诗', 'shi', '', NULL, '朱坡 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a9d092c-3ee9-4ca9-83f1-11bc59fb3986', '早春寄岳州李使君李善棊愛酒情地閑雅', '早春寄岳州李使君李善棊愛酒情地闲雅', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["城高倚峭巘，地勝足樓臺。","朔漠暖鴻去，瀟湘春水來。","縈盈幾多思，掩抑若爲裁。","返照三聲角，寒香一樹梅。","烏林芳草遠，赤壁健帆開。","往事空遺恨，東流豈不回。","分符潁川政，弔屈洛陽才。","拂匣調珠柱，磨鉛勘玉杯。","棊翻小窟勢，壚撥凍醪醅。"]', '["城高倚峭巘，地勝足楼台。","朔漠暖鴻去，瀟湘春水来。","縈盈幾多思，掩抑若爲裁。","返照三声角，寒香一樹梅。","烏林芳草远，赤壁健帆开。","往事空遺恨，东流豈不回。","分符潁川政，弔屈洛陽才。","拂匣調珠柱，磨鉛勘玉杯。","棊翻小窟勢，壚撥凍醪醅。"]', '诗', 'shi', '', NULL, '早春寄岳州李使君李善棊愛酒情地閑雅 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('909490a2-5083-4b45-b44c-0df6f7cd7eb3', '送王侍御赴夏口座主幕', '送王侍御赴夏口座主幕', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["君爲珠履三千客，我是青衿七十徒。","禮數全優知隗始，討論常見念回愚。","黃鶴樓前春水闊，一杯還憶故人無。"]', '["君爲珠履三千客，我是青衿七十徒。","禮數全優知隗始，討論常见念回愚。","黄鹤楼前春水闊，一杯還憶故人無。"]', '诗', 'shi', '', NULL, '送王侍御赴夏口座主幕 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c972bc6-cc65-4ead-a899-29a68298bb0f', '自貽', '自貽', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["杜陵蕭次君，遷少去官頻。","寂寞憐吾道，依稀似古人。","餙心無彩繢，到骨是風塵。","自嫌如匹素，刀尺不由身。"]', '["杜陵蕭次君，遷少去官頻。","寂寞怜吾道，依稀似古人。","餙心無彩繢，到骨是风塵。","自嫌如匹素，刀尺不由身。"]', '诗', 'shi', '', NULL, '自貽 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1c9fb4d-2e0c-4fe4-851e-31be5ce89454', '自遣', '自遣', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["四十已云老，況逢憂窘餘。","且抽持板手，却展小年書。","嗜酒狂嫌阮，知非晚笑蘧。","聞流寧歎吒，待俗不親疎。","遇事知裁剪，操心識卷舒。","還稱二千石，於我意何如。"]', '["四十已云老，況逢憂窘餘。","且抽持板手，却展小年书。","嗜酒狂嫌阮，知非晚笑蘧。","闻流寧歎吒，待俗不親疎。","遇事知裁剪，操心識卷舒。","還稱二千石，於我意何如。"]', '诗', 'shi', '', NULL, '自遣 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1f2edef-a6a6-40bd-97e1-c5dedb7976b2', '題桐葉', '題桐葉', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["去年桐落故溪上，把筆偶題歸燕詩。","江樓今日送歸燕，正是去年題葉時。","葉落燕歸真可惜，東流玄髪且無期。","笑筵歌席反惆悵，明月清風愴別離。","莊叟彭殤同在夢，陶潛身世兩相遺。","一丸五色成虛語，石爛松薪更莫疑。","哆侈不勞文似錦，進趨何必利如錐。","錢神任爾知無敵，酒聖於吾亦庶幾。","江畔秋光蟾閣鏡，檻前山翠茂陵眉。","樽香輕泛數枝菊，簷影斜侵半局棊。","休指宦遊論巧拙，秪將愚直禱神祇。","三吳煙水平生念，寧向閑人道所之。"]', '["去年桐落故溪上，把笔偶題归燕诗。","江楼今日送归燕，正是去年題葉时。","葉落燕归真可惜，东流玄髪且無期。","笑筵歌席反惆悵，明月清风愴別離。","莊叟彭殤同在梦，陶潛身世兩相遺。","一丸五色成虛語，石爛松薪更莫疑。","哆侈不勞文似錦，進趨何必利如錐。","錢神任爾知無敵，酒聖於吾亦庶幾。","江畔秋光蟾閣镜，檻前山翠茂陵眉。","樽香轻泛數枝菊，簷影斜侵半局棊。","休指宦游論巧拙，秪將愚直禱神祇。","三吳煙水平生念，寧向闲人道所之。"]', '诗', 'shi', '', NULL, '題桐葉 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e8ea9f7-c97d-40a9-ab5e-8317678d6377', '沈下賢', '沈下賢', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["斯人清唱何人和，草徑苔蕪不可尋。","一夕小敷山下夢，水如環珮月如襟。"]', '["斯人清唱何人和，草徑苔蕪不可尋。","一夕小敷山下梦，水如环珮月如襟。"]', '诗', 'shi', '', NULL, '沈下賢 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7f84fa9-a466-46f4-9934-ec9faff3ce19', '李和鼎', '李和鼎', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["鵩鳥飛來庚子直，謫去日蝕辛卯年。","由來枉死賢才事，消長相持勢自然。"]', '["鵩鸟飞来庚子直，謫去日蝕辛卯年。","由来枉死賢才事，消长相持勢自然。"]', '诗', 'shi', '', NULL, '李和鼎 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78e09255-add5-4659-9448-f085f3e72e22', '贈沈學士張歌人', '贈沈学士張歌人', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["拖袖事當年，郎教唱客前。","斷時輕裂玉，收處遠繰煙。","孤直縆雲定，光明滴水圓。","泥情遲急管，流恨咽長弦。","吳苑春風起，河橋酒斾懸。","憑君更一醉，家在杜陵邊。"]', '["拖袖事當年，郎教唱客前。","斷时轻裂玉，收处远繰煙。","孤直縆云定，光明滴水圓。","泥情遲急管，流恨咽长弦。","吳苑春风起，河橋酒斾懸。","憑君更一醉，家在杜陵邊。"]', '诗', 'shi', '', NULL, '贈沈學士張歌人 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0eb9c7e7-b800-4ec0-88a6-ed07d05ac67f', '憶遊朱坡四韻', '憶游朱坡四韻', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["秋草樊川路，斜陽覆盎門。","獵逢韓嫣騎，樹識館陶園。","帶雨經荷沼，盤烟下竹村。","如今歸不得，自戴望天盆。"]', '["秋草樊川路，斜陽覆盎门。","獵逢韓嫣騎，樹識館陶园。","带雨經荷沼，盤烟下竹村。","如今归不得，自戴望天盆。"]', '诗', 'shi', '', NULL, '憶遊朱坡四韻 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d83a9e7c-3c75-4cf0-9eab-0ca0085405f7', '朱坡絕句三首 一', '朱坡絕句三首 一', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["故國池塘倚御渠，江城三詔換魚書。","賈生辭賦恨流落，秪向長沙住歲餘。"]', '["故国池塘倚御渠，江城三詔換鱼书。","賈生辞賦恨流落，秪向长沙住歲餘。"]', '诗', 'shi', '', NULL, '朱坡絕句三首 一 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b35b626-7398-4f93-9dea-6497b9557bbe', '朱坡絕句三首 二', '朱坡絕句三首 二', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["煙深苔巷唱樵兒，花落寒輕倦客歸。","藤岸竹洲相掩映，滿池春雨鸊鵜飛。"]', '["煙深苔巷唱樵兒，花落寒轻倦客归。","藤岸竹洲相掩映，满池春雨鸊鵜飞。"]', '诗', 'shi', '', NULL, '朱坡絕句三首 二 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbb59b8b-ba8d-446e-a32a-3a5aba73215e', '朱坡絕句三首 三', '朱坡絕句三首 三', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["乳肥春洞生鵝管，沼避回巖勢犬牙。","自笑卷懷頭角縮，歸盤煙磴恰如蝸。"]', '["乳肥春洞生鵝管，沼避回巖勢犬牙。","自笑卷懷头角縮，归盤煙磴恰如蝸。"]', '诗', 'shi', '', NULL, '朱坡絕句三首 三 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0dcd49c4-9c54-4213-a053-0735ff32a300', '出宮人二首 一', '出宮人二首 一', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["閑吹玉殿昭華管，醉折梨園縹蔕花。","十年一夢歸人世，絳縷猶封繫臂紗。"]', '["闲吹玉殿昭华管，醉折梨园縹蔕花。","十年一梦归人世，絳縷猶封繫臂紗。"]', '诗', 'shi', '', NULL, '出宮人二首 一 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe0bd7d8-e052-444f-bc78-e450c1218ea5', '出宮人二首 二', '出宮人二首 二', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["平陽拊背穿馳道，銅雀分香下璧門。","幾向綴珠深殿裏，妬拋羞態臥黃昏。"]', '["平陽拊背穿驰道，銅雀分香下璧门。","幾向綴珠深殿裏，妬拋羞態臥黄昏。"]', '诗', 'shi', '', NULL, '出宮人二首 二 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95c94d96-7449-4eca-a38d-fcd0a435b729', '長安秋望', '长安秋望', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["樓倚霜樹外，鏡天無一毫。","南山與秋色，氣勢兩相高。"]', '["楼倚霜樹外，镜天無一毫。","南山與秋色，氣勢兩相高。"]', '诗', 'shi', '', NULL, '長安秋望 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8b2207b-ed83-4c74-adca-856c4eda51b5', '獨酌', '独酌', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["窓外正風雪，擁爐開酒缸。","何如釣船雨，蓬底睡秋江。"]', '["窓外正风雪，擁爐开酒缸。","何如釣船雨，蓬底睡秋江。"]', '诗', 'shi', '', NULL, '獨酌 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c98648f2-4460-4e42-8e3f-8330d837fa2a', '醉眠', '醉眠', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["秋醪雨中熟，寒齋落葉中。","幽人本多睡，更酌一樽空。"]', '["秋醪雨中熟，寒斋落葉中。","幽人本多睡，更酌一樽空。"]', '诗', 'shi', '', NULL, '醉眠 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c417148-927c-4333-bddd-0c72c081f126', '不飲贈酒', '不饮贈酒', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["細算人生事，彭殤共一籌。","與愁爭底事，要爾作戈矛。"]', '["細算人生事，彭殤共一籌。","與愁爭底事，要爾作戈矛。"]', '诗', 'shi', '', NULL, '不飲贈酒 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8222908-3d20-44a3-bf34-decc9d982042', '昔事文皇帝三十二韻', '昔事文皇帝三十二韻', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["昔事文皇帝，叨官在諫垣。","奏章爲得地，齚齒負明恩。","金虎知難動，毛釐亦恥言。","掩頭雖欲吐，到口却成吞。","照膽常懸鏡，窺天自戴盆。","周鐘既窕槬，黥陣亦瘢痕。","鳳闕觚稜影，仙盤曉日暾。","雨晴文石滑，風暖戟衣翻。","每慮號無告，長憂駭不存。","隨行唯跼蹐，出語但寒暄。","宮省咽喉任，戈矛羽衛屯。","光塵皆影附，車馬定西奔。","億萬持衡價，錙銖挾契論。","堆時過北斗，積處滿西園。","接櫂隋河溢，連蹄蜀棧刓。","漉空滄海水，搜盡卓王孫。","鬬巧猴雕刺，誇趫索挂跟。","狐威假白額，梟嘯得黃昏。","馥馥芝蘭圃，森森枳棘藩。","吠聲嗾國猘，公議怯膺門。","竄逐諸丞相，蒼茫遠帝閽。","一名爲吉士，誰免弔湘魂。","間世英明主，中興道德尊。","崑岡憐積火，河漢注清源。","川口隄防決，陰車鬼怪掀。","重雲開朗照，九地雪幽冤。","我實剛腸者，形甘短褐髠。","曾經觸蠆尾，猶得凭熊軒。","杜若芳洲翠，嚴光釣瀨喧。","溪山侵越角，封壤盡吳根。","客恨縈春細，鄉愁壓思繁。","祝堯千萬壽，再拜揖餘罇。"]', '["昔事文皇帝，叨官在諫垣。","奏章爲得地，齚齒負明恩。","金虎知难动，毛釐亦恥言。","掩头雖欲吐，到口却成吞。","照膽常懸镜，窺天自戴盆。","周鐘既窕槬，黥陣亦瘢痕。","鳳闕觚稜影，仙盤晓日暾。","雨晴文石滑，风暖戟衣翻。","每慮號無告，长憂駭不存。","隨行唯跼蹐，出語但寒暄。","宮省咽喉任，戈矛羽衛屯。","光塵皆影附，车马定西奔。","億万持衡價，錙銖挾契論。","堆时過北斗，積处满西园。","接櫂隋河溢，連蹄蜀棧刓。","漉空滄海水，搜尽卓王孫。","鬬巧猴雕刺，誇趫索挂跟。","狐威假白額，梟嘯得黄昏。","馥馥芝蘭圃，森森枳棘藩。","吠声嗾国猘，公議怯膺门。","竄逐諸丞相，蒼茫远帝閽。","一名爲吉士，誰免弔湘魂。","间世英明主，中兴道德尊。","崑岡怜積火，河漢注清源。","川口隄防決，陰车鬼怪掀。","重云开朗照，九地雪幽冤。","我實剛腸者，形甘短褐髠。","曾經觸蠆尾，猶得凭熊軒。","杜若芳洲翠，嚴光釣瀨喧。","溪山侵越角，封壤尽吳根。","客恨縈春細，乡愁壓思繁。","祝堯千万壽，再拜揖餘罇。"]', '诗', 'shi', '', NULL, '昔事文皇帝三十二韻 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad4f5881-dee8-459e-a238-1a6d71bb578d', '道一大尹存之庭美二學士簡于聖明自致霄漢皆與舍弟昔年還往牧支離窮悴竊於一麾書美歌詩兼自言志因成長句四韻呈上三君子', '道一大尹存之庭美二学士簡于聖明自致霄漢皆與舍弟昔年還往牧支離窮悴竊於一麾书美歌诗兼自言志因成长句四韻呈上三君子', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["九金神鼎重丘山，五玉諸侯雜珮環。","星座通霄狼鬣暗，戍樓吹笛虎牙閑。","斗間紫氣龍埋獄，天上洪爐帝鑄顏。","若念西河舊交友，魚符應許出函關。"]', '["九金神鼎重丘山，五玉諸侯杂珮环。","星座通霄狼鬣暗，戍楼吹笛虎牙闲。","斗间紫氣龙埋獄，天上洪爐帝鑄顏。","若念西河旧交友，鱼符應許出函关。"]', '诗', 'shi', '', NULL, '道一大尹存之庭美二學士簡于聖明自致霄漢皆與舍弟昔年還往牧支離窮悴竊於一麾書美歌詩兼自言志因成長句四韻呈上三君子 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81a76fa8-deac-4ef4-8142-04c9872b2f8a', '杏園', '杏园', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["夜來微雨洗芳塵，公子驊騮步貼勻。","莫怪杏園顦顇去，滿城多少插花人。"]', '["夜来微雨洗芳塵，公子驊騮步貼勻。","莫怪杏园顦顇去，满城多少插花人。"]', '诗', 'shi', '', NULL, '杏園 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88aa49da-9872-465a-a795-e3120ec633b4', '春晚題韋家亭子', '春晚題韋家亭子', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["擁鼻侵襟花草香，高臺春去恨茫茫。","蔫紅半落平池晚，曲渚飄成錦一張。"]', '["擁鼻侵襟花草香，高台春去恨茫茫。","蔫紅半落平池晚，曲渚飄成錦一張。"]', '诗', 'shi', '', NULL, '春晚題韋家亭子 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd78c143-aeb7-4443-8aeb-69e788d66c2e', '過田家宅', '過田家宅', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["安邑南門外，誰家板築高。","奉誠園裏地，牆缺見蓬蒿。"]', '["安邑南门外，誰家板築高。","奉誠园裏地，牆缺见蓬蒿。"]', '诗', 'shi', '', NULL, '過田家宅 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1aba19d5-e5cf-45cf-82ee-58648d419b25', '見宋拾遺題名處感而成詩', '见宋拾遺題名处感而成诗', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["竄逐窮荒與死期，餓唯蒿藿病無醫。","憐君更抱重泉恨，不見崇山謫去時。"]', '["竄逐窮荒與死期，餓唯蒿藿病無醫。","怜君更抱重泉恨，不见崇山謫去时。"]', '诗', 'shi', '', NULL, '見宋拾遺題名處感而成詩 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7421f3a-5cea-4476-aca5-6ab120303f16', '雪晴訪趙嘏街西所居三韻', '雪晴訪趙嘏街西所居三韻', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["命代風騷將，誰登李杜壇。","少陵鯨海動，翰苑鶴天寒。","今日訪君還有意，三條冰雪獨來看。"]', '["命代风騷將，誰登李杜壇。","少陵鯨海动，翰苑鹤天寒。","今日訪君還有意，三條冰雪独来看。"]', '诗', 'shi', '', NULL, '雪晴訪趙嘏街西所居三韻 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24ca9268-9cbd-423b-b423-12e1a9aa9041', '將赴吳興登樂遊原一絕', '將赴吳兴登乐游原一絕', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["清時有味是無能，閑愛孤雲靜愛僧。","欲把一麾江海去，樂遊原上望昭陵。"]', '["清时有味是無能，闲愛孤云静愛僧。","欲把一麾江海去，乐游原上望昭陵。"]', '诗', 'shi', '', NULL, '將赴吳興登樂遊原一絕 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5fc20d0-10f7-4b8c-954c-7198fcf2cd98', '洛陽長句二首 一', '洛陽长句二首 一', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["草色人心相與閑，是非名利有無間。","橋橫落照虹堪畫，樹鎖千門鳥自還。","芝蓋不來雲杳杳，仙舟何處水潺潺？","君王謙讓泥金事，蒼翠空高萬歲山。"]', '["草色人心相與闲，是非名利有無间。","橋橫落照虹堪畫，樹鎖千门鸟自還。","芝蓋不来云杳杳，仙舟何处水潺潺？","君王謙讓泥金事，蒼翠空高万歲山。"]', '诗', 'shi', '', NULL, '洛陽長句二首 一 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a16c3ba-6095-4c22-92ad-6e3adb53bee1', '洛陽長句二首 二', '洛陽长句二首 二', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["天漢東穿白玉京，日華浮動翠光生。","橋邊遊女珮環委，波底上陽金碧明。","月鎖名園孤鶴唳，川酣秋夢鑿龍聲。"]', '["天漢东穿白玉京，日华浮动翠光生。","橋邊游女珮环委，波底上陽金碧明。","月鎖名园孤鹤唳，川酣秋梦鑿龙声。"]', '诗', 'shi', '', NULL, '洛陽長句二首 二 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac86417f-9ce1-4b16-90c9-8bf7a14ee47c', '洛中監察病假滿送韋楚老拾遺歸朝', '洛中監察病假满送韋楚老拾遺归朝', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["洛橋風暖細翻衣，春引仙官去玉墀。","獨鶴初沖太虛日，九牛新落一毛時。","行開教化期君是，臥病神祇禱我知。","十載丈夫堪恥處，朱雲猶掉直言旗。"]', '["洛橋风暖細翻衣，春引仙官去玉墀。","独鹤初沖太虛日，九牛新落一毛时。","行开教化期君是，臥病神祇禱我知。","十載丈夫堪恥处，朱云猶掉直言旗。"]', '诗', 'shi', '', NULL, '洛中監察病假滿送韋楚老拾遺歸朝 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('763a05fa-d6c1-41a7-b11f-2e3bb9540ef5', '東都送鄭處誨校書歸上都', '东都送鄭处誨校书归上都', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["悠悠渠水清，雨霽洛陽城。","槿墮初開豔，蟬聞第一聲。","故人容易去，白髮等閑生。","此別無多語，期君晦盛名。"]', '["悠悠渠水清，雨霽洛陽城。","槿墮初开豔，蟬闻第一声。","故人容易去，白髮等闲生。","此別無多語，期君晦盛名。"]', '诗', 'shi', '', NULL, '東都送鄭處誨校書歸上都 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('643c46d6-1e3f-41f0-b78c-60df0400e496', '故洛陽城有感', '故洛陽城有感', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["一片宮牆當道危，行人爲爾去遲遲。","篳圭苑裏秋風後，平樂館前斜日時。","錮黨豈能留漢鼎，清談空解識胡兒。","千燒萬戰坤靈死，慘慘終年鳥雀悲。"]', '["一片宮牆當道危，行人爲爾去遲遲。","篳圭苑裏秋风後，平乐館前斜日时。","錮黨豈能留漢鼎，清談空解識胡兒。","千燒万戰坤靈死，慘慘終年鸟雀悲。"]', '诗', 'shi', '', NULL, '故洛陽城有感 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('554f48ec-69db-4890-96b5-7eaca5e6596e', '揚州三首 一', '揚州三首 一', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["煬帝雷塘土，迷藏有舊樓。","誰家唱水調，明月滿揚州。","駿馬宜閑出，千金好舊游。","喧闐醉年少，半脫紫茸裘。"]', '["煬帝雷塘土，迷藏有旧楼。","誰家唱水調，明月满揚州。","駿马宜闲出，千金好旧游。","喧闐醉年少，半脫紫茸裘。"]', '诗', 'shi', '', NULL, '揚州三首 一 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a75989ce-f97f-4abc-bc28-4463c888ccc7', '揚州三首 二', '揚州三首 二', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["秋風放螢苑，春草鬬雞臺。","金絡擎鵰去，鸞環拾翠來。","蜀船紅錦重，越橐水沈堆。","處處皆華表，淮王奈却回。"]', '["秋风放螢苑，春草鬬雞台。","金絡擎鵰去，鸾环拾翠来。","蜀船紅錦重，越橐水沈堆。","处处皆华表，淮王奈却回。"]', '诗', 'shi', '', NULL, '揚州三首 二 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c761c2ee-9b29-45a2-bdea-af11fa94f7c3', '揚州三首 三', '揚州三首 三', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["街垂千步柳，霞映兩重城。","天碧臺閣麗，風涼歌管清。","纖腰間長袖，玉珮雜繁纓。","拖軸誠爲壯，豪華不可名。","自是荒淫罪何妨作帝京。"]', '["街垂千步柳，霞映兩重城。","天碧台閣丽，风涼歌管清。","纖腰间长袖，玉珮杂繁纓。","拖軸誠爲壯，豪华不可名。","自是荒淫罪何妨作帝京。"]', '诗', 'shi', '', NULL, '揚州三首 三 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e659f21-993b-44be-9ceb-66d0a9d9206a', '潤州二首 一', '潤州二首 一', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["句吳亭東千里秋，放歌曾作昔年遊。","青苔寺裏無馬跡，綠水橋邊多酒樓。","大抵南朝皆曠達，可憐東晉最風流。","月明更想桓伊在，一笛聞吹出塞愁。"]', '["句吳亭东千里秋，放歌曾作昔年游。","青苔寺裏無马跡，綠水橋邊多酒楼。","大抵南朝皆曠達，可怜东晉最风流。","月明更想桓伊在，一笛闻吹出塞愁。"]', '诗', 'shi', '', NULL, '潤州二首 一 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34230058-6ff4-4ec3-b248-67e005ed9403', '潤州二首 二', '潤州二首 二', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["謝眺詩中佳麗地，夫差傳裏水犀軍。","城高鐵甕橫強弩，柳暗朱樓多夢雲。","畫角愛飄江北去，釣歌長向月中聞。","揚州塵土試回首，不惜千金借與君。"]', '["謝眺诗中佳丽地，夫差傳裏水犀軍。","城高鐵甕橫強弩，柳暗朱楼多梦云。","畫角愛飄江北去，釣歌长向月中闻。","揚州塵土試回首，不惜千金借與君。"]', '诗', 'shi', '', NULL, '潤州二首 二 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48c6fee4-fc95-4b0e-8107-6ec225e1b79d', '題揚州禪智寺', '題揚州禪智寺', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["雨過一蟬噪，飄蕭松桂秋。","青苔滿階砌，白鳥故遲留。","暮靄生深樹，斜陽下小樓。","誰知竹西路，歌吹是揚州。"]', '["雨過一蟬噪，飄蕭松桂秋。","青苔满階砌，白鸟故遲留。","暮靄生深樹，斜陽下小楼。","誰知竹西路，歌吹是揚州。"]', '诗', 'shi', '', NULL, '題揚州禪智寺 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32dad2e8-0db2-4828-8d23-9dbb828bab62', '西江懷古', '西江懷古', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["上吞巴漢控瀟湘，怒似連山淨鏡光。","魏帝縫囊真戲劇，苻堅投箠更荒唐。","千秋釣艇歌明月，萬里沙鷗弄夕陽。","範蠡清塵何寂寞，好風唯屬往來商。"]', '["上吞巴漢控瀟湘，怒似連山淨镜光。","魏帝縫囊真戲劇，苻堅投箠更荒唐。","千秋釣艇歌明月，万里沙鷗弄夕陽。","範蠡清塵何寂寞，好风唯屬往来商。"]', '诗', 'shi', '', NULL, '西江懷古 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40382e0d-b922-4c98-8ece-aa19d5185786', '江南懷古', '江南懷古', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["車書混一業無窮，井邑山川今古同。","戊辰年向金陵過，惆悵閑吟憶庾公。"]', '["车书混一業無窮，井邑山川今古同。","戊辰年向金陵過，惆悵闲吟憶庾公。"]', '诗', 'shi', '', NULL, '江南懷古 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1a23dad-694c-41a0-82b7-6a0ddde6d246', '江南春絕句', '江南春絕句', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["千里鶯啼綠映江，水村山郭酒旗風。","南朝四百八十寺，多少樓臺煙雨中。"]', '["千里鶯啼綠映江，水村山郭酒旗风。","南朝四百八十寺，多少楼台煙雨中。"]', '诗', 'shi', '', NULL, '江南春絕句 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b701d26-ca76-4bef-baa6-0498963a716c', '將赴宣州留題揚州禪智寺', '將赴宣州留題揚州禪智寺', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["故里溪頭松柏雙，來時盡日倚松窓。","杜陵隋苑已絕國，秋晚南遊更渡江。"]', '["故里溪头松柏雙，来时尽日倚松窓。","杜陵隋苑已絕国，秋晚南游更渡江。"]', '诗', 'shi', '', NULL, '將赴宣州留題揚州禪智寺 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd8f10d0-5751-4610-a901-550e74fb161b', '題宣州開元寺水閣閣下宛溪夾溪居人', '題宣州开元寺水閣閣下宛溪夾溪居人', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["六朝文物草連空，天淡雲閑今古同。","鳥去鳥來山色裏，人歌人哭水聲中。","深秋簾幕千家雨，落日樓臺一笛風。","惆悵無因見范蠡，參差煙樹五湖東。"]', '["六朝文物草連空，天淡云闲今古同。","鸟去鸟来山色裏，人歌人哭水声中。","深秋簾幕千家雨，落日楼台一笛风。","惆悵無因见范蠡，參差煙樹五湖东。"]', '诗', 'shi', '', NULL, '題宣州開元寺水閣閣下宛溪夾溪居人 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3e5a592-dc26-4cc9-a310-525f32b195f6', '宣州送裴坦判官往舒州時牧欲赴官歸京', '宣州送裴坦判官往舒州时牧欲赴官归京', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["日暖泥融雪半銷，行人芳草馬聲驕。","九華山路雲遮寺，清弋江村柳拂橋。","君意如鴻高的的，我心懸斾正搖搖。","同來不得同歸去，故國逢春一寂寥。"]', '["日暖泥融雪半銷，行人芳草马声驕。","九华山路云遮寺，清弋江村柳拂橋。","君意如鴻高的的，我心懸斾正搖搖。","同来不得同归去，故国逢春一寂寥。"]', '诗', 'shi', '', NULL, '宣州送裴坦判官往舒州時牧欲赴官歸京 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12781143-afe6-4a27-83bb-20307ff23ef7', '句溪夏日送盧霈秀才歸王屋山將欲赴舉', '句溪夏日送盧霈秀才归王屋山將欲赴舉', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["野店正紛泊，繭蠶初引絲。","行人碧溪渡，繫馬綠楊枝。","苒苒跡始去，悠悠心所期。","秋山念君別，惆悵桂花時。"]', '["野店正紛泊，繭蠶初引絲。","行人碧溪渡，繫马綠楊枝。","苒苒跡始去，悠悠心所期。","秋山念君別，惆悵桂花时。"]', '诗', 'shi', '', NULL, '句溪夏日送盧霈秀才歸王屋山將欲赴舉 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90d5325d-54e6-4dd0-a0e0-94a6fbb5eb57', '自宣城赴官上京', '自宣城赴官上京', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["瀟灑江湖十過秋，酒杯無日不淹留。","謝公城畔溪驚夢，蘇小門前柳拂頭。","千里雲山何處好，幾人襟韻一生休。","塵冠挂却知閑事，終擬蹉跎訪舊遊。"]', '["瀟灑江湖十過秋，酒杯無日不淹留。","謝公城畔溪驚梦，蘇小门前柳拂头。","千里云山何处好，幾人襟韻一生休。","塵冠挂却知闲事，終擬蹉跎訪旧游。"]', '诗', 'shi', '', NULL, '自宣城赴官上京 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e85a9e02-bf6d-45e8-b409-34d494901c16', '春末題池州弄水亭', '春末題池州弄水亭', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["使君四十四，兩佩左銅魚。","爲吏非循吏，論書讀底書。","晚花紅豔靜，高樹綠陰初。","亭宇清無比，溪山畫不如。","嘉賓能嘯詠，宮妓巧粧梳。","逐日愁皆碎，隨時醉有餘。","偃須求五鼎，陶秪愛吾廬。","趣向人皆異，賢豪莫笑渠。"]', '["使君四十四，兩佩左銅鱼。","爲吏非循吏，論书读底书。","晚花紅豔静，高樹綠陰初。","亭宇清無比，溪山畫不如。","嘉賓能嘯詠，宮妓巧粧梳。","逐日愁皆碎，隨时醉有餘。","偃須求五鼎，陶秪愛吾廬。","趣向人皆異，賢豪莫笑渠。"]', '诗', 'shi', '', NULL, '春末題池州弄水亭 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3aa3cf45-b634-4721-8c60-74b843904b43', '登池州九峰樓寄張祜', '登池州九峰楼寄張祜', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["百感中來不自由，角聲孤起夕陽樓。","碧山終日思無盡，芳草何年恨即休。","睫在眼前長不見，道非身外更何求。","誰人得似張公子，千首詩輕萬戶侯。"]', '["百感中来不自由，角声孤起夕陽楼。","碧山終日思無尽，芳草何年恨即休。","睫在眼前长不见，道非身外更何求。","誰人得似張公子，千首诗轻万戶侯。"]', '诗', 'shi', '', NULL, '登池州九峰樓寄張祜 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d24827d-f7c1-4b16-ba8b-1f3a84cbd455', '齊安郡晚秋', '齊安郡晚秋', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["柳岸風來影漸疎，使君家似野人居。","雲容水態還堪賞，嘯志歌懷亦自如。","雨暗殘燈碁散後，酒醒孤枕鴈來初。","可憐赤壁爭雄渡，唯有蓑翁坐釣魚。"]', '["柳岸风来影漸疎，使君家似野人居。","云容水態還堪賞，嘯志歌懷亦自如。","雨暗殘灯碁散後，酒醒孤枕鴈来初。","可怜赤壁爭雄渡，唯有蓑翁坐釣鱼。"]', '诗', 'shi', '', NULL, '齊安郡晚秋 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea5ac55c-1d02-43f9-a411-da4255d3c30f', '九日齊安登高', '九日齊安登高', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["江涵秋影鴈初飛，與客攜壺上翠微。","塵世難逢開口笑，菊花須插滿頭歸。","但將酩酊酬佳節，不用登臨歎落暉。","古往今來只如此，牛山何必淚霑衣。"]', '["江涵秋影鴈初飞，與客携壺上翠微。","塵世难逢开口笑，菊花須插满头归。","但將酩酊酬佳節，不用登臨歎落暉。","古往今来只如此，牛山何必泪霑衣。"]', '诗', 'shi', '', NULL, '九日齊安登高 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecd7e71b-cfeb-401a-9834-e971a6afc54e', '池州春送前進士蒯希逸', '池州春送前進士蒯希逸', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["芳草復芳草，斷腸還斷腸。","自然堪下淚，何必更殘陽。","楚岸千萬里，燕鴻三兩行。","有家歸不得，況舉別君觴。"]', '["芳草复芳草，斷腸還斷腸。","自然堪下泪，何必更殘陽。","楚岸千万里，燕鴻三兩行。","有家归不得，況舉別君觴。"]', '诗', 'shi', '', NULL, '池州春送前進士蒯希逸 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ba5ff8d-f653-4c16-ba3c-476a101f7d30', '齊安郡中偶題二首 一', '齊安郡中偶題二首 一', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["兩竿落日溪橋上，半縷輕煙柳影中。","多少綠荷相倚恨，一時回首背西風。"]', '["兩竿落日溪橋上，半縷轻煙柳影中。","多少綠荷相倚恨，一时回首背西风。"]', '诗', 'shi', '', NULL, '齊安郡中偶題二首 一 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a979e4fd-0abe-4078-9f0c-a5a58b63fd80', '齊安郡中偶題二首 二', '齊安郡中偶題二首 二', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["秋聲無不攪離心，夢澤蒹葭楚雨深。","自滴階前大梧葉，干君何事動哀吟。"]', '["秋声無不攪離心，梦澤蒹葭楚雨深。","自滴階前大梧葉，干君何事动哀吟。"]', '诗', 'shi', '', NULL, '齊安郡中偶題二首 二 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7025f2b-f037-447d-9cbf-444588fd4934', '齊安郡後池絕句', '齊安郡後池絕句', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["菱透浮萍綠錦池，夏鶯千囀弄薔薇。","盡日無人看微雨，鴛鴦相對浴紅衣。"]', '["菱透浮萍綠錦池，夏鶯千囀弄薔薇。","尽日無人看微雨，鴛鴦相对浴紅衣。"]', '诗', 'shi', '', NULL, '齊安郡後池絕句 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51793720-6e73-4dc2-b4ad-e20b4439b612', '題齊安城樓', '題齊安城楼', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["嗚咽江樓角一聲，微陽瀲瀲落寒汀。","不用憑闌苦回首，故鄉七十五長亭。"]', '["嗚咽江楼角一声，微陽瀲瀲落寒汀。","不用憑闌苦回首，故乡七十五长亭。"]', '诗', 'shi', '', NULL, '題齊安城樓 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be60d3de-6077-4525-aafc-bcaaee8e7a79', '池州李使君沒後十一日處州新命始到後見歸妓感而成詩', '池州李使君沒後十一日处州新命始到後见归妓感而成诗', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["縉雲新命詔初行，纔是孤魂壽器成。","黃壤不知新雨露，粉書空換舊銘旌。","巨卿哭處雲空斷，阿騖歸來月正明。","多少四年遺愛事，鄉閭生子李爲名。"]', '["縉云新命詔初行，纔是孤魂壽器成。","黄壤不知新雨露，粉书空換旧銘旌。","巨卿哭处云空斷，阿騖归来月正明。","多少四年遺愛事，乡閭生子李爲名。"]', '诗', 'shi', '', NULL, '池州李使君沒後十一日處州新命始到後見歸妓感而成詩 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ba882ca-87ba-4f85-840f-999b3ae3563b', '見劉秀才與池州妓別', '见劉秀才與池州妓別', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["遠風南浦萬重波，未似生離別恨多。","楚管能吹柳花怨，吳姬爭唱竹枝歌。","金釵橫處綠雲墮，玉筯凝時紅粉和。","待得枚臯相見日，自應粧鏡笑蹉跎。"]', '["远风南浦万重波，未似生離別恨多。","楚管能吹柳花怨，吳姬爭唱竹枝歌。","金釵橫处綠云墮，玉筯凝时紅粉和。","待得枚臯相见日，自應粧镜笑蹉跎。"]', '诗', 'shi', '', NULL, '見劉秀才與池州妓別 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dc42ceb-2ad5-4fd4-a3ec-fb7066096802', '池州廢林泉寺', '池州廢林泉寺', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["廢寺林溪上，頹垣倚亂峰。","看棲歸樹鳥，猶想過山鐘。","石路尋僧去，此生應不逢。"]', '["廢寺林溪上，頹垣倚亂峰。","看棲归樹鸟，猶想過山鐘。","石路尋僧去，此生應不逢。"]', '诗', 'shi', '', NULL, '池州廢林泉寺 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a9d70a4-570b-4972-b7c1-e4bd395ae81b', '憶齊安郡', '憶齊安郡', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["平生睡足處，雲夢澤南州。","一夜風欺竹，連江雨送秋。","格卑常汩汩，力學強悠悠。","終掉塵中手，瀟湘釣漫流。"]', '["平生睡足处，云梦澤南州。","一夜风欺竹，連江雨送秋。","格卑常汩汩，力学強悠悠。","終掉塵中手，瀟湘釣漫流。"]', '诗', 'shi', '', NULL, '憶齊安郡 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('022a3d00-b611-43eb-a8de-0708716ce025', '池州清溪', '池州清溪', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["弄溪終日到黃昏，照數秋來白髮根。","何物賴君千遍洗，筆頭塵土漸無痕。"]', '["弄溪終日到黄昏，照數秋来白髮根。","何物賴君千遍洗，笔头塵土漸無痕。"]', '诗', 'shi', '', NULL, '池州清溪 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b86db95b-15ac-4d37-a2ec-682f9ea6fd06', '遊池州林泉寺金碧洞', '游池州林泉寺金碧洞', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["袖拂霜林下石稜，潺湲聲斷滿溪冰。","攜茶臘月遊金碧，合有文章病茂陵。"]', '["袖拂霜林下石稜，潺湲声斷满溪冰。","携茶臘月游金碧，合有文章病茂陵。"]', '诗', 'shi', '', NULL, '遊池州林泉寺金碧洞 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57fcc29a-3136-4a89-b306-54bf8e30438c', '即事', '即事', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["因思上黨三年戰，閑詠周公七月詩。","竹帛未聞書死節，丹青空見畫靈旗。","蕭條井邑如魚尾，早晚干戈識虎皮。","莫笑一麾東下計，滿江秋浪碧參差。"]', '["因思上黨三年戰，闲詠周公七月诗。","竹帛未闻书死節，丹青空见畫靈旗。","蕭條井邑如鱼尾，早晚干戈識虎皮。","莫笑一麾东下計，满江秋浪碧參差。"]', '诗', 'shi', '', NULL, '即事 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b237f5d-d5e7-4298-8ba1-56a2df082f8d', '贈李秀才', '贈李秀才', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["骨清年少眼如冰，鳳羽參差五色層。","天上麒麟時一下，人間不獨有徐陵。"]', '["骨清年少眼如冰，鳳羽參差五色層。","天上麒麟时一下，人间不独有徐陵。"]', '诗', 'shi', '', NULL, '贈李秀才 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3afc8229-82f7-4ff9-a0de-5ddeb0f88631', '寄李起居四韻', '寄李起居四韻', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["楚女梅簪白雪姿，前溪碧水凍醪時。","雲罍心凸知難捧，鳳管簧寒不受吹。","南國劒眸能盼眄，侍臣香袖愛僛垂。","自憐窮律窮途客，正怯孤燈一局碁。"]', '["楚女梅簪白雪姿，前溪碧水凍醪时。","云罍心凸知难捧，鳳管簧寒不受吹。","南国劒眸能盼眄，侍臣香袖愛僛垂。","自怜窮律窮途客，正怯孤灯一局碁。"]', '诗', 'shi', '', NULL, '寄李起居四韻 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a9216fd-4030-4bef-8072-e593ff72a1b5', '題池州貴池亭', '題池州貴池亭', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["勢比凌歊宋武臺，分明百里遠帆開。","蜀江雪浪西江滿，強半春寒去却來。"]', '["勢比凌歊宋武台，分明百里远帆开。","蜀江雪浪西江满，強半春寒去却来。"]', '诗', 'shi', '', NULL, '題池州貴池亭 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cf8ea1f-34fd-4ef0-abf2-00d8bf91091c', '蘭溪', '蘭溪', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["蘭溪春盡碧泱泱，映水蘭花雨發香。","楚國大夫憔悴日，應尋此路去瀟湘。"]', '["蘭溪春尽碧泱泱，映水蘭花雨發香。","楚国大夫憔悴日，應尋此路去瀟湘。"]', '诗', 'shi', '', NULL, '蘭溪 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e005cd58-79a0-440d-8626-727ce5328c29', '睦州四韻', '睦州四韻', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["州在釣臺邊，溪山實可憐。","有家皆掩映，無處不潺湲。","好樹鳴幽鳥，晴樓入野煙。","殘春杜陵客，中酒落花前。"]', '["州在釣台邊，溪山實可怜。","有家皆掩映，無处不潺湲。","好樹鳴幽鸟，晴楼入野煙。","殘春杜陵客，中酒落花前。"]', '诗', 'shi', '', NULL, '睦州四韻 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2703ed11-ada5-4fa4-9904-22dd1b1821a2', '秋晚早發新定', '秋晚早發新定', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["解印書千軸，重陽酒百缸。","涼風滿紅樹，曉月下秋江。","巖壑會歸去，塵埃終不降。","懸纓未敢濯，嚴瀨碧淙淙。"]', '["解印书千軸，重陽酒百缸。","涼风满紅樹，晓月下秋江。","巖壑會归去，塵埃終不降。","懸纓未敢濯，嚴瀨碧淙淙。"]', '诗', 'shi', '', NULL, '秋晚早發新定 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e3688e7-0bc4-4297-9b41-98b3f014a88c', '除官歸京睦州雨霽', '除官归京睦州雨霽', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["秋半吳天霽，清凝萬里光。","水聲侵笑語，嵐翠撲衣裳。","遠樹疑羅帳，孤雲認粉囊。","溪山侵兩越，時節到重陽。","顧我能甘賤，無由得自強。","悮曾公觸尾，不敢夜循墻。","豈意籠飛鳥，還爲錦帳郎。","網今開傅燮，書舊識黃香。","姹女真虛語，飢兒欲一行。","淺深須揭厲，休更學張綱。"]', '["秋半吳天霽，清凝万里光。","水声侵笑語，嵐翠撲衣裳。","远樹疑羅帳，孤云認粉囊。","溪山侵兩越，时節到重陽。","顧我能甘賤，無由得自強。","悮曾公觸尾，不敢夜循墻。","豈意籠飞鸟，還爲錦帳郎。","網今开傅燮，书旧識黄香。","姹女真虛語，飢兒欲一行。","淺深須揭厲，休更学張綱。"]', '诗', 'shi', '', NULL, '除官歸京睦州雨霽 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a7216cc-6181-4bd8-a2e7-5d68d6edc287', '夜泊桐廬先寄蘇臺盧郎中', '夜泊桐廬先寄蘇台盧郎中', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["水檻桐廬館，歸舟繫石根。","笛吹孤戌月，犬吠隔溪村。","十載違清裁，幽懷未一論。"]', '["水檻桐廬館，归舟繫石根。","笛吹孤戌月，犬吠隔溪村。","十載違清裁，幽懷未一論。"]', '诗', 'shi', '', NULL, '夜泊桐廬先寄蘇臺盧郎中 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('906890ad-278f-4252-be3f-405b809a4178', '新轉南曹未敘朝散初秋暑退出守吳興書此篇以自見志', '新轉南曹未敘朝散初秋暑退出守吳兴书此篇以自见志', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["捧詔汀洲去，全家羽翼飛。","喜拋新錦帳，榮借舊朱衣。","且免材爲累，何妨拙有機。","宋株聊自守，魯酒怕旁圍。","清尚寧無素，光陰亦未晞。","一盃寬幕席，五字弄珠璣。","越浦黃柑嫩，吳溪紫蟹肥。","平生江海志，佩得左魚歸。"]', '["捧詔汀洲去，全家羽翼飞。","喜拋新錦帳，榮借旧朱衣。","且免材爲累，何妨拙有機。","宋株聊自守，魯酒怕旁圍。","清尚寧無素，光陰亦未晞。","一盃寬幕席，五字弄珠璣。","越浦黄柑嫩，吳溪紫蟹肥。","平生江海志，佩得左鱼归。"]', '诗', 'shi', '', NULL, '新轉南曹未敘朝散初秋暑退出守吳興書此篇以自見志 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1bd16df-e065-48cd-855a-25d67663cdfb', '題白蘋洲', '題白蘋洲', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["山鳥飛紅帶，亭薇拆紫花。","溪光初透徹，秋色正清華。","靜處知生樂，喧中見死誇。","無多珪組累，終不負煙霞。"]', '["山鸟飞紅带，亭薇拆紫花。","溪光初透徹，秋色正清华。","静处知生乐，喧中见死誇。","無多珪組累，終不負煙霞。"]', '诗', 'shi', '', NULL, '題白蘋洲 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e19012a-a57f-4e53-ae4f-40a3b4303db2', '題茶山', '題茶山', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["山實東吳秀，茶稱瑞草魁。","剖符雖俗吏，修貢亦仙才。","溪盡停蠻櫂，旗張卓翠苔。","柳村穿窈窕，松澗渡喧豗。","等級雲峰峻，寬平洞府開。","拂天聞笑語，特地見樓臺。","泉嫩黃金湧，牙香紫璧裁。","拜章期沃日，輕騎疾奔雷。","舞袖嵐侵澗，歌聲谷答回。","磬音藏葉鳥，雪豔照潭梅。","好是全家到，兼爲奉詔來。","樹陰香作帳，花徑落成堆。","景物殘三月，登臨愴一盃。","重遊難自尅，俛首入塵埃。"]', '["山實东吳秀，茶稱瑞草魁。","剖符雖俗吏，修貢亦仙才。","溪尽停蠻櫂，旗張卓翠苔。","柳村穿窈窕，松澗渡喧豗。","等級云峰峻，寬平洞府开。","拂天闻笑語，特地见楼台。","泉嫩黄金湧，牙香紫璧裁。","拜章期沃日，轻騎疾奔雷。","舞袖嵐侵澗，歌声谷答回。","磬音藏葉鸟，雪豔照潭梅。","好是全家到，兼爲奉詔来。","樹陰香作帳，花徑落成堆。","景物殘三月，登臨愴一盃。","重游难自尅，俛首入塵埃。"]', '诗', 'shi', '', NULL, '題茶山 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da21588d-5e04-4707-a084-696ba5120669', '茶山下作', '茶山下作', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["春風最窈窕，日曉柳村西。","嬌雲光占岫，健水鳴分溪。","燎巖野花遠，戛瑟幽鳥啼。","把酒坐芳草，亦有佳人攜。"]', '["春风最窈窕，日晓柳村西。","嬌云光占岫，健水鳴分溪。","燎巖野花远，戛瑟幽鸟啼。","把酒坐芳草，亦有佳人携。"]', '诗', 'shi', '', NULL, '茶山下作 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f540523d-6bde-433c-87d5-e1929f04bcbd', '入茶山下題水口草市絕句', '入茶山下題水口草市絕句', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["倚溪侵嶺多高樹，誇酒書旗有小樓。","驚起鴛鴦豈無恨，一雙飛去却回頭。"]', '["倚溪侵嶺多高樹，誇酒书旗有小楼。","驚起鴛鴦豈無恨，一雙飞去却回头。"]', '诗', 'shi', '', NULL, '入茶山下題水口草市絕句 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c5abe03-8a94-43d1-b340-e25aa1f83fc6', '春日茶山病不飲酒因呈賓客', '春日茶山病不饮酒因呈賓客', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["笙歌登畫船，十日清明前。","山秀白雲膩，溪光紅粉鮮。","欲開未開花，半陰半晴天。","誰知病太守，猶得作茶仙。"]', '["笙歌登畫船，十日清明前。","山秀白云膩，溪光紅粉鲜。","欲开未开花，半陰半晴天。","誰知病太守，猶得作茶仙。"]', '诗', 'shi', '', NULL, '春日茶山病不飲酒因呈賓客 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01746278-f392-4ef2-b743-f04920747aec', '不飲贈官妓', '不饮贈官妓', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["芳草正得意，汀洲日欲西。","無端千樹柳，更拂一條溪。","幾朵梅堪折，何人手好攜。","誰憐佳麗地，春恨却悽悽。"]', '["芳草正得意，汀洲日欲西。","無端千樹柳，更拂一條溪。","幾朵梅堪折，何人手好携。","誰怜佳丽地，春恨却悽悽。"]', '诗', 'shi', '', NULL, '不飲贈官妓 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3adfc13-1050-4049-8cb4-4355e2b0256f', '早春贈軍事薛判官', '早春贈軍事薛判官', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["雪後新正半，春來四刻長。","晴梅朱粉豔，嫩水碧羅光。","弦管開雙調，花鈿坐兩行。","唯君莫惜醉，認取少年場。"]', '["雪後新正半，春来四刻长。","晴梅朱粉豔，嫩水碧羅光。","弦管开雙調，花鈿坐兩行。","唯君莫惜醉，認取少年場。"]', '诗', 'shi', '', NULL, '早春贈軍事薛判官 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44f95de1-e861-45ce-af4e-cc4443bb5d7c', '代吳興妓春初寄薛軍事', '代吳兴妓春初寄薛軍事', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["霧冷侵紅粉，春陰撲翠鈿。","自悲臨曉鏡，誰與惜流年。","柳暗霏微雨，花愁黯淡天。","金釵有幾隻，抽當酒家錢。"]', '["霧冷侵紅粉，春陰撲翠鈿。","自悲臨晓镜，誰與惜流年。","柳暗霏微雨，花愁黯淡天。","金釵有幾隻，抽當酒家錢。"]', '诗', 'shi', '', NULL, '代吳興妓春初寄薛軍事 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3407eba-d066-4e2e-903f-1af94e886ab7', '八月十二日得替後移居霅溪館因題長句四韻', '八月十二日得替後移居霅溪館因題长句四韻', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["萬家相慶喜秋成，處處樓臺歌板聲。","千歲鶴歸猶有恨，一年人住豈無情。","夜涼溪館留僧話，風定蘇潭看月生。","景物登臨閑始見，願爲閑客此閑行。"]', '["万家相慶喜秋成，处处楼台歌板声。","千歲鹤归猶有恨，一年人住豈無情。","夜涼溪館留僧話，风定蘇潭看月生。","景物登臨闲始见，願爲闲客此闲行。"]', '诗', 'shi', '', NULL, '八月十二日得替後移居霅溪館因題長句四韻 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dadb8a20-904f-451c-a2ff-90add19d8976', '初冬夜飲', '初冬夜饮', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["淮陽多病偶求歡，客袖侵霜與燭盤。","砌下梨花一堆雪，明年誰此凭闌干。"]', '["淮陽多病偶求歡，客袖侵霜與燭盤。","砌下梨花一堆雪，明年誰此凭闌干。"]', '诗', 'shi', '', NULL, '初冬夜飲 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('767881fd-3732-4255-a091-2408754395d1', '栽竹', '栽竹', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["本因遮日種，却似爲溪移。","歷歷羽林影，疎疎煙露姿。","蕭騷寒雨夜，敲劼晚風時。","故國何年到，塵冠挂一枝。"]', '["本因遮日種，却似爲溪移。","歷歷羽林影，疎疎煙露姿。","蕭騷寒雨夜，敲劼晚风时。","故国何年到，塵冠挂一枝。"]', '诗', 'shi', '', NULL, '栽竹 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('273c54cd-db27-4ede-9b96-4412483aab04', '梅', '梅', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["輕盈照溪水，掩斂下瑤臺。","妬雪聊相比，欺春不逐來。","偶同佳客見，似爲凍醪開。","若在秦樓畔，堪爲弄玉媒。"]', '["轻盈照溪水，掩斂下瑤台。","妬雪聊相比，欺春不逐来。","偶同佳客见，似爲凍醪开。","若在秦楼畔，堪爲弄玉媒。"]', '诗', 'shi', '', NULL, '梅 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cbf46c5-1136-49a5-954d-22408a0d96df', '山石榴', '山石榴', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["似火山榴映小山，繁中能薄豔中閑。","一朵佳人玉釵上，秪疑燒却翠雲鬟。"]', '["似火山榴映小山，繁中能薄豔中闲。","一朵佳人玉釵上，秪疑燒却翠云鬟。"]', '诗', 'shi', '', NULL, '山石榴 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc24cf38-f6e8-456b-9ca0-5deaf9ca640e', '柳長句', '柳长句', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["日落水流西復東，春光不盡柳何窮。","巫娥廟裏低含雨，宋玉宅前斜帶風。","不嫌榆莢共爭翠，深與桃花相映紅。","灞上漢南千萬樹，幾人遊宦別離中。"]', '["日落水流西复东，春光不尽柳何窮。","巫娥廟裏低含雨，宋玉宅前斜带风。","不嫌榆莢共爭翠，深與桃花相映紅。","灞上漢南千万樹，幾人游宦別離中。"]', '诗', 'shi', '', NULL, '柳長句 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3e578a1-2ab6-4397-b2ff-a9d27f8568a3', '隋堤柳', '隋堤柳', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["夾岸垂楊三百里，秪應圖畫最相宜。","自嫌流落西歸疾，不見東風二月時。"]', '["夾岸垂楊三百里，秪應圖畫最相宜。","自嫌流落西归疾，不见东风二月时。"]', '诗', 'shi', '', NULL, '隋堤柳 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00430c53-2891-4917-ba7c-5cccc0dcf9b0', '柳絕句', '柳絕句', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["數樹新開翠影齊，倚風情態被春迷。","依依故國樊川恨，半掩村橋半掩溪。"]', '["數樹新开翠影齊，倚风情態被春迷。","依依故国樊川恨，半掩村橋半掩溪。"]', '诗', 'shi', '', NULL, '柳絕句 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab6eb2e3-96e6-49bc-ad2c-c70fe0fe889d', '獨柳', '独柳', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["含煙一株柳，拂地搖風久。","佳人不忍折，悵望回纖手。"]', '["含煙一株柳，拂地搖风久。","佳人不忍折，悵望回纖手。"]', '诗', 'shi', '', NULL, '獨柳 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ee69d68-c50d-4a8e-9125-9ce8b90e38de', '早鴈', '早鴈', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["金河秋半虜弦開，雲外驚飛四散哀。","仙掌月明孤影過，長門燈暗數聲來。","須知胡騎紛紛在，豈逐春風一一回。","莫厭瀟湘少人處，水多菰米岸莓苔。"]', '["金河秋半虜弦开，云外驚飞四散哀。","仙掌月明孤影過，长门灯暗數声来。","須知胡騎紛紛在，豈逐春风一一回。","莫厭瀟湘少人处，水多菰米岸莓苔。"]', '诗', 'shi', '', NULL, '早鴈 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b755806f-5908-4013-9635-f35b5e4d7514', '鵁鶄', '鵁鶄', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["芝莖抽紺趾，清唳擲金梭。","日翅閑張錦，風池去罥羅。","靜眠依翠荇，暖戲折高荷。","山陰豈無爾，繭字換羣鵝。"]', '["芝莖抽紺趾，清唳擲金梭。","日翅闲張錦，风池去罥羅。","静眠依翠荇，暖戲折高荷。","山陰豈無爾，繭字換羣鵝。"]', '诗', 'shi', '', NULL, '鵁鶄 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9bff166-bad3-4e2f-8e9a-3b3dab4c99cd', '鸚鵡', '鸚鵡', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["華堂日漸高，雕檻繫紅縚。","故國隴山樹，美人金剪刀。","避籠交翠尾，罅嘴靜新毛。","不念三緘事，世途皆爾曹。"]', '["华堂日漸高，雕檻繫紅縚。","故国隴山樹，美人金剪刀。","避籠交翠尾，罅嘴静新毛。","不念三緘事，世途皆爾曹。"]', '诗', 'shi', '', NULL, '鸚鵡 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d77c98b5-c087-448d-aa25-0abf916df46b', '鶴', '鹤', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["清音迎曉月，愁思立寒蒲。","丹頂西施頰，霜毛四皓鬚。","碧雲行止躁，白鷺性靈麤。","終日無群伴，溪邊弔影孤。"]', '["清音迎晓月，愁思立寒蒲。","丹頂西施頰，霜毛四皓鬚。","碧云行止躁，白鷺性靈麤。","終日無群伴，溪邊弔影孤。"]', '诗', 'shi', '', NULL, '鶴 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79dfd992-325b-4f0d-88fb-41af329b14c9', '鴉', '鴉', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["擾擾復翻翻，黃昏颺冷煙。","毛欺皇后髪，聲感楚姬弦。","蔓壘盤風下，霜林接翅眠。","秪如西旅樣，頭白豈無緣。"]', '["擾擾复翻翻，黄昏颺冷煙。","毛欺皇后髪，声感楚姬弦。","蔓壘盤风下，霜林接翅眠。","秪如西旅樣，头白豈無緣。"]', '诗', 'shi', '', NULL, '鴉 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db60ce28-affd-4810-90aa-0937eba12898', '鷺鷥', '鷺鷥', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["雪衣雪髪青玉觜，羣捕魚兒溪影中。","驚飛遠映碧山去，一樹梨花落晚風。"]', '["雪衣雪髪青玉觜，羣捕鱼兒溪影中。","驚飞远映碧山去，一樹梨花落晚风。"]', '诗', 'shi', '', NULL, '鷺鷥 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ae31638-4d94-433c-94f4-dbe0a936dd67', '村舍燕', '村舍燕', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["漢宮一百四十五，多下珠簾閉瑣窓。","何處營巢夏將半，茅簷煙裏語雙雙。"]', '["漢宮一百四十五，多下珠簾閉瑣窓。","何处營巢夏將半，茅簷煙裏語雙雙。"]', '诗', 'shi', '', NULL, '村舍燕 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3350ad48-ab27-410c-a204-4e223a6a457a', '歸燕', '归燕', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["畫堂歌舞喧喧地，社去社來人不看。","長是江樓使君伴，黃昏猶待倚闌干。"]', '["畫堂歌舞喧喧地，社去社来人不看。","长是江楼使君伴，黄昏猶待倚闌干。"]', '诗', 'shi', '', NULL, '歸燕 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('511e17d0-14fe-4303-8bca-c2544eb84a25', '傷猨', '傷猨', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["獨折南園一朵梅，重尋幽坎已生苔。","無端晚吹驚高樹，似裊長枝欲下來。"]', '["独折南园一朵梅，重尋幽坎已生苔。","無端晚吹驚高樹，似裊长枝欲下来。"]', '诗', 'shi', '', NULL, '傷猨 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc695811-2ff0-4ea9-a0ed-c593fc3a218f', '還俗老僧', '還俗老僧', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["雪髪不長寸，秋寒力更微。","獨尋一徑葉，猶挈衲殘衣。","日暮千峰裏，不知何處歸。"]', '["雪髪不长寸，秋寒力更微。","独尋一徑葉，猶挈衲殘衣。","日暮千峰裏，不知何处归。"]', '诗', 'shi', '', NULL, '還俗老僧 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b8eb5bd-f6d7-4629-92c7-12d73573c0d1', '斫竹', '斫竹', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["寺廢竹色死，宦家寧爾留。","霜根漸隨斧，風玉尚敲秋。"]', '["寺廢竹色死，宦家寧爾留。","霜根漸隨斧，风玉尚敲秋。"]', '诗', 'shi', '', NULL, '斫竹 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95bf4642-3062-48e0-a1fd-cc8505d63998', '將赴湖州留題亭菊', '將赴湖州留題亭菊', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["陶菊手自種，楚蘭心有期。","遙知渡江日，正是擷芳時。"]', '["陶菊手自種，楚蘭心有期。","遙知渡江日，正是擷芳时。"]', '诗', 'shi', '', NULL, '將赴湖州留題亭菊 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aeb383ee-1d05-4d4c-a662-dcb83fb07284', '折菊', '折菊', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["籬東菊徑深，折得自孤吟。","雨中衣半濕，擁鼻自知心。"]', '["籬东菊徑深，折得自孤吟。","雨中衣半濕，擁鼻自知心。"]', '诗', 'shi', '', NULL, '折菊 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efa43677-f926-4a14-a837-0a330c0a9fdd', '雲', '云', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["盡日看雲首不回，無心都大似無才。","可憐光彩一片玉，萬里晴天何處來。"]', '["尽日看云首不回，無心都大似無才。","可怜光彩一片玉，万里晴天何处来。"]', '诗', 'shi', '', NULL, '雲 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('519c3422-7504-4293-9a27-73c83c1ac1ec', '醉後題僧院', '醉後題僧院', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["離心忽忽復悽悽，雨晦傾瓶取醉泥。","可羨高僧共心語，一如攜穉往東西。"]', '["離心忽忽复悽悽，雨晦傾瓶取醉泥。","可羨高僧共心語，一如携穉往东西。"]', '诗', 'shi', '', NULL, '醉後題僧院 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4a297e3-7f61-4691-9435-589af58c5b75', '題禪院', '題禪院', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["觥船一櫂百分空，十歲青春不負公。","今日鬢絲禪榻畔，茶煙輕颺落花風。"]', '["觥船一櫂百分空，十歲青春不負公。","今日鬢絲禪榻畔，茶煙轻颺落花风。"]', '诗', 'shi', '', NULL, '題禪院 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a18f0079-46d6-4a55-ac4c-420df4b9fc92', '哭李給事中敏', '哭李給事中敏', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["陽陵郭門外，陂陁丈五墳。","九泉如結友，茲地好埋君。"]', '["陽陵郭门外，陂陁丈五墳。","九泉如結友，茲地好埋君。"]', '诗', 'shi', '', NULL, '哭李給事中敏 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33d6f968-bc8f-4eae-9ea8-09a8b7e0d665', '黃州竹徑鬬', '黄州竹徑鬬', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["竹濁蟠小徑，屈折鬬蛇來。","三年得歸去，知遶幾千回。"]', '["竹濁蟠小徑，屈折鬬蛇来。","三年得归去，知遶幾千回。"]', '诗', 'shi', '', NULL, '黃州竹徑鬬 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4f3ad55-7782-4654-91dd-5246a4a0eed8', '題敬愛寺樓', '題敬愛寺楼', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["暮景千山雪，春寒百尺樓。","獨登還獨下，誰會我悠悠。"]', '["暮景千山雪，春寒百尺楼。","独登還独下，誰會我悠悠。"]', '诗', 'shi', '', NULL, '題敬愛寺樓 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad0752ec-4d39-4e7a-b4a0-5316996c1c81', '送劉秀才歸江陵', '送劉秀才归江陵', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["綵服鮮華覲渚宮，鱸魚新熟別江東。","劉郎浦夜侵船月，宋玉亭春弄袖風。","落落精神終有立，飄飄才思杳無窮。","誰人世上爲金口，借取明時一薦雄。"]', '["綵服鲜华覲渚宮，鱸鱼新熟別江东。","劉郎浦夜侵船月，宋玉亭春弄袖风。","落落精神終有立，飄飄才思杳無窮。","誰人世上爲金口，借取明时一薦雄。"]', '诗', 'shi', '', NULL, '送劉秀才歸江陵 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b31e0478-a723-4a99-aaa9-4e645bd2604a', '見吳秀才與池妓別因成絕句', '见吳秀才與池妓別因成絕句', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["紅燭短時羌笛怨，清歌咽處蜀弦高。","萬里分飛兩行淚，滿江寒雨正蕭騷。"]', '["紅燭短时羌笛怨，清歌咽处蜀弦高。","万里分飞兩行泪，满江寒雨正蕭騷。"]', '诗', 'shi', '', NULL, '見吳秀才與池妓別因成絕句 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2090e1eb-ae03-4fc6-a227-2d96318191d5', '湖南正初招李郢秀才', '湖南正初招李郢秀才', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["行樂及時時已晚，對酒當歌歌不成。","千里暮山重疊翠，一溪寒水淺深情。","高人以飲爲忙事，浮世除詩盡強名。","看著白蘋芽欲吐，雪舟相訪勝閑行。"]', '["行乐及时时已晚，对酒當歌歌不成。","千里暮山重叠翠，一溪寒水淺深情。","高人以饮爲忙事，浮世除诗尽強名。","看著白蘋芽欲吐，雪舟相訪勝闲行。"]', '诗', 'shi', '', NULL, '湖南正初招李郢秀才 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23a44d51-2452-4472-924f-20bd7f7b910e', '贈朱道靈', '贈朱道靈', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["劉根丹篆三千字，郭璞青囊兩卷書。","牛渚磯南謝山北，白雲深處有巖居。"]', '["劉根丹篆三千字，郭璞青囊兩卷书。","牛渚磯南謝山北，白云深处有巖居。"]', '诗', 'shi', '', NULL, '贈朱道靈 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8092ed18-a644-4244-b6c0-7fe47070d8eb', '屏風絕句', '屏风絕句', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["屏風周昉畫纖腰，歲久丹青色半銷。","斜倚玉窓鸞髪女，拂塵猶自妬嬌嬈。"]', '["屏风周昉畫纖腰，歲久丹青色半銷。","斜倚玉窓鸾髪女，拂塵猶自妬嬌嬈。"]', '诗', 'shi', '', NULL, '屏風絕句 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d759ee6d-b24e-4fc3-8675-7c33e25f5ced', '哭韓綽', '哭韓綽', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["平明送葬上都門，紼翣交橫逐去魂。","歸來冷笑悲身事，喚婦呼兒索酒盆。"]', '["平明送葬上都门，紼翣交橫逐去魂。","归来冷笑悲身事，喚婦呼兒索酒盆。"]', '诗', 'shi', '', NULL, '哭韓綽 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e6221b3-e5bf-40ac-855b-d9625beb5364', '新定途中', '新定途中', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["無端偶效張文紀，下杜鄉園別五秋。","重過江南更千里，萬山深處一孤舟。"]', '["無端偶效張文紀，下杜乡园別五秋。","重過江南更千里，万山深处一孤舟。"]', '诗', 'shi', '', NULL, '新定途中 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c40fa2c-8faf-421d-be74-8b9da907fc55', '題新定八松院小石', '題新定八松院小石', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["雨滴珠璣碎，苔生紫翠重。","故關何日到，且看小三峰。"]', '["雨滴珠璣碎，苔生紫翠重。","故关何日到，且看小三峰。"]', '诗', 'shi', '', NULL, '題新定八松院小石 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfbe8c22-538d-45df-8fc6-07d527e6bc8b', '往年隨故府吳興公夜泊蕪湖口今赴官西去再宿蕪湖感舊傷懷因成十六韻', '往年隨故府吳兴公夜泊蕪湖口今赴官西去再宿蕪湖感旧傷懷因成十六韻', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["南指陵陽路，東流似昔年。","重恩山未答，雙鬢雪飄然。","數仞慙投跡，群公愧拍肩。","駑駘蒙錦繡，塵土浴潺湲。","郭隗黃金峻，虞卿白璧鮮。","貔貅環玉帳，鸚鵡破蠻牋。","極浦沈碑會，秋花落帽筵。","旌旗明迥野，冠珮照神仙。","籌畫言何補，優容道實全。","謳謠人撲地，雞犬樹連天。","紫鳳超如電，青襟散似煙。","蒼生未經濟，墳草已芊綿。","往事惟沙月，孤燈但客船。","峴山雲影畔，棠葉水聲前。","故國還歸去，浮生亦可憐。","高歌一曲淚，明日夕陽邊。"]', '["南指陵陽路，东流似昔年。","重恩山未答，雙鬢雪飄然。","數仞慙投跡，群公愧拍肩。","駑駘蒙錦繡，塵土浴潺湲。","郭隗黄金峻，虞卿白璧鲜。","貔貅环玉帳，鸚鵡破蠻牋。","極浦沈碑會，秋花落帽筵。","旌旗明迥野，冠珮照神仙。","籌畫言何補，優容道實全。","謳謠人撲地，雞犬樹連天。","紫鳳超如電，青襟散似煙。","蒼生未經濟，墳草已芊綿。","往事惟沙月，孤灯但客船。","峴山云影畔，棠葉水声前。","故国還归去，浮生亦可怜。","高歌一曲泪，明日夕陽邊。"]', '诗', 'shi', '', NULL, '往年隨故府吳興公夜泊蕪湖口今赴官西去再宿蕪湖感舊傷懷因成十六韻 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bd8c40c-eac0-46ac-969e-a9dcd3382323', '懷鍾陵舊遊四首 一', '懷鍾陵旧游四首 一', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["一謁征南最少年，虞卿雙璧截肪鮮。","歌謠千里春長暖，絲管高臺月正圓。","玉帳軍籌羅俊彥，絳帷環珮立神仙。","陸公餘德機雲在，如我酬恩合執鞭。"]', '["一謁征南最少年，虞卿雙璧截肪鲜。","歌謠千里春长暖，絲管高台月正圓。","玉帳軍籌羅俊彥，絳帷环珮立神仙。","陸公餘德機云在，如我酬恩合執鞭。"]', '诗', 'shi', '', NULL, '懷鍾陵舊遊四首 一 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86500cf0-f0a0-4a79-893e-6bedd71460ee', '懷鍾陵舊遊四首 二', '懷鍾陵旧游四首 二', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["滕閣中春綺席開，柘枝蠻鼓殷晴雷。","垂樓萬幕青雲合，破浪千帆陣馬來。","未掘雙龍牛斗氣，高懸一榻棟梁材。","連巴控越知何事，珠翠沈檀處處堆。"]', '["滕閣中春綺席开，柘枝蠻鼓殷晴雷。","垂楼万幕青云合，破浪千帆陣马来。","未掘雙龙牛斗氣，高懸一榻棟梁材。","連巴控越知何事，珠翠沈檀处处堆。"]', '诗', 'shi', '', NULL, '懷鍾陵舊遊四首 二 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a36dd569-3de9-454d-8ea2-40cda1c009d4', '懷鍾陵舊遊四首 三', '懷鍾陵旧游四首 三', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["十頃平湖堤柳合，岸秋蘭芷綠纖纖。","一聲明月採蓮女，四面朱樓卷畫簾。","白鷺煙紛光的的，微漣風定翠{氵忄占}{氵忄占}。","斜輝更落西山影，千步虹橋氣象兼。"]', '["十頃平湖堤柳合，岸秋蘭芷綠纖纖。","一声明月採蓮女，四面朱楼卷畫簾。","白鷺煙紛光的的，微漣风定翠{氵忄占}{氵忄占}。","斜輝更落西山影，千步虹橋氣象兼。"]', '诗', 'shi', '', NULL, '懷鍾陵舊遊四首 三 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f57d3221-b9aa-49e5-9c50-21cc46215c8c', '懷鍾陵舊遊四首 四', '懷鍾陵旧游四首 四', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["控壓平江十萬家，秋來江靜鏡新磨。","城頭晚鼓雷霆後，橋上遊人笑語多。","日落汀痕千里色，月當樓午一聲歌。","昔年行樂穠桃畔，醉與龍沙揀蜀羅。"]', '["控壓平江十万家，秋来江静镜新磨。","城头晚鼓雷霆後，橋上游人笑語多。","日落汀痕千里色，月當楼午一声歌。","昔年行乐穠桃畔，醉與龙沙揀蜀羅。"]', '诗', 'shi', '', NULL, '懷鍾陵舊遊四首 四 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63a80b35-d8ea-48ef-af36-7810c2d82fe0', '臺城曲二首 一', '台城曲二首 一', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["整整復斜斜，隨旗簇晚沙。","門外韓擒虎，樓頭張麗華。","誰憐容足地，却羨井中鼃。"]', '["整整复斜斜，隨旗簇晚沙。","门外韓擒虎，楼头張丽华。","誰怜容足地，却羨井中鼃。"]', '诗', 'shi', '', NULL, '臺城曲二首 一 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2059adb6-6df8-4339-aaa6-19918cc6f9aa', '臺城曲二首 二', '台城曲二首 二', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["王頒兵勢急，鼓下坐蠻奴。","瀲灩倪塘水，叉牙出骨鬚。","乾蘆一炬火，回首是平蕪。"]', '["王頒兵勢急，鼓下坐蠻奴。","瀲灩倪塘水，叉牙出骨鬚。","乾蘆一炬火，回首是平蕪。"]', '诗', 'shi', '', NULL, '臺城曲二首 二 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f2c9620-79c0-4929-adc4-8d22a8f400fc', '江上雨寄崔碣', '江上雨寄崔碣', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["春半平江雨，圓文破蜀羅。","聲眠篷底客，寒濕釣來蓑。","暗澹遮山遠，空濛著柳多。","此時懷舊恨，相望意如何。"]', '["春半平江雨，圓文破蜀羅。","声眠篷底客，寒濕釣来蓑。","暗澹遮山远，空濛著柳多。","此时懷旧恨，相望意如何。"]', '诗', 'shi', '', NULL, '江上雨寄崔碣 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6161b416-2cc1-482e-87bf-824be6bc84a0', '罷鍾陵幕吏十三年來泊湓浦感舊爲詩', '罷鍾陵幕吏十三年来泊湓浦感旧爲诗', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["青梅雨中熟，檣倚酒旗邊。","故國殘春夢，孤舟一褐眠。","搖搖遠堤柳，暗暗十程煙。","南奏鐘陵道，無因似昔年。"]', '["青梅雨中熟，檣倚酒旗邊。","故国殘春梦，孤舟一褐眠。","搖搖远堤柳，暗暗十程煙。","南奏鐘陵道，無因似昔年。"]', '诗', 'shi', '', NULL, '罷鍾陵幕吏十三年來泊湓浦感舊爲詩 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afc80a09-19c1-466c-aeda-9a90b0b0ff3f', '商山麻澗', '商山麻澗', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["雲光嵐彩四面合，柔柔垂柳十餘家。","雉飛鹿過芳草遠，牛巷雞塒春日斜。","秀眉老父對罇酒，蒨袖女兒簪野花。","征車自念塵土計，惆悵溪邊書細沙。"]', '["云光嵐彩四面合，柔柔垂柳十餘家。","雉飞鹿過芳草远，牛巷雞塒春日斜。","秀眉老父对罇酒，蒨袖女兒簪野花。","征车自念塵土計，惆悵溪邊书細沙。"]', '诗', 'shi', '', NULL, '商山麻澗 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78fb5437-65d1-4935-9c9f-c39965efad1d', '商山富水驛', '商山富水驛', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["益戇由來未覺賢，終須南去弔湘川。","當時物議朱雲小，後代聲華白日懸。","邪佞每思當面唾，清貧長欠一杯錢。","驛名不合輕移改，留警朝天者惕然。"]', '["益戇由来未覺賢，終須南去弔湘川。","當时物議朱云小，後代声华白日懸。","邪佞每思當面唾，清貧长欠一杯錢。","驛名不合轻移改，留警朝天者惕然。"]', '诗', 'shi', '', NULL, '商山富水驛 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aabd4bc3-4975-4d76-a91a-88b324791261', '丹水', '丹水', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["何事苦縈迴，離腸不自裁。","恨身隨夢去，春態逐雲來。","沈定藍光徹，喧盤粉浪開。","翠巖三百尺，誰作子陵臺。"]', '["何事苦縈迴，離腸不自裁。","恨身隨梦去，春態逐云来。","沈定藍光徹，喧盤粉浪开。","翠巖三百尺，誰作子陵台。"]', '诗', 'shi', '', NULL, '丹水 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71613d6e-3c46-4916-91b1-2f2bdb65cc30', '題武關', '題武关', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["碧溪留我武關東，一笑懷王跡自窮。","鄭袖嬌嬈酣似醉，屈原憔悴去如蓬。","山墻谷塹依然在，弱吐強吞盡已空。","今日聖神家四海，戌旗長卷夕陽中。"]', '["碧溪留我武关东，一笑懷王跡自窮。","鄭袖嬌嬈酣似醉，屈原憔悴去如蓬。","山墻谷塹依然在，弱吐強吞尽已空。","今日聖神家四海，戌旗长卷夕陽中。"]', '诗', 'shi', '', NULL, '題武關 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e030eda-3a52-46ea-ad33-40137058f623', '除官赴闕商山道中絕句', '除官赴闕商山道中絕句', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["水疊鳴珂樹如帳，長楊春殿九門珂。","我來惆悵不自決，欲去欲住終如何。"]', '["水叠鳴珂樹如帳，长楊春殿九门珂。","我来惆悵不自決，欲去欲住終如何。"]', '诗', 'shi', '', NULL, '除官赴闕商山道中絕句 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bae49af-8404-43ad-9365-8fba6e888bed', '漢江', '漢江', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["溶溶漾漾白鷗飛，綠淨春深好染衣。","南去北來人自老，夕陽長送釣船歸。"]', '["溶溶漾漾白鷗飞，綠淨春深好染衣。","南去北来人自老，夕陽长送釣船归。"]', '诗', 'shi', '', NULL, '漢江 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('723e51b8-cea0-4ce3-adac-f20fda3b54d5', '襄陽雪夜感懷', '襄陽雪夜感懷', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["往事起獨念，飄然自不勝。","前灘急夜響，密雪映寒燈。","的的三年夢，迢迢一綫緪。","明朝楚山上，莫上最高層。"]', '["往事起独念，飄然自不勝。","前灘急夜响，密雪映寒灯。","的的三年梦，迢迢一綫緪。","明朝楚山上，莫上最高層。"]', '诗', 'shi', '', NULL, '襄陽雪夜感懷 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f18d8018-cb67-494d-9b0e-831b3558756a', '詠歌聖德遠懷天寶因題關亭長句四韻', '詠歌聖德远懷天寶因題关亭长句四韻', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["聖敬文思業太平，海寰天下唱歌行。","秋來氣勢洪河壯，霜後精神泰華獰。","廣德者強朝萬國，用賢無敵是長城。","君王若悟治安論，安史何人敢弄兵。"]', '["聖敬文思業太平，海寰天下唱歌行。","秋来氣勢洪河壯，霜後精神泰华獰。","廣德者強朝万国，用賢無敵是长城。","君王若悟治安論，安史何人敢弄兵。"]', '诗', 'shi', '', NULL, '詠歌聖德遠懷天寶因題關亭長句四韻 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efab3f0d-4e53-4277-b4cd-9fd3b89019a4', '途中作', '途中作', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["綠樹南陽道，千峰勢遠隨。","碧溪風澹態，芳樹雨餘姿。","野渡雲初暖，征人袖半垂。"]', '["綠樹南陽道，千峰勢远隨。","碧溪风澹態，芳樹雨餘姿。","野渡云初暖，征人袖半垂。"]', '诗', 'shi', '', NULL, '途中作 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b809e73b-f524-4922-8e14-9fe0c0348268', '重到襄陽哭亡友韋壽朋', '重到襄陽哭亡友韋壽朋', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["故人墳樹立秋風，伯道無兒跡更空。","重到笙歌分散地，隔江吹笛月明中。"]', '["故人墳樹立秋风，伯道無兒跡更空。","重到笙歌分散地，隔江吹笛月明中。"]', '诗', 'shi', '', NULL, '重到襄陽哭亡友韋壽朋 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c93c162-d424-4d91-b71b-7c9b81713b8c', '赤壁', '赤壁', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["折戟沈沙鐵未銷，自將磨洗認前朝。","東風不與周郎便，銅雀春深鏁二喬。"]', '["折戟沈沙鐵未銷，自將磨洗認前朝。","东风不與周郎便，銅雀春深鏁二喬。"]', '诗', 'shi', '', NULL, '赤壁 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc64fa88-7231-45a4-acfb-20601e9d8440', '雲夢澤', '云梦澤', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["日旗龍斾想飄揚，一索功高縛楚王。","直是超然五湖客，未如終始郭汾陽。"]', '["日旗龙斾想飄揚，一索功高縛楚王。","直是超然五湖客，未如終始郭汾陽。"]', '诗', 'shi', '', NULL, '雲夢澤 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ff7d3b9-9b28-4293-8fde-aae03e263d65', '除官行至昭應聞友人出官因寄', '除官行至昭應闻友人出官因寄', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["賤子來千里，明公去一麾。","可能休涕淚，豈獨感恩知。","草木窮秋後，山川落照時。","如何望故國，驅馬却遲遲。"]', '["賤子来千里，明公去一麾。","可能休涕泪，豈独感恩知。","草木窮秋後，山川落照时。","如何望故国，驱马却遲遲。"]', '诗', 'shi', '', NULL, '除官行至昭應聞友人出官因寄 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7879bd00-f62e-4030-9c0e-776e629fefdf', '寄浙東韓八評事', '寄浙东韓八評事', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["一笑五雲溪上舟，跳丸日月十經秋。","鬢衰酒減欲誰泥，跡辱魂慙好自尤。","夢寐幾回迷蛺蝶，文章應解伴牢愁。","無窮塵土無聊事，不得清言解不休。"]', '["一笑五云溪上舟，跳丸日月十經秋。","鬢衰酒減欲誰泥，跡辱魂慙好自尤。","梦寐幾回迷蛺蝶，文章應解伴牢愁。","無窮塵土無聊事，不得清言解不休。"]', '诗', 'shi', '', NULL, '寄浙東韓八評事 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8de30193-fba7-4aef-9ff9-c3726a22104d', '泊秦淮', '泊秦淮', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["煙籠寒水月籠沙，夜泊秦淮近酒家。","商女不知亡國恨，隔江猶唱後庭花。"]', '["煙籠寒水月籠沙，夜泊秦淮近酒家。","商女不知亡国恨，隔江猶唱後庭花。"]', '诗', 'shi', '', NULL, '泊秦淮 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12f3e91e-1c38-487b-a645-bbf19ac943ae', '秋浦途中', '秋浦途中', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["蕭蕭山路窮秋雨，淅淅溪風一岸蒲。","爲問寒沙新到雁，來時還下杜陵無。"]', '["蕭蕭山路窮秋雨，淅淅溪风一岸蒲。","爲问寒沙新到雁，来时還下杜陵無。"]', '诗', 'shi', '', NULL, '秋浦途中 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5029a80b-731c-43a4-a302-23920b4c64dd', '題桃花夫人廟', '題桃花夫人廟', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["細腰宮裏露桃新，脉脉無言度幾春。","至竟息亡緣底事，可憐金谷墜樓人。"]', '["細腰宮裏露桃新，脉脉無言度幾春。","至竟息亡緣底事，可怜金谷墜楼人。"]', '诗', 'shi', '', NULL, '題桃花夫人廟 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fb652c9-c48c-4a0b-bf5a-250c2ecd52a5', '初春有感寄歙州邢員外', '初春有感寄歙州邢員外', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["雪漲前溪水，啼聲已繞灘。","梅衰未減態，春嫩不禁寒。","跡去夢一覺，年來事百般。"]', '["雪漲前溪水，啼声已繞灘。","梅衰未減態，春嫩不禁寒。","跡去梦一覺，年来事百般。"]', '诗', 'shi', '', NULL, '初春有感寄歙州邢員外 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30d52eda-5bb3-4e60-847d-9cef36f891cb', '書懷寄中朝往還', '书懷寄中朝往還', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["平生自許少塵埃，爲吏塵中勢自迴。","朱紱久慙官借與，白題還嘆老將來。","須知世路難輕進，豈是君門不大開。","霄漢幾多同學伴，可憐頭角盡卿材。"]', '["平生自許少塵埃，爲吏塵中勢自迴。","朱紱久慙官借與，白題還嘆老將来。","須知世路难轻進，豈是君门不大开。","霄漢幾多同学伴，可怜头角尽卿材。"]', '诗', 'shi', '', NULL, '書懷寄中朝往還 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('948e4f5f-bab8-40fe-9bd6-5d0147208933', '寄崔鈞', '寄崔鈞', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["緘書報子玉，爲我謝平津。","自愧掃門士，誰爲乞火人。","詞臣陪羽獵，戰將騁騏驎。","兩地差池恨，江汀醉送君。"]', '["緘书報子玉，爲我謝平津。","自愧掃门士，誰爲乞火人。","词臣陪羽獵，戰將騁騏驎。","兩地差池恨，江汀醉送君。"]', '诗', 'shi', '', NULL, '寄崔鈞 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cda8e61-fac0-4c14-ad84-72d7318dd31d', '初春雨中舟次和州橫江裴使君見迎李趙二秀才同來因書四韻兼寄江南許渾先輩', '初春雨中舟次和州橫江裴使君见迎李趙二秀才同来因书四韻兼寄江南許渾先輩', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["芳草渡頭微雨時，萬株楊柳拂波垂。","蒲根水暖雁初浴，梅徑香寒蜂未知。","辭客倚風吟暗淡，使君迴馬濕旌旗。","江南仲蔚多情調，悵望春陰幾首詩。"]', '["芳草渡头微雨时，万株楊柳拂波垂。","蒲根水暖雁初浴，梅徑香寒蜂未知。","辞客倚风吟暗淡，使君迴马濕旌旗。","江南仲蔚多情調，悵望春陰幾首诗。"]', '诗', 'shi', '', NULL, '初春雨中舟次和州橫江裴使君見迎李趙二秀才同來因書四韻兼寄江南許渾先輩 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9150feb-1af5-47f2-a858-4a84afec8569', '和州絕句', '和州絕句', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["江湖醉渡十年春，牛渚山邊六問津。","歷陽前事知何實，高位紛紛見陷人。"]', '["江湖醉渡十年春，牛渚山邊六问津。","歷陽前事知何實，高位紛紛见陷人。"]', '诗', 'shi', '', NULL, '和州絕句 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce45b6ae-176c-44be-834e-95f1f4cc2f92', '題烏江亭', '題烏江亭', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["勝敗兵家事不期，包羞忍恥是男兒。","江東子弟多才俊，卷土重來未可知。"]', '["勝敗兵家事不期，包羞忍恥是男兒。","江东子弟多才俊，卷土重来未可知。"]', '诗', 'shi', '', NULL, '題烏江亭 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73a0e38b-f3c6-456c-9120-79a385acbde6', '題橫江館', '題橫江館', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["孫家兄弟晉龍驤，馳騁功名業帝王。","至竟江山誰是主，苔磯空屬釣魚郎。"]', '["孫家兄弟晉龙驤，驰騁功名業帝王。","至竟江山誰是主，苔磯空屬釣鱼郎。"]', '诗', 'shi', '', NULL, '題橫江館 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10a4bf8c-caed-42a0-8ae2-9be9ac847b94', '寄澧州張舍人笛', '寄澧州張舍人笛', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["髪勻肉好生春嶺，截玉鑽星寄使君。","檀的染時痕半月，落梅飄處響穿雲。","樓中威鳳傾冠聽，沙上驚鴻掠水分。","遙想紫泥封詔罷，夜深應隔禁墻聞。"]', '["髪勻肉好生春嶺，截玉鑽星寄使君。","檀的染时痕半月，落梅飄处响穿云。","楼中威鳳傾冠听，沙上驚鴻掠水分。","遙想紫泥封詔罷，夜深應隔禁墻闻。"]', '诗', 'shi', '', NULL, '寄澧州張舍人笛 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('146f2975-7439-4e91-b13f-d9f1128ecd4b', '寄揚州韓綽判官', '寄揚州韓綽判官', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["青山隱隱水迢迢，秋盡江南草木凋。","二十四橋明月夜，玉人何處教吹簫。"]', '["青山隐隐水迢迢，秋尽江南草木凋。","二十四橋明月夜，玉人何处教吹簫。"]', '诗', 'shi', '', NULL, '寄揚州韓綽判官 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1675d33-d1f9-45de-b62d-248b68ebd95a', '送李羣玉赴舉', '送李羣玉赴舉', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["故人別來面如雪，一榻拂雲秋影中。","玉白花紅三百首，五陵誰唱與春風。"]', '["故人別来面如雪，一榻拂云秋影中。","玉白花紅三百首，五陵誰唱與春风。"]', '诗', 'shi', '', NULL, '送李羣玉赴舉 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('daea041a-e25e-4e84-8259-6ea57f41d7bd', '送薛種遊湖南', '送薛種游湖南', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["賈傅松醪酒，秋來美更香。","憐君片雲思，一去遶瀟湘。"]', '["賈傅松醪酒，秋来美更香。","怜君片云思，一去遶瀟湘。"]', '诗', 'shi', '', NULL, '送薛種遊湖南 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7845e2e-507e-447c-88dc-81fa48ebe533', '題壽安縣甘棠館御溝', '題壽安縣甘棠館御溝', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["一渠東注芳華苑，苑鏁池塘百歲空。","水殿半傾蟾口澀，爲誰流下蓼花中。"]', '["一渠东注芳华苑，苑鏁池塘百歲空。","水殿半傾蟾口澀，爲誰流下蓼花中。"]', '诗', 'shi', '', NULL, '題壽安縣甘棠館御溝 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9d1f98c-aa7c-47ab-8c78-22435044a3ac', '汴河懷古', '汴河懷古', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["錦纜龍舟隋煬帝，平臺複道漢梁王。","遊人閑起前朝念，折柳孤吟斷殺腸。"]', '["錦纜龙舟隋煬帝，平台複道漢梁王。","游人闲起前朝念，折柳孤吟斷殺腸。"]', '诗', 'shi', '', NULL, '汴河懷古 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7c1509b-e03c-4a52-a794-15fd89bb2e01', '汴河阻凍', '汴河阻凍', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["千里長河初凍時，玉珂瑤珮響參差。","浮生却似冰底水，日夜東流人不知。"]', '["千里长河初凍时，玉珂瑤珮响參差。","浮生却似冰底水，日夜东流人不知。"]', '诗', 'shi', '', NULL, '汴河阻凍 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf9aae5e-6233-4d81-a97a-b8d807856646', '酬張祜處士見寄長句四韻', '酬張祜处士见寄长句四韻', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["七子論詩誰似公，曹劉須在指揮中。","薦衡昔日知文舉，乞火無人作蒯通。","北極樓臺長挂夢，西江波浪遠吞空。","可憐故國三千里，虛唱歌詞滿六宮。"]', '["七子論诗誰似公，曹劉須在指揮中。","薦衡昔日知文舉，乞火無人作蒯通。","北極楼台长挂梦，西江波浪远吞空。","可怜故国三千里，虛唱歌词满六宮。"]', '诗', 'shi', '', NULL, '酬張祜處士見寄長句四韻 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63c2eec6-c998-4c11-8a77-858c8dd62cee', '寄宣州鄭諫議', '寄宣州鄭諫議', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["大夫官重醉江東，瀟灑名儒振古風。","文石陛前辭聖主，碧雲天外作冥鴻。","五言寧謝顏光祿，百歲須齊衛武公。","再拜宜同丈人行，過庭交分有無同。"]', '["大夫官重醉江东，瀟灑名儒振古风。","文石陛前辞聖主，碧云天外作冥鴻。","五言寧謝顏光祿，百歲須齊衛武公。","再拜宜同丈人行，過庭交分有無同。"]', '诗', 'shi', '', NULL, '寄宣州鄭諫議 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd95b67d-b48a-48b5-86d7-9013581bb1f8', '題元處士高亭', '題元处士高亭', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["水接西江天外聲，小齋松影拂雲平。","何人教我吹長笛，與倚春風弄月明。"]', '["水接西江天外声，小斋松影拂云平。","何人教我吹长笛，與倚春风弄月明。"]', '诗', 'shi', '', NULL, '題元處士高亭 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('537a4e19-aa23-4606-8bd1-f1a3a383582e', '鄭瓘協律', '鄭瓘協律', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["廣文遺韻留樗散，雞犬圖書共一船。","自說江湖不歸事，阻風中酒過年年。"]', '["廣文遺韻留樗散，雞犬圖书共一船。","自说江湖不归事，阻风中酒過年年。"]', '诗', 'shi', '', NULL, '鄭瓘協律 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c91696b5-4487-4bb7-9a31-2c08bbf65b31', '和野人殷潛之題籌筆驛十四韻', '和野人殷潛之題籌笔驛十四韻', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["三吳裂婺女，九錫獄孤兒。","霸主業未半，本朝心是誰。","永安宮受詔，籌筆驛沈思。","畫地乾坤在，濡毫勝負知。","艱難同草創，得失計毫釐。","寂默經千慮，分明渾一期。","川流縈智思，山聳助扶持。","慷慨匡時畧，從容問罪師。","褒中秋鼓角，渭曲晚旌旗。","仗義懸無敵，鳴攻故有辭。","若非天奪去，豈復慮能支。","子夜星纔落，鴻毛鼎便移。","郵亭世自換，白日事長垂。","何處躬耕者，猶題殄瘁詩。"]', '["三吳裂婺女，九錫獄孤兒。","霸主業未半，本朝心是誰。","永安宮受詔，籌笔驛沈思。","畫地乾坤在，濡毫勝負知。","艱难同草創，得失計毫釐。","寂默經千慮，分明渾一期。","川流縈智思，山聳助扶持。","慷慨匡时畧，從容问罪師。","褒中秋鼓角，渭曲晚旌旗。","仗義懸無敵，鳴攻故有辞。","若非天奪去，豈复慮能支。","子夜星纔落，鴻毛鼎便移。","郵亭世自換，白日事长垂。","何处躬耕者，猶題殄瘁诗。"]', '诗', 'shi', '', NULL, '和野人殷潛之題籌筆驛十四韻 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2870b27-aad2-4db9-8dcf-c0cf664032ea', '重題絕句一首', '重題絕句一首', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["郵亭寄人世，人世寄郵亭。","何如自籌度，鴻路有冥冥。"]', '["郵亭寄人世，人世寄郵亭。","何如自籌度，鴻路有冥冥。"]', '诗', 'shi', '', NULL, '重題絕句一首 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34bb4ecb-16aa-46dd-b6f0-bf461ee71b86', '送陸洿郎中棄官東歸', '送陸洿郎中棄官东归', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["少微星動照春雲，魏闕衡門路自分。","倏去忽來應有意，世間塵土謾疑君。"]', '["少微星动照春云，魏闕衡门路自分。","倏去忽来應有意，世间塵土謾疑君。"]', '诗', 'shi', '', NULL, '送陸洿郎中棄官東歸 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6015cfb-c874-426d-831f-2b43f4c355b5', '寄珉笛與宇文舍人', '寄珉笛與宇文舍人', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["調高銀字聲還側，物比柯亭韻校奇。","寄與玉人天上去，桓將軍見不教吹。"]', '["調高銀字声還側，物比柯亭韻校奇。","寄與玉人天上去，桓將軍见不教吹。"]', '诗', 'shi', '', NULL, '寄珉笛與宇文舍人 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a8ecdaf-bc64-4834-b6bd-12e6ac2e0454', '寄內兄和州崔員外十二韻', '寄內兄和州崔員外十二韻', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["歷陽崔太守，何日不含情。","恩義同鍾李，塤篪實弟兄。","光塵能混合，擘畫最分明。","臺閣仁賢譽，閨門孝友聲。","西方像教毀，南海繡衣行。","金橐寧迴顧，珠簟肯一棖。","秪宜裁密詔，何自取專城。","進退無非道，徊翔必有名。","好風初婉軟，離思苦縈盈。","金馬舊遊貴，桐廬春水生。","雨侵寒牖夢，梅引凍醪傾。","共祝中興主，高歌唱太平。"]', '["歷陽崔太守，何日不含情。","恩義同鍾李，塤篪實弟兄。","光塵能混合，擘畫最分明。","台閣仁賢譽，閨门孝友声。","西方像教毀，南海繡衣行。","金橐寧迴顧，珠簟肯一棖。","秪宜裁密詔，何自取專城。","進退無非道，徊翔必有名。","好风初婉軟，離思苦縈盈。","金马旧游貴，桐廬春水生。","雨侵寒牖梦，梅引凍醪傾。","共祝中兴主，高歌唱太平。"]', '诗', 'shi', '', NULL, '寄內兄和州崔員外十二韻 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2eadd251-6ddc-4e50-ba28-602207029aaa', '遣興', '遣兴', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["鏡弄白髭鬚，如何作老夫。","浮生長勿勿，兒小且嗚嗚。","忍過事堪喜，泰來憂勝無。","治平心徑熟，不遣有窮途。"]', '["镜弄白髭鬚，如何作老夫。","浮生长勿勿，兒小且嗚嗚。","忍過事堪喜，泰来憂勝無。","治平心徑熟，不遣有窮途。"]', '诗', 'shi', '', NULL, '遣興 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('922beb25-8b04-4750-b645-8374d4f8fd03', '早秋', '早秋', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["疎雨洗空曠，秋標驚意新。","大熱去酷吏，清風來故人。","尊酒酌未酌，晚花嚬不嚬。","銖秤與縷雪，誰覺老陳陳。"]', '["疎雨洗空曠，秋標驚意新。","大熱去酷吏，清风来故人。","尊酒酌未酌，晚花嚬不嚬。","銖秤與縷雪，誰覺老陳陳。"]', '诗', 'shi', '', NULL, '早秋 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e74b915f-c7f9-4dda-a24d-937c88208020', '秋思', '秋思', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["熱去解鉗釱，飄蕭秋半時。","微雨池塘見，好風襟袖知。","髪短梳未足，枕涼閑且欹。","平生分過此，何事不參差。"]', '["熱去解鉗釱，飄蕭秋半时。","微雨池塘见，好风襟袖知。","髪短梳未足，枕涼闲且欹。","平生分過此，何事不參差。"]', '诗', 'shi', '', NULL, '秋思 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd17e0fb-67dd-48d6-83b0-56acff5988c8', '途中一絕', '途中一絕', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["鏡中絲髪悲來慣，衣上塵痕拂漸難。","惆悵江湖釣竿手，却遮西日向長安。"]', '["镜中絲髪悲来慣，衣上塵痕拂漸难。","惆悵江湖釣竿手，却遮西日向长安。"]', '诗', 'shi', '', NULL, '途中一絕 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d2ede80-37d9-4a34-be93-9fce568c910c', '春盡途中', '春尽途中', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["田園不事來遊宦，故國誰教爾別離。","獨倚關亭還把酒，一年春盡送春詩。"]', '["田园不事来游宦，故国誰教爾別離。","独倚关亭還把酒，一年春尽送春诗。"]', '诗', 'shi', '', NULL, '春盡途中 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4acd9b4-09e3-4810-a9fd-9150c7dac5b7', '題村舍', '題村舍', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["三樹稚桑春未到，扶床乳女午啼飢。","潛銷暗鑠歸何處，萬指侯家自不知。"]', '["三樹稚桑春未到，扶床乳女午啼飢。","潛銷暗鑠归何处，万指侯家自不知。"]', '诗', 'shi', '', NULL, '題村舍 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07c56081-1024-424f-965b-c3d127864bc4', '代人寄遠六言二首 一', '代人寄远六言二首 一', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["河橋酒斾風軟，候館梅花雪嬌。","宛陵樓上瞪目，我郎何處情饒。"]', '["河橋酒斾风軟，候館梅花雪嬌。","宛陵楼上瞪目，我郎何处情饒。"]', '诗', 'shi', '', NULL, '代人寄遠六言二首 一 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49d60d9c-f57f-4e60-87d4-3b45e0ccd2bb', '代人寄遠六言二首 二', '代人寄远六言二首 二', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["繡領任垂蓬髻，丁香閑結春梢。","賸肯新年歸否，江南綠草迢迢。"]', '["繡領任垂蓬髻，丁香闲結春梢。","賸肯新年归否，江南綠草迢迢。"]', '诗', 'shi', '', NULL, '代人寄遠六言二首 二 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36f57a15-2a27-4532-975c-161b1d7a1e58', '閨情', '閨情', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["娟娟却月眉，新鬢學鵶飛。","暗砌勻檀粉，晴窓畫夾衣。","袖紅垂寂寞，眉黛歛衣稀。","還向長陵去，今宵歸不歸。"]', '["娟娟却月眉，新鬢学鵶飞。","暗砌勻檀粉，晴窓畫夾衣。","袖紅垂寂寞，眉黛歛衣稀。","還向长陵去，今宵归不归。"]', '诗', 'shi', '', NULL, '閨情 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8060dc9f-b2c9-4ccd-9279-0d53bca98c64', '舊遊', '旧游', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["閑吟芍藥詩，惆望久嚬眉。","盼眄迴眸遠，纖衫整髻遲。","重尋春晝夢，笑把淺花枝。","小市長陵住，非郎誰得知。"]', '["闲吟芍藥诗，惆望久嚬眉。","盼眄迴眸远，纖衫整髻遲。","重尋春晝梦，笑把淺花枝。","小市长陵住，非郎誰得知。"]', '诗', 'shi', '', NULL, '舊遊 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('130fca6a-c2b7-4b57-beee-768e935a0338', '寄遠', '寄远', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["隻影隨驚鴈，單棲鏁畫籠。","向春羅袖薄，誰念舞臺風。"]', '["隻影隨驚鴈，單棲鏁畫籠。","向春羅袖薄，誰念舞台风。"]', '诗', 'shi', '', NULL, '寄遠 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f5d62ed-875d-40ac-88b1-c6336b59ab5b', '簾', '簾', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["徒云逢剪削，豈謂見偏裝。","鳳節輕雕日，鸞花薄餙香。","問屏何屈曲，憐帳解周防。","下漬金階露，斜分碧瓦霜。","沈沈伴春夢，寂寂侍華堂。","誰見昭陽殿，真珠十二行。"]', '["徒云逢剪削，豈謂见偏裝。","鳳節轻雕日，鸾花薄餙香。","问屏何屈曲，怜帳解周防。","下漬金階露，斜分碧瓦霜。","沈沈伴春梦，寂寂侍华堂。","誰见昭陽殿，真珠十二行。"]', '诗', 'shi', '', NULL, '簾 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a1fd7c9-1dc8-4ac5-8058-5aa386dc1856', '寄題甘露寺北軒', '寄題甘露寺北軒', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["曾向蓬萊宮裏行，北軒闌檻最留情。","孤高堪弄桓伊笛，縹緲宜聞子晉笙。","天接海門秋水色，煙籠隋苑暮鐘聲。","他年會著荷衣去，不向山僧說姓名。"]', '["曾向蓬萊宮裏行，北軒闌檻最留情。","孤高堪弄桓伊笛，縹緲宜闻子晉笙。","天接海门秋水色，煙籠隋苑暮鐘声。","他年會著荷衣去，不向山僧说姓名。"]', '诗', 'shi', '', NULL, '寄題甘露寺北軒 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0cf18c5-08ff-47c9-8930-f7d58927d9a4', '題青雲館', '題青云館', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["虬蟠千仞劇羊腸，天府由來百二強。","四皓有芝輕漢祖，張儀無地與懷王。","雲連帳影蘿陰合，枕遶泉聲客夢涼。","深處會容高尚者，水苗三頃百株桑。"]', '["虬蟠千仞劇羊腸，天府由来百二強。","四皓有芝轻漢祖，張儀無地與懷王。","云連帳影蘿陰合，枕遶泉声客梦涼。","深处會容高尚者，水苗三頃百株桑。"]', '诗', 'shi', '', NULL, '題青雲館 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0860fbf-265b-4eb4-a4e3-ff3b82b3aa59', '正初奉酬歙州刺史邢羣', '正初奉酬歙州刺史邢羣', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["翠巖千尺倚溪斜，曾得嚴光作釣家。","越嶂遠分丁字水，臘梅遲見二年花。","明時刀尺君須用，幽處田園我有涯。","一壑風烟陽羨里，解龜休去路非賒。"]', '["翠巖千尺倚溪斜，曾得嚴光作釣家。","越嶂远分丁字水，臘梅遲见二年花。","明时刀尺君須用，幽处田园我有涯。","一壑风烟陽羨里，解龟休去路非賒。"]', '诗', 'shi', '', NULL, '正初奉酬歙州刺史邢羣 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7733c279-f1f6-438c-87a8-f494fa8e82c7', '江上偶見絕句', '江上偶见絕句', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["楚江寒食橘花時，野渡臨風駐綵旗。","草色連雲人去住，水紋如縠燕差池。"]', '["楚江寒食橘花时，野渡臨风駐綵旗。","草色連云人去住，水紋如縠燕差池。"]', '诗', 'shi', '', NULL, '江上偶見絕句 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb1ab7cc-2152-4b7a-97aa-adb03543814d', '題木蘭廟', '題木蘭廟', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["彎弓征戰作男兒，夢裏曾經與畫眉。","幾度思歸還把酒，拂雲堆上祝明妃。"]', '["彎弓征戰作男兒，梦裏曾經與畫眉。","幾度思归還把酒，拂云堆上祝明妃。"]', '诗', 'shi', '', NULL, '題木蘭廟 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2af955e5-da79-4ddc-8d15-db5a1e05c208', '入商山', '入商山', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["早入商山百里雲，藍溪橋下水聲分。","流水舊聲人舊耳，此迴嗚咽不堪聞。"]', '["早入商山百里云，藍溪橋下水声分。","流水旧声人旧耳，此迴嗚咽不堪闻。"]', '诗', 'shi', '', NULL, '入商山 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e750cf9-5dd7-4949-92b7-4fce2ed39cc5', '偶題', '偶題', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["甘羅昔作秦丞相，子政曾爲漢輦郎。","千載更逢王侍讀，當時還道有文章。"]', '["甘羅昔作秦丞相，子政曾爲漢輦郎。","千載更逢王侍读，當时還道有文章。"]', '诗', 'shi', '', NULL, '偶題 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8616c0d-3a21-4d1e-8472-9f2baecd3730', '送盧秀才一絕', '送盧秀才一絕', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["春瀨與烟遠，送君孤櫂開。","潺湲如不改，愁更釣魚來。"]', '["春瀨與烟远，送君孤櫂开。","潺湲如不改，愁更釣鱼来。"]', '诗', 'shi', '', NULL, '送盧秀才一絕 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0658bc9e-eae6-4e6e-9516-10598fe4d89a', '醉題', '醉題', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["金鑷洗霜鬢，銀觥敵露桃。","醉頭扶不起，三丈日還高。"]', '["金鑷洗霜鬢，銀觥敵露桃。","醉头扶不起，三丈日還高。"]', '诗', 'shi', '', NULL, '醉題 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0141cac7-abc2-4371-8cec-4af251222696', '題商山四皓廟一絕', '題商山四皓廟一絕', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["呂氏強梁嗣子柔，我於天性豈恩讐。","南軍不袒左邊袖，四老安劉是滅劉。"]', '["呂氏強梁嗣子柔，我於天性豈恩讐。","南軍不袒左邊袖，四老安劉是滅劉。"]', '诗', 'shi', '', NULL, '題商山四皓廟一絕 杜牧 shi');
